  insert into public.courses (id, university_id, code, title, department, description, source_url, slug) values
    ('238ecbf2-46d6-4d70-99be-f18c026075f7', v_uni_id, 'ACC10040', 'Financial Accounting 1', 'Business', 'This module provides an introduction to financial accounting practices, usage and regulation. In particular, it introduces students to the preparation and interpretation of company financial statements.', 'https://www.ucd.ie/modules/ACC10040', 'acc10040'),
    ('bcd533c0-68d7-49ef-8ddc-f3c64db363a3', v_uni_id, 'ACC10060', 'Introduction to Accounting', 'Business', 'This module is intended for non-business degree students and will provide students with an introduction to financial and management accounting. Among the areas covered are: the nature and purpose of accounting; the users of accounting information; preparation and interpretation of Trading, Profit and Loss Accounts, Balance Sheets; VAT,The purpose of management accounting is to provide information to assist management in making informed decisions and evaluations. Management needs to plan, control and make decisions.', 'https://www.ucd.ie/modules/ACC10060', 'acc10060'),
    ('f0e0e4c3-3835-41d5-ba42-e189ea193887', v_uni_id, 'ACC1071D', 'An Introduction to Financial Accounting Information', 'Business', 'This module deals with the fundamental principles of accounting and reporting and the concepts underlying the preparation of accounts. Candidates will be introduced to the primary financial statements Profit and Loss Account, Balance Sheet and Cash Flow Statement and will learn how to usefully interpret financial statements. This module also introduces candidates to the requirement to conduct an audit and to the contents of the audit report.', 'https://www.ucd.ie/modules/ACC1071D', 'acc1071d'),
    ('841153d7-90a6-42d6-b390-9fcaaea306cf', v_uni_id, 'ACC20010', 'Financial Accounting 2', 'Business', 'Financial Accounting 2 builds on the basic accounting techniques introduced in first-year Accounting and develops students’ understanding and application of financial accounting and reporting. The main areas covered are: 1. Revision of double-entry bookkeeping, trial balances and year-end adjustments, including the preparation of financial statements. 2. The regulatory and conceptual framework underlying financial reporting. 3. The content and interpretation of published annual reports. 4. Preparation and presentation of financial statements in accordance with International Financial Reporting Standards (IFRS). 5. Reporting financial performance, including earnings per share, and an introduction to group financial statements. 6. Recognition, measurement and disclosure issues relating to property, plant and equipment, government grants, inventories, provisions, contingencies and events after the reporting period.', 'https://www.ucd.ie/modules/ACC20010', 'acc20010'),
    ('fb78843d-2388-4063-9e59-d5fc36bb8a41', v_uni_id, 'ACC20020', 'Management Accounting', 'Business', 'Management needs to plan, control and make decisions to achieve organizational objectives. The purpose of management accounting is to assist management in achieving these organizational objectives by providing the relevant financial and non-financial information. Topics to be dealt with range from an understanding of cost behaviour, cost estimation, and cost-volume-profit analysis, through to costing systems including activity-based costing to budgetary planning and control, and standard costing and variance analysis.', 'https://www.ucd.ie/modules/ACC20020', 'acc20020'),
    ('567a3741-5403-40a1-96ae-19b808f80def', v_uni_id, 'ACC20040', 'Business, Media & Corporate Communications', 'Business', 'This module will critically examine the evolution, operation and effects of mass media and its influence over business, markets and capitalism in the 21st century. It will do so with a heavy emphasis on how firms use communications tools to disseminate messages to the external environment. The module seeks to explore mass media, its commercial aims and its intersection with organisations, markets and economic actors. It will examine theoretical approaches to these issues and explore linkages between todays 24/7 ‘always on’ digital media and the more traditional media forms of the past. In addition to this, the module also aims to equip students with the skills to be media literate and effectively communicate themselves across multiple channels in an era of disinformation. The module will also examine how organisations, particularly corporate and government entities, strategically utilise media channels to enhance and defend corporate reputation and to persuade external audiences and important stakeholders. This will be explored via theoretical approaches, but also by looking at global case studies of reputation management, including corporate scandals. The commercial models of mass digital platforms such as Google, TikTok and X will be studied. Also large scale global events such as the Covid-19 Pandemic and the Trump Presidency, and their impact on media and the distribution of information, will also be a focus. A reading list has been provided and students are expected to familiarize themselves with the readings before class, as they will be discussed. In class attendance is vital on this module, as regular in-class exercises and tasks are a key part of the learning.', 'https://www.ucd.ie/modules/ACC20040', 'acc20040'),
    ('1b7f7678-4c1b-4bcb-8957-3bbabdd14061', v_uni_id, 'ACC20050', 'Sustainability Reporting and Analysis', 'Business', 'Sustainability disclosures represent a rapidly evolving aspect of corporate reporting, playing a pivotal role in both internal decision-making processes and external evaluations from capital markets, regulators, and the broader public. This module aims to elucidate the significance of sustainability reporting both from a societal as well as business perspective, highlighting their intrinsic interconnection. Concepts such as materiality will be introduced, and developments around double materiality explored. Sustainability is a broad term with different understandings and definitions. Students will learn about the basics of climate science and the transition the economy will undergo. Climate risks in business will be analysed. While the focus lies on environmental sustainability and key green reporting metrics like greenhouse gas emissions, broader sustainability topics such as gender pay gap reporting and corporate governance will also be touched upon. Students will get an introduction to the concept of ESG and its influence on capital markets. Sustainability relates to data from all business processes and departments in the organization. Non-financial data often comes in different units and formats than financial data. In this module, students will learn how this information can be organized, analysed and presented to provide information for decision makers within and outside of the organization. Students are expected to develop a basic understanding of the current regulatory environment and the difference between voluntary and mandatory disclosure. Students will explore the current state of corporate sustainability reporting. Voluntary nonfinancial disclosure is increasingly popular, with an increasing number of companies providing standalone sustainability reports or integrating sustainability information into their annual reports. This module will equip students with skills to handle related data and analyse reports critically, emphasizing the importance of assessing data quality and credibility of sustainability claims to mitigate risks associated with greenwashing. Lastly, this module will provide an overview of the upcoming regulatory requirements globally and in the EU, and key stakeholders involved in the standard setting processes.', 'https://www.ucd.ie/modules/ACC20050', 'acc20050'),
    ('7fe5e7be-f1ac-4ebe-92ec-eca6cbb3f513', v_uni_id, 'ACC30010', 'Tax in Society', 'Business', 'This module introduces students to the fundamental principles and economics of taxation, alongside their practical application. It examines the key influences shaping the Irish tax system, with an emphasis on developing students’ ability to calculate liabilities under the main tax heads, including Income Tax, Capital Gains Tax, VAT and Corporation Tax.', 'https://www.ucd.ie/modules/ACC30010', 'acc30010'),
    ('28eade03-314a-49ee-b16e-09274c69736e', v_uni_id, 'ACC30020', 'Financial Accounting 3', 'Business', 'This module develops students'' knowledge of financial accounting and reporting by building on foundations laid at Levels 1 and 2. The module aims to improve students'' ability to apply accounting methods to more challenging transactions of companies and for more complex corporate structures than dealt with previously. The module focuses on the financial reporting standards used by EU companies to report financial information. The module also develops students'' ability to critically appraise the financial reporting framework and standards used by companies. Topics covered include the usefulness of financial reporting, i.e. the role of financial reporting in investment and other decision-making; the financial reporting regulatory framework; concepts such as faithful representation (including substance over form) and relevance; preparation of group accounts; accounting for financial instruments, intangible assets, leases, pensions, foreign currencies.', 'https://www.ucd.ie/modules/ACC30020', 'acc30020'),
    ('34b02623-5e3a-4a2f-99f8-2273a914ea39', v_uni_id, 'ACC30030', 'Cost Management', 'Business', 'Cost Management can be defined as the information set that managers need in decision making to ensure that the firm is successful. It includes both financial information about costs and revenues but also relevant non-financial information about quality, customer satisfaction and other critical success factors. Cost Management recognises that costs do not just happen they are caused. Topics covered include the strategic role of Cost Management systems, cost accumulation systems, Cost Management techniques such as activity based costing, customer profitability analysis, cost of quality reporting, target costing, life-cycle costing and bench-marking. The course also includes research findings on Cost-Management systems.', 'https://www.ucd.ie/modules/ACC30030', 'acc30030'),
    ('7debdb58-ebd6-4db1-8124-8cc26e9a6a41', v_uni_id, 'ACC30050', 'Corporate Governance, Company Law and Labour Law', 'Business', 'This module examines the various legal provisions that are applicable to business generally and to accountants in particular. It covers company law and the principles and practice of corporate governance.', 'https://www.ucd.ie/modules/ACC30050', 'acc30050'),
    ('1d848ff1-5f72-40a6-8de1-c5ed78ace3b1', v_uni_id, 'ACC30060', 'Financial Statement Analysis', 'Business', 'Financial statements are relevant to the decisions of many individuals including investors, creditors, consultants, managers, auditors, directors, analysts, regulators and employees. Financial statement analysis is the application of analytical tools and techniques to general purpose financial statements to derive estimates and inferences useful in business decisions. This module aims to develop the student’s business skills and knowledge in the following ways. Investment decisions The module will develop the student’s ability to use financial statements to better understand the firm’s strategy, performance, risks and prospects. Understanding these aspects of the firm is essential for financial analysis, fund management, credit control and the assessment of mergers and acquisitions. Firm valuation and financial modelling This module will develop student’s ability to develop firm valuation models in Excel for firms in a variety of different situations. Students will learn how to incorporate financial statement information in these valuations in a manner consistent with finance theory. Bloomberg at the Deloitte Data Analytics Lab This module will develop student’s ability to use the Bloomberg data service to analyse firm performance and firm value. By the end of the module students should possess a working knowledge of the tools and frameworks necessary to understand, analyse and use financial statements.', 'https://www.ucd.ie/modules/ACC30060', 'acc30060'),
    ('e2caaf27-6bdf-4544-aff2-b1aaa6a051dd', v_uni_id, 'ACM10060', 'Applications of Differential Equations', 'Mathematics & Statistics', 'This course introduces students to the theory of differential equations and dynamical systems and to their many applications as mathematical models. The topics covered prepare the student for more advanced subjects in ordinary differential equations (ODEs), dynamical systems theory, numerical methods and partial differential equations. Course Outline: A) 1st-order ODEs: Direction fields Linear equations: Integrating factor method. Separable equations. Exact equations. B) 2nd-order ODEs: Homogeneous equations: Characteristic equation method (real, complex and double roots). Non-homogeneous equations: Method of undetermined coefficients. Examples: Forced and damped systems, mechanical oscillations, resonances, etc. C) Systems of 2 coupled ODEs: Linear and nonlinear. Phase plane analysis. Critical points and classifications in terms of eigendirections and eigenvalues. Examples: Population models, the tragedy of the commons, epidemic models, etc.', 'https://www.ucd.ie/modules/ACM10060', 'acm10060'),
    ('0e80473a-28b1-4945-ad4e-f039a1e3b25d', v_uni_id, 'AH30010', 'Writings on Art', 'Art History & Cultural Policy', 'This module is only open to art history majors for whom it is compulsory. This module provides an overview of some of the principal trends in writing on art from the pre-modern to the present day. It thus builds upon the thematic modules undertaken in Levels 1 and 2, enabling students to place their cumulative experience in a methodological framework. The course develops students’ understanding of art history as a discipline while importantly positioning it in dialogue with diverse approaches and methods to underscore the interdisciplinary nature of the field. Topics include formalism, connoisseurship, feminism, queer theory, and decoloniality. The module aims to provide students with a theoretical and critical context for their final-year study of art history and to aid them in identifying the ideas that inform their own approaches to the subject. It attunes students to current and emerging approaches to art history.', 'https://www.ucd.ie/modules/AH30010', 'ah30010'),
    ('8e517f75-43ce-4cf6-991f-618c4e03d20b', v_uni_id, 'AH30600', 'From Constantinople to Istanbul: Art, Faith, Politics', 'Art History & Cultural Policy', 'From its ancient beginnings as the town of Byzantion, the city now known as Istanbul has captured the collective imagination of many over the centuries. This module examines the art and the built environment of the city, from its expansion in the Roman period, to its re-foundation as the Byzantine capital Constantinople, to its Ottoman transformation into modern Istanbul. As different groups—Byzantines, Crusaders, Ottomans—took control of the city, they shaped its architecture to proclaim the power and grandeur of their cultures and religions, commissioning magnificent monuments such as the church of Hagia Sophia, the Süleymaniye Mosque, and Topkapi Palace, as well as icon paintings, reliquaries, and manuscripts. The module will allow students to engage with archaeological and literary evidence, bringing to life lost buildings such as the Great Palace and the Church of the Holy Apostles. When possible, class field trips to local collections (the Chester Beatty, the National Gallery, UCD Special Collections) as well as churches in Dublin inspired by Byzantine styles will allow students to see objects associated with the city in person.', 'https://www.ucd.ie/modules/AH30600', 'ah30600'),
    ('799d5c41-acec-4555-9e55-196887a8506c', v_uni_id, 'ARCH10150', 'Anthropology: an introduction', 'Archaeology', 'This module will introduce you to the discipline of anthropology—the study of what it means to be human. Anthropology examines the diversity of human societies across space and time. Anthropology is an interdisciplinary subject that is often divided into ‘four fields’: cultural or social anthropology, biological anthropology, linguistic anthropology, and archaeology. This module provides an overview of anthropology, with a particular focus on biological and cultural anthropology. We will investigate the early history of anthropology and its reliance on ethnographic fieldwork, charting both the trajectory of human evolution and the parameters of the human body. Over the course of the module, we will examine how key facets of human existence such as kinship, ritual and symbolism, gift exchange, and the home are understood in different societies. We will explore different ways of understanding the world and how to make comparisons between these and ask what it means to think anthropologically. A representative list of topics covered from past versions of the module looks something like this: Week 1: What is anthropology? Week 2: The story of human evolution Week 3: Ethnography Week 4: The body Week 5: Inequality Week 6: Exchange Week 7: Kinship Week 8: Hunter-gatherers Week 9: Anthropology of food Week 10: Anthropology of ritual', 'https://www.ucd.ie/modules/ARCH10150', 'arch10150'),
    ('75b8d81b-dee2-45e4-87ba-3b0e5f87d495', v_uni_id, 'ARCH10160', 'The Human Past', 'Archaeology', 'This module introduces the archaeology of the prehistoric and historic world through examining key points in the development of ancient human societies, such as the emergence of Homo sapiens (modern humans) and their spread across all parts of the world; the development of agriculture and the transition from nomadic to settled societies; the invention of metalworking and its relationship to changes in human society; the emergence of early states and empires; and the archaeology of the historical world. Case studies are drawn from across the globe, including Europe, Asia and Africa. We will discuss the importance of a broad range of archaeological evidence (including some famous finds), and the module will outline some of the key ways in which these contribute to our understanding of diverse human societies. Note: No Generative AI content is allowed in the submission for assessments in this module. Have confidence in your own reading, thoughts and voice.', 'https://www.ucd.ie/modules/ARCH10160', 'arch10160'),
    ('4fed6a94-5af7-4e20-a6fc-e0dcbac7588a', v_uni_id, 'ARCH10170', 'Making the Past', 'Archaeology', 'Archaeology is the discipline of things, exploring how people make their own worlds through material culture. This can include houses, personal dress and jewellery, tools and equipment, cooking utensils, amongst many other things. The stories of all things includes the raw materials used to make them, the skills, knowledge, techniques and practices involved in the making, and the use, wear, repair and discard of them into the soil. This module introduces you to how people made things in the past. You will work together as a class in a practical experimental archaeology week, outdoors in the open air, using genuine raw materials (plants, clay, stone, flint, wood, textiles, etc) to make various replicas of archaeological objects. You will make things, and thereby gain genuine personal insights into the material worlds of the past. The module will have 1 introductory lecture at very start of trimester 2, followed by a walking tour of UCD School of Archaeology''s Centre for Experimental Archaeology and Material Culture (CEAMC) at Roebuck. This practical course is then taught over one intensive week indoors and outdoors at UCD School of Archaeology''s Centre for Experimental Archaeology and Material Culture (CEAMC) between Monday 15th and Friday 19th March 2027 (during the Reading/Fieldwork period). CEAMC is UCD School of Archaeology''s experimental archaeological facility on the UCD Campus (in Roebuck district). Do dress for practical outdoors activities in Irish weather. For further information on CEAMC, see weblinks below. UCD CEAMC website is here https://www.ucd.ie/archaeology/ceamc/ UCD CEAMC on YouTube https://www.youtube.com/channel/UCl6r12tTQOtJr-ApBYyGgkw UCD CEAMC on Bluesky https://bsky.app/profile/experimentarchaeol.bsky.social UCD CEAMC on Facebook https://www.facebook.com/groups/UCDExperimentalArchaeology/', 'https://www.ucd.ie/modules/ARCH10170', 'arch10170'),
    ('96901cd9-4e2b-4699-8968-2afb3cdbad8f', v_uni_id, 'ARCH20600', 'Archaeological Science', 'Archaeology', 'Archaeology is a subject that makes use of techniques and approaches from many other disciplines. In recent years, developments in Science have opened up exciting possibilities and allowed us to approach questions that even a few years ago would have seemed impossible. As an archaeologist, understanding and applying these approaches is an increasingly important part of the discipline. Archaeological Science is a wide topic that would be impossible to cover in all of its details in a single 5-credit module. Consequently, the module provides a broad overview of approaches and a more detailed look at how some of these are applied through targeted case studies and themes. These are chosen to show the way in which scientific methods and thinking can add to our understanding of the past. Even if you have no scientific background, you will learn how to appreciate a scientific way of thinking and how it applies to archaeology. The module will help you to confidently read and critique publications and media that rely on scientific research, and you will gain experience in laboratory analysis of archaeological material. No Generative AI content is allowed in the final submission for assessments in this module. You may choose to use Generative AI for brainstorming and generating ideas for improving work, but remember that this can bring you down a confusing and incorrect path. Have confidence in your own reading, thoughts and voice.', 'https://www.ucd.ie/modules/ARCH20600', 'arch20600'),
    ('4d3a2b4d-be6d-4109-a1d1-82308621a3f0', v_uni_id, 'ARCH30500', 'Experiment Archaeology & Ancient Technologies', 'Archaeology', 'Using traditional and social scientific approaches, experimental archaeology investigates how people in the past built and occupied houses, managed and interacted with their landscapes, made objects using sophisticated knowledge of materials and how natural processes have impacted archaeological remains. It also enables us to reflect on past materialities through practical engagement with ancient technologies, which provides us embodied experiences of raw materials, processes and technologies not normally used today. For archaeologists interested in material culture, this module allows us to directly explore how archaeology truly is the “discipline of things”. This module introduces you to experimental archaeology and ancient technologies, through a field school held in Week 0 - the week immediately prior to the start of teaching in Week 1 (Autumn Trimester) at the UCD Centre for Experimental Archaeology and Material Culture, at Roebuck, on the University College Dublin campus. You will participate in a range of practical experiments on houses, stone/flint, pottery, organics, food. You should attend in suitable clothing (boots, rain gear, etc) and bring their own supply of drinking water. You should also bring writing materials (pencil, notebook) and a camera. The module will be primarily assessed by means of a reflective learning journal and a project, whereby you make something and think about it in relation to archaeological evidence. Seminars during trimester will help you design, carry out, and report on your project. NB: The main practical component of this module is taught over a week long field school in Week 0 - the week immediately before the beginning of the Autumn Trimester. Correspondingly, you will need to plan to be on campus and available over this week. If you have specific orientation sessions that you wish to attend during this time please contact the Module Coordinator (brendan.oneill@ucd.ie) and arrangements can be made.', 'https://www.ucd.ie/modules/ARCH30500', 'arch30500'),
    ('c53646e9-2dde-4424-b63a-a07ae3194798', v_uni_id, 'ARCH30700', 'Research Project Preparation', 'Archaeology', 'This module gives you the space to develop a research proposal, that will be the basis for the Research Project module in the following trimester. Through the module you will be developing your topic, the key questions that you will be addressing, the methods that you think you will need to employ and the resources that it might require. The final submission for this module will be the completion of a project proposal form. The form has been based on the types of questions grant awarding bodies would ask you if you were looking for funding. The proposal phase allows a point of critical reflection before you embark on your project and allows for an assessment of whether or not it can proceed or whether it needs to be adapted.', 'https://www.ucd.ie/modules/ARCH30700', 'arch30700'),
    ('20ea18b8-52a4-485d-a0db-f06ccedace02', v_uni_id, 'ARCH30910', 'Roman Imperial Art, Architecture and Political Propaganda; how to spot fake news in the Roman world', 'Archaeology', 'The Roman Empire covers one of the most important and iconic periods of European, North African and Middle Eastern history. The Empire (lasting from the 1st until, arguably, the 5th century AD) extended, at its territorial peak, from the Welsh coastline as far as the Euphrates and from the Scottish border to North Africa. It achieved cultural and political unification on an unprecedented scale. Its military might and administrative rigour enabled a highly-structured system of economic exploitation and cultural appropriation throughout its territorial reach. This module moves thematically and chronologically from the Pax Romana established by Augustus to the rise of imperial cities in northern Africa under Septimius Severus. Themes of peace, triumph and conflict will be viewed through a series of core-and-periphery test cases. Topics covered will include Augustan Peace, The Wars in Judaea, The Spoils of Territorial Expansion under Trajan (looking at Dacia and Parthia), Territorial Consolidation under Hadrian (exploring Rome and Britain) and the Art of Ruling in Absentia (as exemplified by Marcus Aurelius’ reign on the Danube). Students will analyse the Roman conceptualisation of events taking place on the fringe of Empire and the nature of their portrayal at the administrative core in terms of Roman imperial propaganda, political rivalries, "fake news" and the various media used to reach the masses. Imperial propaganda will be investigated through a reading of the most famous imperial architectural designs in Rome which will be tested against archaeological evidence for daily life in the related provinces. The module assumes no prior knowledge of Roman history or archaeology.', 'https://www.ucd.ie/modules/ARCH30910', 'arch30910'),
    ('0152dcd7-c182-4acf-99b5-1accd47696c2', v_uni_id, 'ARCT10010', 'Architectural Design I', 'Architecture, Plan & Env Pol', 'Module Description First Year Architectural Design provides a foundation in the study of architecture and seeks to unlock the creative and intellectual potential of each student. This core programme introduces students to ways of observing, representing, making and thinking about architecture and the environment. Via a series of design projects students explore ideas of space and environmental design. The trimester begins with a close-up investigation of spaces, objects, places, and events and gradually introduces a wider range of constructional, social, cultural and environmental concerns. The work is supported by the development of a broad range of technical and representational skills through a combination of studio work and independent but related Drawing and Making skills workshops. There is a focus on establishing a clear design work method and an understanding of the social and environmental issues posed by the project, including developing an awareness of factors affecting climate change and how the agency of architects has the potential to impact positively on climate. Structure A series of set projects invite design responses across a range of scales employing different media, offering each student the means of developing a work method. These projects involve a combination of both individual and group work. A supporting cultural programme may include a variety of visits to buildings and cultural events during the trimester. Attendance at these events and at all studio sessions is critical to developing a sound work method. The module requires all students to make a collective exhibition of their work at the end of the semester. Approaches to Teaching and Learning Key modes of teaching in this module; studio work to include active/task-based learning, enquiry-based learning including unstructured reading, peer and group work, case-based or precedent study, lectures, reflective writing and student presentations. Emphasis is placed on developing an iterative work method through which variants of a design are projected, investigated and evaluated through drawing overlay and test models. The range of representation skills required include drawing, model, collage and digital techniques. Students will work to reflect, collate, edit and compose their research and design work for presentation and exhibition. The use of AI is not permitted in this module. Submission At the end of module each student is required to submit individual collated and organized physical and digital portfolios. The portfolios include drawings, models, sketches and other studies with a view to demonstrating work process and the required outcomes as well as a critical self-evaluation of the student’s work. Feedback Students are in weekly contact with their tutors in small group meetings and individual tutorials. At these sessions the student''s work is discussed and formative feedback is provided that is focused on positively developing project ideas - it is not intended to grade ideas which are in the process of taking shape. Reviews are scheduled during the trimester at which students will be given an indication of what development is required where a project is underdeveloped. Written feedback is given after the final assessment.', 'https://www.ucd.ie/modules/ARCT10010', 'arct10010'),
    ('40a05012-5b54-40ed-a684-8364850a1064', v_uni_id, 'ARCT10020', 'Architectural Design II', 'Architecture, Plan & Env Pol', 'Module Description This Module will continue work initiated in the first term, focusing on the development and application of observational and technical skills. Exercises will be set to design coherent architectural responses to the constraints and potential of site and brief, examine our relationship to space and understand general principles of material and construction. Students will need to develop a clear process and methodology in their work as well as an understanding of the social and environmental issues posed by the project, including how our agency as architects has the potential to impact positively or negatively on climate change. Structure Working individually or in assigned groups students will carry out project development and research. Student activities are studio based and attendance in studio is mandatory. The project will involve a period of research and survey leading up to an interim review. This is followed by a period of proposition and design to conclude with a final review. Approaches to Teaching and Learning Key modes of teaching in this module; studio work to include active/task-based learning, enquiry-based learning including unstructured reading, peer and group work, case-based or precedent study, lectures, reflective writing and student presentations. Emphasis is placed on developing an iterative work method through which variants of a design are projected, investigated and evaluated through drawing overlay and test models. The range of representation skills required include drawing, model, collage and digital techniques. Students will work to reflect, collate, edit and compose their research and design work for presentation and exhibition. Submission At the end of module each student is required to submit individual, collated and organized physical and digital portfolios. The portfolios should include drawings, models and sketches with a view to demonstrating the required outcomes as well as a critical self-evaluation of the student’s work. Feedback Students are in weekly contact with their tutors in small group meetings. At these sessions the student''s work is discussed and summative feedback is provided that is focused on positively developing project ideas - it is not intended to grade ideas which are in the process of taking shape. Reviews are scheduled during the semester at which students will be given an indication of what development is required where a project is underdeveloped. Written feedback is given after the Interim Review and after the final assessment.', 'https://www.ucd.ie/modules/ARCT10020', 'arct10020'),
    ('f22bec72-f621-426f-a4bb-bbef52fd3754', v_uni_id, 'ARCT10040', 'Architectural Technologies I – Introduction to Building Envelope', 'Architecture, Plan & Env Pol', 'This module introduces Architectural Technologies in their broadest sense including principles and applications in order to provide a foundation for an understanding of the construction methods and performance of a building at a domestic scale. The module will examine in detail the building envelope, focussing on the principles of construction, through a formal lecture series complemented by visits to the Building Laboratory and exercises in Technology Studio. Technology Studio comprises structured projects including technical drawings, analytical models, sketching, simple surveying methods and generic material studies, intended to emphasise the importance of architectural technologies in the creative process of marking architecture. Technology Studio works closely with Design Studio (Architectural Design II ARCT10020) and many of the exercises will require students to consider and develop aspects of their work in Design Studio. The mark in Technology Studio contributes 12% to the overall mark in Design Studio. 60% of the overall grade for this module will be allocated to Technology Studio, 40% of the overall grade will be allocated to a written examination at the end of the trimester. The Technology Studio component must be passed. An in-module resit will be offered for Technology Studio and for the Written Examination.', 'https://www.ucd.ie/modules/ARCT10040', 'arct10040'),
    ('92d9e27e-ecde-4478-8ad6-2c05c26baf3d', v_uni_id, 'ARCT10070', 'Survey I: History and Theory of the Built Environment I', 'Architecture, Plan & Env Pol', 'In its most basic sense, this module is a lecture course that introduces the history of the built environment from antiquity through to the medieval period. But it is much more than that. Its core premise is that the history of architecture is ‘not just history’, but instead a continuously developing visual language that borrows, adapts, shadows and even sometimes appropriates the work of other people and cultures. This course begins with a series of problems and contexts that teaches the student how to observe, describe and analyse buildings, cities and landscapes. Through a mixture of lectures and workshops, we will examine key moments in the history of the built environment. We will not only look at the buildings themselves but also consider how, in many cases, they continue to influence and hold sway on architects in the present day.', 'https://www.ucd.ie/modules/ARCT10070', 'arct10070'),
    ('c3ac6fe2-7623-4abb-a72b-40ea41d1bf3d', v_uni_id, 'ARCT10090', 'Perspectives: History and Theory of the Built Environment II', 'Architecture, Plan & Env Pol', 'This is a continuation of the autumn module (ARCT10070) insofar as it provides a broad overview of major moments in the history of the built environment. Like its sister module, this course engages with architectural theory as well, looking at how buildings and landscapes have shaped perceptions and interpretations of buildings over time. This course begins as the cusp of the modern period, with the early Renaissance, and then travels across both place and time, considering how such things as trade, migration, religion and war have helped (or hindered) the dissemination of architectural ideas.', 'https://www.ucd.ie/modules/ARCT10090', 'arct10090'),
    ('4ae6aeeb-a497-4b09-855c-467ddb9e352e', v_uni_id, 'ARCT10160', 'Drawing & Making', 'Architecture, Plan & Env Pol', 'Pass/Fail (GPA Neutral) The focus of the Drawing & Making module in the Autumn trimester is to introduce and hone skills to support design work happening in parallel in the Architectural Design Studio module. The intention is to expose the students to an array of tools and techniques with the aim that each will find a method of representation that resonates with them while developing fundamental skills. Drawing and Making focuses on the introduction of a range of analogue representational techniques of drawing and model-making by hand. By participating in workshops on ways of seeing, analytical sketching, orthographic representation and model-making skills, students are introduced to a range of representational techniques. Drawing & Making also introduces exercises in structural investigation and materiality where students are challenged to explore the innate properties of various materials. The trimester ends with workshops introducing digital drawing. Drawing & Making is taught in person in Richview. There is one field trip to Dublin city centre and one sketching trip around UCD during the time of the Drawing & Making module. Attendance and participation each week are a mandatory part of the module, and students are strongly encouraged to attend and to participate in the group discussions of your work and the work of your peers. Peer discussion and feedback in particular are a very important component of your learning in this module. Please contact one of the teaching team if for any reason you are unable to attend a session. In the Spring Trimester, Drawing & Making continues during the Technology I Introduction to Building Envelope module. Drawing and Making is taught by a team of practicing architects, each working in a different type of design and creative practice: Emer O''Daly, Eibhlín ní Chathasaigh, Paul Durcan and Joe Swan.', 'https://www.ucd.ie/modules/ARCT10160', 'arct10160'),
    ('e9d34d17-326c-40b7-8804-96ea80aa06d4', v_uni_id, 'ARCT10170', 'Introduction to Regenerative Practice', 'Architecture, Plan & Env Pol', 'This module introduces students to contemporary and future practice of architecture: what architects do. Content is framed from the scale of the planet and society, to the scale of the human and more than human, with an emphasis on changing skills, tools and knowledge architects need to develop in response to the climate emergency: shifting from extractive to regenerative practice. Three key areas are introduced as foundations to be built on and practiced: the profession of architecture, ethics and regulation; climate literacy for the design of the built environment; critical thinking and informed design process as it relates to the built environment.', 'https://www.ucd.ie/modules/ARCT10170', 'arct10170'),
    ('65ef47dc-df1c-4fd4-b858-7f9608ddbe8a', v_uni_id, 'ARCT20010', 'Architectural Design IV', 'Architecture, Plan & Env Pol', 'Housing Campus Life – Strategies for Adaptive Reuse and Regenerative Development in UCD This studio project follows on from the studio of 22/23 with a continued focus on adaptive reuse. The studio is also part of the Curriculum for Climate Action project, now called Building Change.. This is a shared, government-funded initiative across all Ireland''s undergraduate architecture programmes, specifically focussed on the revision of studio modules to equip students with the knowledge and skills necessary to work towards low-carbon and zero carbon designed environments. While this initiative informs the overall direction and outcomes of the studio module, it will also support specific input and exercises. The studio will focus on developing design scenarios a site at the centre of Belfield campus which provide a combination of accommodation and shared facilities for students and others. These design scenarios will include the reappropriation of existing buildings as well as new-build elements. Thus, adaptive reuse is central to the semester’s work and theories and practices of reuse will provide the underpinning for the design work. A field trip focussed on processes and examples of reuse will further augment this focus. In considering both existing and proposed buildings, the emphasis is on understanding them as entities or organisms which exist in time, which have different phases of life from the moment of their completion. Buildings and their surroundings must also be understood in terms of their environmental performance - how light and air and moisture moves through them over the course of the day, the year. Tools and methods for testing and experimenting with environmental performance will play a central role in the studio. Close attention will be paid to the fabric and construction, including working with other built-environment disciplines. At all stages, questions of climate action and climate adaptation will be central, with full consideration of the embodied and operational carbon of proposals. Close attention will also be paid to the development of briefs which respond to the changing needs of campus life. Student accommodation will form a major component of this brief, and will bring with it challenges of organisation, layout, circulation and systems of construction, all of which need to be considered in the design process. In conjunction with this, other functions and uses may be added to the project which serve to enrich and expand campus life in truly enabling, inclusive and sustainable ways.', 'https://www.ucd.ie/modules/ARCT20010', 'arct20010'),
    ('6ae1b0e6-aaf8-4a85-82bf-4fb6328d3058', v_uni_id, 'ARCT20040', 'History & Theory of the Designed Environment III - Survey Course 2', 'Architecture, Plan & Env Pol', 'The course sets out to present the development of the modern and contemporary designed environment in order to build a common knowledge base for future architects, engineers, designers, landscape architects, planners and others involved in the procurement and management of the designed physical environment. Not withstanding this perspective, it is accessible to all. The time span of the study is the latter half of the nineteenth century to the latter half of the twentieth. While concentrating on key figures and movements, the course situates changes in the design environment over this time in a wider social, cultural and technological context. Often underpinned by a political agenda, modernity has its roots in a critical reaction to the conditions and inequality of the nineteenth-century industrial city. This module traces how this develops, examining those projects from the modernist canon which are most significant and influential. Furthermore it examines how modern architecture, urbanism and landscapes adapted to changing technologies and structural theories. More recently, it has been recognised that modern architecture and development is instrincially linked to the fossil fuel economy in terms of the resources it uses, the methods and processes it deploys and the functions it serves. Equally, modern architecture and development is fundamentally related to geo-political processes of colonisation and globalisation. Interwoven through the course, a series of three thematic lectures and seminars, dealing respectively with systems and resources, with so-called ''carbon form'' and with global society, will reflect on how these new perspectives can complicate and enrich our understanding of the architecture of the period.', 'https://www.ucd.ie/modules/ARCT20040', 'arct20040'),
    ('14ce9dec-9b2a-4e90-9a94-1f793f7511d7', v_uni_id, 'ARCT20050', 'Architectural Design III', 'Architecture, Plan & Env Pol', 'Pass/Fail (GPA Neutral) WE ARE HOPEFUL MONSTERS From Wood Quay to Camden Yard - A Punk Approach to the City & Climate Action Over the next three academic years (2026 - 2029) , we will expand our architectural thinking to the scale of the city and its complex layers of infrastructure, ecology and inhabitation. Our study will engage with the economic, environmental, political and sociological conditions of the city, their implications and potentialities for generating architecture as Climate Action in the Anthropocene. We recognise architecture’s potential to consider hope as an action, future orientated and dynamic - an action that momentarily moves us past traditional or perceived boundaries, enabling us to project nimble and imaginative propositions in response to the moment''s extraordinary challenges. The architectural solution might be unknown or surprising. Equally we invite learners take on this challange with a rigorous, structured and serious approach. “If we are to survive in the environment we have made for ourselves, may we have to be monstrous enough to greet our predicament?” Hopeful Monsters, Nicholas Moseley 1990 We wish to explore the potential for the city centre to be a people''s home - a place that supports its citizens (both human and more than human) to live well and thrive - to work, learn and play. We will study, investigate, probe, act, respond, adapt, iterate, through the lens of climate action. We will look for gaps, existing buildings, infill, connections in the city in order to act architecturally, all the while considering connections and opportunities. Each semester the focus will examine part of the territory, through maps, observations and digital and analog data. We will look at buildings, rooms, public spaces, amenities, infrastructures, movement, resources. Learners will engage in group and individual design projects, at the scale of the body, building, city and beyond. For this first of the six semesters of Hopeful Monsters the studio will respond to a design scenario, within the council''s remit and responsibility, to provide a city for living in a hopeful, inclusive, enabling and sustainable manner. A "hopeful monster" is an evolutionary theory proposing that massive, sudden genetic mutations (macromutations) can create entirely new species in a single leap. If the drastic new traits happen to survive and thrive in a given environment, the "monstrous" individual becomes the founder of a brand-new evolutionary lineage Richard Goldschmidt 1940.', 'https://www.ucd.ie/modules/ARCT20050', 'arct20050'),
    ('d2975384-652a-40b4-a65c-8772e21f87c6', v_uni_id, 'ARCT20100', 'Architectural Technologies II', 'Architecture, Plan & Env Pol', 'This module looks in detail at building construction and the materials and systems used. It develops the student''s understanding of fundamental matters of construction. It builds the student''s confidence in building technology to enhance their design confidence. It introduces the student to building regulations and design standards. The module begins where Architectural Technology 1 left off with the opening, and works through walls, foundations, floors, roofs and cladding. Both lectures and tech studio initially focus on timber and masonry before introducing a wider range of materials including cast concrete and steel in the closing weeks. The module runs as a parallel lecture series and technology studio.', 'https://www.ucd.ie/modules/ARCT20100', 'arct20100'),
    ('978d93a9-13f3-4d5c-8381-5475b911d424', v_uni_id, 'ARCT20130', 'Imagining Architecture', 'Architecture, Plan & Env Pol', 'This module provides a theoretical and technical grounding in digital drawing and image-making in the architectural design process. The module is taught through a combination of live lecture and video-tutorials. Each week students will learn a specific skill set combined with a critical overview of the theoretical, historical and contemporary modes of the drawing and image-making practice. Assignments are structured to allow for a gradual development of technical proficiency and theoretical appreciation through weekly submissions.', 'https://www.ucd.ie/modules/ARCT20130', 'arct20130'),
    ('a1c8b4eb-9403-46a8-bd24-a737d5423c02', v_uni_id, 'ARCT20170', 'Intro to Computational Design', 'Architecture, Plan & Env Pol', 'This module introduces students to digital tools for creating and controlling form. The aim of the module is to give an understanding of the possibilities that digital design can bring, to develop a student’s ability to think and draw in three dimensions and to create complex forms and patterns, and to demonstrate how simple computer programming and parametric thinking can interact with design. This module engages with two key digital tools. First, the students are introduced to a 3D drawing/modelling tool (Rhino), and learn how to draw three-dimensional geometries – from the simple to the complex. Following this, the students build on their modelling skills by experimenting with a parametric visual programming language (Grasshopper): to explore the creation of patterns, to control geometries, and to consider issues of detail and fabrication. The demonstrations and projects are structured around studies of precedent buildings by architects and engineers who built complex form and pattern, from the designers of the Modernist period (Candela, Nervi, Dieste, etc) to current practitioners. This module explores a territory of overlap between architecture and engineering: in terms of how the digital tools are used in practice, and in terms of the ideas of geometry and technology that underpin digital design. The module is open to students of both disciplines.', 'https://www.ucd.ie/modules/ARCT20170', 'arct20170'),
    ('5c4f6fa0-bf74-4dce-a940-49e40678175b', v_uni_id, 'ARCT20570', 'Enhancing Digital Drawing Skills', 'Architecture, Plan & Env Pol', 'This module will provide the opportunity to enhance and develop digital drawing skills for those designing the built environment. The global objective of the module is to teach participants a spectrum of drawing skills across a number of computer programs: Adobe InDesign, Adobe Photoshop and Rhinoceros and Revit. Integration of these applications and their file formats while maintaining file image quality, integrity and scale will be demonstrated. Teaching will consist of instructional lectures and video tutorials as well as individual/small group tutorials.', 'https://www.ucd.ie/modules/ARCT20570', 'arct20570'),
    ('a7ee7501-f076-4f53-9078-23374b8e5933', v_uni_id, 'ARCT20580', 'Architecture & Environment I', 'Architecture, Plan & Env Pol', 'Architecture & Environment I considers the dynamic relationship between sustainable building design and environmental factors and the interplay between them. It focuses on how these elements influence human experience, health, well-being and both the indoor and outdoor environments. The course covers a range of topics including daylight and sunlight, lighting design, sound and acoustics, energy and thermal performance, indoor environmental quality, sensory perception, occupant health, and human comfort. It explores the ways in which these elements interact to shape not only the built environment but also the human experience within these spaces. It emphasises the importance of sustainable design practices that prioritise the well-being of occupants, environmental stewardship and the optimised use of natural resources.', 'https://www.ucd.ie/modules/ARCT20580', 'arct20580'),
    ('45f770aa-d495-4ed9-8528-30aba12f843c', v_uni_id, 'ARCT20590', 'Photography & the Built Env', 'Architecture, Plan & Env Pol', 'This module immerses students in the practice and theory of digital photography as a tool for observing, interpreting and creatively representing the built environment. Beginning with the construction of a Camera Obscura and culminating in the production of a short photo book, students engage in a sequence of projects that explore the built environment while developing their ability to see, document and question the spaces around them. Through illustrated talks, hands-on workshops, tutorials, lively peer discussion and field-based exploration, the module introduces key historical and theoretical perspectives on photography alongside practical instruction. Students develop a critical understanding of image-making in relation to the built environment while building core photographic skills, including camera control, composition, digital post-production and publication. Students are expected to have access to a digital SLR or mirrorless camera with full manual control (adjustable shutter speed, film speed, aperture) and RAW capture, a laptop with image-editing software, and presentation and layout tools for visual communication and book design (eg powerpoint / google slides / keynote and adobe indesign, adobe photoshop or open source alternatives).', 'https://www.ucd.ie/modules/ARCT20590', 'arct20590'),
    ('88d357b5-0ebc-4dc9-95e0-3fe5598388ce', v_uni_id, 'BIOL00010', 'Fundamentals of Biology', 'Biology & Environment Science', 'This course provides an introduction to the general principles of biology and is intended primarily for students who have not previously studied the subject. A wide range of biological concepts will be covered, including cells, organisms and ecology. The overall aim of this module is to provide a basic understanding of biology and put this in the context of the many diverse and developing research areas that exist in biology today.', 'https://www.ucd.ie/modules/BIOL00010', 'biol00010'),
    ('7e42d129-3c43-408f-bf27-78783cb58b1c', v_uni_id, 'BIOL10070', 'Biology for the Modern World', 'Biology & Environment Science', 'Biology lies at the heart of human civilisation and society. Biological knowledge underpins how we treat disease, care for other species and our environment, and how we produce food, energy and materials. The aim of this module is to give students an introduction to the biological knowledge that informs medicinal, technical and environmental development and informs topics that are of significant public concern. These include stem cell research; conservation and biodiversity; climate change; evolution of vertebrates including humans; mate choice, sex, genetics and survival of the fittest; cancer research, antimicrobial resistance, breeding and engineering of food crops, novel materials and energy sources. A variety of professors will introduce students to the biological principles that underpin their research in these areas and students will get an opportunity to demonstrate their knowledge of these principles in MCQ exams. A basic introduction on how science informs policy and public debates will also be added to the module this year. Student feedback: generally students are very satisfied with their learning in this module and find the range of topics exciting. As a result of feedback from last year (2019) the assessment structure was simplified again.', 'https://www.ucd.ie/modules/BIOL10070', 'biol10070'),
    ('3b9efe66-f122-47b7-81c6-821cc8986d77', v_uni_id, 'BIOL10110', 'Cell Biology & Genetics', 'Biology & Environment Science', 'This module will provide an introduction to the cell, its structure and functioning. Also the basis of genetics and inheritance will be explored. The following topics will be covered: (1) An overview of cell biology; (2) cellular organelles and the cytoskeleton; (3) How cells work- cellular respiration and photosynthesis; (4) The cell cycle and the key roles of cell division; (5) How meiosis and sexual life cycles provide biological variation; (6) Introduction into genes and inheritance from a Mendelian perspective; (6) The link between chromosomes, genes and inheritance; (7) DNA and the molecular basis of inheritance; (8) How proteins are made from genes; (9) How genomes can inform our understanding of life''s diversity; (10) Brief introduction into basic genetic molecular techniques. The student is required to attend 22 lectures, five two-hour practicals and complete online pre-practical assignments, and complete online continuous assessments.', 'https://www.ucd.ie/modules/BIOL10110', 'biol10110'),
    ('ea6d7c28-18b7-426a-be12-25175e2b4410', v_uni_id, 'BIOL40560', 'Biological Imaging', 'Biology & Environment Science', 'In the life and biomedical sciences the form and function of organisms, particularly at the cellular and subcellular levels, is often studied through imaging and microscopy approaches. This module informs about the concepts of imaging and microscopy; the importance of resolution and its limits; optical components; and microscope design. Students will gain understanding of widefield microscopy, laser scanning confocal microscopy, spinning disk confocal microscopy; super-resolution microscopy, and automated microscopy. The module will also detail various imaging techniques used to quantify the mobility and interactions of molecules in cells, including time-lapse microscopy, FRAP, FRET, FCS and split fluorescent proteins. Cell culture and types of cells available, treatment of cells in live cell imaging experiments, use of media, buffers, climate control systems, and issues relating to photo-toxicity will also be explored. Consideration will also be given to fluorescent proteins, fixation methods, use of antibodies and stains, immunofluorescence, and mounting media. A basic introduction to the analysis of biological images will also be given. This module also provides practical exposure to concepts in imaging through lab-based workshops.', 'https://www.ucd.ie/modules/BIOL40560', 'biol40560'),
    ('cd867825-066e-4554-a287-c8a09e0121d0', v_uni_id, 'BMGT10140', 'Business Plan', 'Business', 'This is a core course on preparing a Business Plan for a new business start-up. The key elements of a business plan are examined, such as defining objectives and goals, conducting an environmental analysis, developing a marketing strategy, operating a strategic strategy, conducting a competitive analysis, and selecting a financial strategy. Students must demonstrate the ability to build and present the Business Plan. The course will be assessed on completing and presenting a detailed written project. You will also show competencies in being an influential start-up team member.', 'https://www.ucd.ie/modules/BMGT10140', 'bmgt10140'),
    ('2121ff9e-32ce-4864-bae1-dce82edc8e3a', v_uni_id, 'BMGT10150', 'Project Management', 'Business', 'In recent years, project management has become increasingly more significant in an organisational context. Projects drive business activities in a wide variety of sectors from the public and private sectors to not for profit charities and organisations. Regardless of the product or service, good project management techniques will provide a result that is delivered on time and within budget. In this regard, the module will cover topics such as planning, scheduling, budgeting, quality, leadership and risk management which are some of the key issues that need to be understood and practiced by managers to realise successful project delivery.', 'https://www.ucd.ie/modules/BMGT10150', 'bmgt10150'),
    ('225eb059-01d2-4bd2-9832-9d666aae8b26', v_uni_id, 'BMGT10170', 'Inside Organisations', 'Business', 'Inside Organisations is built around ten conversations about people, work and organisations. Our purpose is to learn more about the human side of organisations, and get to grips with groups, teamwork and collaboration. People’s behaviour is often curious and always interesting. Taking a close look at behaviour inside organisations (starting with your own) will prove useful to you not just when you enter the workplace, but right now, as you work to get things done in college. This is a module designed to develop your OB knowledge and insight, expand your skills through active experience, and enhance your capacity for reflective, informed analysis. In parallel to lectures, you’ll engage in active learning, working with fellow classmates on one of three styles of group experience: a creative project team, a structured weekly roundtable, or a Venture Lab to plan and deliver an event. Places on each are assigned subject to availability, and groups will continue to work together throughout the term. We’ll discuss the scope of each in more detail in lectures before the team assignments commence. This module is 100% team graded, reflecting our focus on collaboration skills. The interdependent nature of teamwork will require your time, attention and very active contribution – showing up for yourself and each other. There are four specific learning goals: Knowledge: Learning about a range of individual, group and organisational behaviour (OB) theories and concepts, including personality, motivation, culture, and decision-making in groups. Skills: Getting to grips with groups: learning to understand and work with group dynamics, and developing practical collaboration, teamwork and communication skills. Application: Building awareness of contemporary working lives, organisational practices, and the future of work. Mindset: Developing your self-awareness, psychological mindedness and sociological imagination. A key intention of this module is to lay a foundation of vocabulary and insights concerning human behaviour in organisations that you can draw on throughout many future modules. All students taking this module should be aware that this module requires a high degree of participation and teamwork.', 'https://www.ucd.ie/modules/BMGT10170', 'bmgt10170'),
    ('dcdf5e8e-7332-42c2-a574-2ddebac49935', v_uni_id, 'BMGT10180', 'Business Management Simulation', 'Business', 'This module provides students with a practical introduction to essential business and strategy competences associated with managing a new venture. Through computer simulation, you will start up and run your own company, struggling with business fundamentals and the interplay between marketing, distribution, manufacturing, human resources, finance, and accounting. You are given control of a simulated business and must manage its operations through several decision cycles. Repeatedly, you must analyze the situation, plan a strategy to improve it and then execute that strategy out into the future. You face great uncertainty from the outside environment and from your own decisions. Incrementally, you will learn to skilfully adjust your strategy as you discover the nature of real-life decisions, including the available options, linkages to other parts of the business, conflicts, tradeoffs and potential outcomes. Note: This module has a limited number of elective places. We welcome students from all disciplines who are interested in a challenging introduction to business management.', 'https://www.ucd.ie/modules/BMGT10180', 'bmgt10180'),
    ('6fa66e57-a617-4011-bff4-72a6950f1091', v_uni_id, 'BMGT10190', 'Effective Learning and Development', 'Business', 'You are at the beginning of your degree and have an opportunity to create and build skills that will stand to you – throughout your life and career. Being successful in business requires soft skills alongside technical expertise. Skills like being able to set goals, managing your time - and life - well, and expressing yourself effectively enable you to manage yourself and your relationships with others sustainably. These skills are necessary for academic progression but are also increasingly required by employers. You will find that some topics develop your existing skills and apply them in new ways. Other topics will require more personal reflection and will develop new skills in unfamiliar areas. You will explore skills in two blocks: the first block focuses on setting goals, finding good quality sources of information, thinking critically, and expressing yourself verbally and in writing, while the second focuses on managing your life, understanding mindsets, empathy and resilience, exploring learning preferences and how you see others and your future. These are all topics that have value beyond this module, your application in this module will be of benefit to you across your modules and life outside of university. IMPORTANT NOTE:: Students are expected to attend all sessions. The use of AI tools (e.g. Gemini, Copilot, ChatGPT, Claude, Jasper, NotebookLM, DeepL, Grammarly,  etc.) is not permitted in this module. Students are expected to engage directly with module materials and activities without the use of AI tools. Failure to comply will result in a NM/fail grade. Students must complete their Learning reflection submissions from start to finish in Google docs on their UCD Connect Google drive while online and without using the Document tab function.  Failure to comply will result in a NM/fail grade for the Learning reflection. Students are expected to comply with UCD''s Academic Integrity Policy requirements. Any evidence of misconduct will be forwarded to the school''s committee.', 'https://www.ucd.ie/modules/BMGT10190', 'bmgt10190'),
    ('83198ff3-92f8-423e-9936-5667ee7d956b', v_uni_id, 'BMGT10200', 'Foundations of Management', 'Business', 'This module explores key ideas, debates, and practices that have shaped contemporary approaches to management. The module will critically examine influential eras of thought and different approaches to organising and managing human endeavour e.g. scientific management, bureaucracy, human relations, and consider their social and historical contexts. It is designed to help you to weigh management ideas in context, identify fads and gain long-term perspectives to inform your thinking. It will also help you analyse and argue based on your reading. Over the course of the module you will learn lessons from the past that can be applied to key management issues of today and in your future management practice.', 'https://www.ucd.ie/modules/BMGT10200', 'bmgt10200'),
    ('18a0a4c0-5e77-4294-9a6f-2ef272e4a15a', v_uni_id, 'BMGT20050', 'Business Across Borders', 'Business', '"Business Across Borders" module is a second-level (year 2) introductory module on international business, management, and culture. This introductory module focuses on the challenges and opportunities associated with organisational management and business strategy in the global environment. Business Across Borders is a course that is essential for every organisation, be it a small and medium enterprise or large multinationals operating both domestically or across borders. Students will learn to understand the key Global and International issues involved in doing business on the Global stage. The course focuses on integrating and applying the basic elements of management, culture and international strategic management and specialised contextualised strategies required for emerging economies and for international new ventures, including modes of entry and methods used to analyse and assess culture and political risk in developed and developing countries. The course will cover most issues for any businessperson to understand the complexities of doing business overseas and the ways to enter these markets and how culture plays an exceedingly impactful role in deciding between success and failure. Students will gain a general overview of the process and effect of internationalisation in contemporary business, along with an introduction to theories, concepts, and skills relevant to managing effectively in today’s global environment. Students will address how industrial growth directly and indirectly drives vital societal targets—such as job creation, poverty reduction, gender equity, fair labour standards, and expanded access to health care and education. This integrated framework aligns directly with UN Sustainable Development Goal 9 (SDG 9). Through lively, topical, and accessible examples, the course will try to integrate international management, culture, and strategies to allow students to conceptualise business operations globally. This module introduces two core perspectives, the institution-based view and the resource-based view. The course also includes numerous interesting and diverse examples of the intersection of business and culture to motivate students to read and learn. Students will be challenged to integrate the knowledge they have gained from other business core courses and apply their accumulated knowledge to business case studies. Students will engage in active research and analytical problem solving related to managing in the international environment and will frequently be called upon to brief their findings to the class. Discussion and explanation are the key learning skills.', 'https://www.ucd.ie/modules/BMGT20050', 'bmgt20050'),
    ('9410f04f-b564-4130-9b16-18fe56d14542', v_uni_id, 'BMGT20080', 'Consulting with NGOs', 'Business', 'Consulting with NGOs (formerly known as Service Leanring) focuses on encouraging ''learning by doing''. NGOs and other non-profit companies operate in a particularly challenging space. On this module, students will come to understand these challenges firsthand by working closely with a local charity, non-profit or social enterprise to solve a current business challenge that they are facing. To do this, students will learn some of the tools and techniques that management consultants use when advising companies - not just the theory, but also how to apply them. By making that important link between theory and practice, students will also be able to explore the key management issues affecting the non-profit sector, while making a valuable contribution to the local community. This is a project-based course with a considerable amount of group work. All students will be assessed on both their group work and their individual contribution to the project.', 'https://www.ucd.ie/modules/BMGT20080', 'bmgt20080'),
    ('88c63fdc-801b-42d9-a7ea-fa19abc1fa75', v_uni_id, 'BMGT20100', 'Developing Future Leaders', 'Business', 'What does it mean to become a leader, and how can we continue to be effective leaders? Leadership is not a destination reached simply by gaining a particular position or title. Rather, it is an ongoing process of learning, adapting, and developing the skills and capabilities needed to work effectively with and influence others. This module invites students to explore what effective leadership looks like, how leadership can be developed, and how individuals can make a positive difference in the groups, teams, and organisations of which they are part. Students will develop an understanding of key perspectives on leadership, relationships, and influence, while developing practical skills in areas such as self-awareness, communication, influencing others, decision-making, conflict management, collaboration, navigating power and diversity, and responding effectively to change. Students will have opportunities to examine their own strengths, values, emotions, and behaviours, consider how these shape their interactions and their approach to leadership, and identify areas for personal and professional development.', 'https://www.ucd.ie/modules/BMGT20100', 'bmgt20100'),
    ('1369bd75-d406-4b59-b770-13eb68a51aee', v_uni_id, 'BMGT20130', 'Responsible and Sustainable Business Management', 'Business', 'This module helps you develop an awareness of how business and ethical issues interconnect in organizations, and your role in navigating that relationship. It explores business and ethics by examining their philosophical foundations, which provides a basis for understanding the key dynamics that influence both individual and collective decision-making and actions in organizations. The module addresses contemporary challenges including social responsibility and environmental sustainability considerations that businesses face today. You will have opportunities to discuss ethical issues through case studies and various ethical problems in a highly participative class environment.', 'https://www.ucd.ie/modules/BMGT20130', 'bmgt20130'),
    ('56a0baed-7178-4521-80c3-6f0fcd25fc0a', v_uni_id, 'BMGT20140', 'Global Business', 'Business', 'This module is designed to provide students with a broad understanding of the issues involved in doing business in a globalised world economy. Throughout the semester we will be drawing on current knowledge in the area to learn about the main economic, political, ethical, cultural, and sustainable factors that characterise the global business environment. Subsequently, we will focus on how these factors matter for firms and discuss a range of firm-level issues. These include global strategies and structures, the process and modes of foreign expansion, management of foreign subsidiaries, and financial and human factors in global business. In particular, we will use gen AI to generate initial answers for some assessment questions, and critical analysis will be required based on them.', 'https://www.ucd.ie/modules/BMGT20140', 'bmgt20140'),
    ('8077e2d7-f4cc-4058-ad16-e0fc01350d06', v_uni_id, 'BMGT20150', 'Sustainable Operations & Supply Chain Management', 'Business', 'Operations and supply chain management play a key role in executing an organisation''s business strategy and achieving sustainability goals. These functions create, manage, and improve manufacturing and service processes, and oversee the flow of goods and services. This module equips students with key concepts, tools and techniques to design, manage, and optimize operations and supply chains through a sustainability lens. Students will build in-demand skills to drive operational and sustainable excellence, enabling them to thrive in roles across operations, supply chain, and consulting. Through exercises and cases, they will gain hands-on experience solving real-world operations and supply chain challenges, identifying root causes, exploring sustainable alternatives, and implementing impactful improvements. They will also learn how to leverage emerging technologies and harness data to unlock innovations that benefit the environment and society. This module prepares students to drive sustainable operational and supply chain excellence and strategic impact in their future careers.', 'https://www.ucd.ie/modules/BMGT20150', 'bmgt20150'),
    ('e6893b44-4f12-48da-acbf-f43dfa70e8b5', v_uni_id, 'BMGT20160', 'Business and Social Enterprise', 'Business', 'This module is essentially composed of two intertwined parts. The first part tasks you to apply entrepreneurial thinking to identify opportunities and solutions that will make an important positive impact on society: it is an invitation to redefine your environment in a creative and innovative way. In addition to this first part, in the second we addresses issues which become particularly relevant when the firm increases in size and scales up: how to ensure a long-run survival when external environmental conditions change (dynamic capabilities), how to properly balance today''s needs with tomorrow''s demand (ambidexterity), how to set and maintain a dominant design (network effects), and how to benefit from ideas that originate out of the traditional organizational boundaries (open innovation). Using course readings, discussions, and case studies, you will be able to identify opportunities to create social value, undertake the initial discovery, research and validation steps required to assess the potential to create a scalable business. In order to achieve this, the module also provides some essential tools on how to set the most appropriate strategic direction of the firm, once it has been created. Business and Social Enterprise helps you to integrate and apply key management, marketing, finance, and research skills developed in other modules. The module also aims at providing few but essential notions related to the strategic management field, which are expected to be very useful to successfully run both a social and "standard" enterprise. The module is also expected to strengthen your teamwork and creative skills. The module will be practice-oriented, with several opportunities of interaction and real case discussions. The approach followed will be mostly inductive, i.e. students are guided towards the conception of a general theory starting from specific, real business situations.', 'https://www.ucd.ie/modules/BMGT20160', 'bmgt20160'),
    ('dccfd3d7-8856-449e-a593-83f74fada87a', v_uni_id, 'BMGT20180', 'Wellbeing and Work', 'Business', 'Stress, whether experienced as physical or psychological, is a common feature of our normal lives. According to the World Health Organisation, it is stress emanating from the workplace that affects the psychological and physical health of individuals, as well as the effectiveness of organizations and the functioning of society. Considering this, it becomes clear that it is essential to focus on wellbeing in the workplace. This module will emphasise the individual’s wellbeing as a starting point for organisational and societal wellbeing using practices which can help build resilience and strengthen personal resources to manage and respond to challenges as experienced in everyday life, including the work setting, in a more skilful way. A wide range of practices will be explored using different modalities to expose participants to a variety of tools and potentially meet individual preferences. Habits can be changed and the skills to do so can be learned, it is something simply a matter of finding the right tool! It is advised that students are comfortable with their emotional wellbeing before enrolling in this module. In the event of questions about the suitability of this module, please contact the module coordinator prior to enrolling in the module. IMPORTANT NOTE:: Students are expected to attend all sessions. The use of AI tools (e.g. Gemini, Copilot, ChatGPT, Claude, Jasper, NotebookLM, DeepL, Grammarly,  etc.) is not permitted in this module. Students are expected to engage directly with module materials and activities without the use of AI tools. Failure to comply will result in a NM/fail grade. Students must complete their written submissions from start to finish in Google docs/slides on their UCD Connect Google drive while online and without using the Document tab function.  Failure to comply will result in a NM/fail grade. Students are expected to comply with UCD''s Academic Integrity Policy requirements. Any evidence of misconduct will be forwarded to the school''s committee.', 'https://www.ucd.ie/modules/BMGT20180', 'bmgt20180'),
    ('cb5343cf-e2f3-4ad9-8d2b-0212935f5bbb', v_uni_id, 'BMGT20190', 'Introduction to Negotiations', 'Business', 'Negotiation is the process through which conflicts are resolved, resources are allocated, and agreements are made. The types and contexts of negotiation vary widely from minor disagreements amongst friends to complex, high-risk commercial, legal or political negotiations. In this module you will gain a broad understanding of the concepts, frameworks and theories of negotiation and the body of empirical research that supports them. You will learn to differentiate between effective and ineffective negotiation strategies and tactics and how to create and claim value when negotiating. Throughout the module you will engage in hands-on negotiation exercises, class discussion, and reflection on your skill development. Attendance in class for the learning activities is therefore essential for success in the module. Materials: Students are required to register and pay the copyright fees for negotiations exercise materials (estimated at 50 euros). The required textbook is free through the UCD library. Students are actively encouraged to engage critically with specific AI negotiation tools in several elements of this module.', 'https://www.ucd.ie/modules/BMGT20190', 'bmgt20190'),
    ('385681c9-cf28-445e-b86e-f27613ed820d', v_uni_id, 'BMGT20210', 'Business and the European Union', 'Business', 'This module examines the relationship between the European Union and the business environment in Europe and internationally. Businesses, inside and outside the European Union, are reviewing their business models and strategies, as they seek to i. withstand the disruption caused by the tense geopolitical situation, ii. adapt to the challenges posed by Brexit and the EU-UK Trade and Cooperation Agreement, iii. accommodate the changing nature of globalisation encompassing international political relations (e.g. with the US, China, Asia, Africa, the Middle East and Russia), iii. negotiate economic shocks, impacting the flows of trade (goods and services) and investment and iv. engage with ambitions for sustainable competitiveness during a period of green and digital transition. These developments are in many ways unprecedented and business dislikes uncertainty thus making it a lively and interesting time to study the European Union. Following the European Parliament elections in June 2024 and the re-election of Ursula von der Leyen as President of the European Commission, the European institutions and member states commenced a five year term to 2029 set to design a policy programme addressing i. the ease of engagement with the single european market, ii. the facilitation of industry via decarbonisation and lower energy prices, iii. the enhancement of productivity through the diffusion of digital technologies, iv. competitiveness linked to research and innovation and v. the development of key labour skills for market needs over a career. Manufacturing and service companies, both large and small, across a wide range of industries established within the EU or trading with it must comply with its legislative requirements and be mindful of policy development. Part I the module’s introductory lectures/sessions provide i. an overview of the history and development of the European Union along the role of business interests; ii. the European Union institutions/agencies and policy development and iii. a profile of the member states and international relations. Part II will addresses a selection of specific policy areas including the single market for goods and services, competition policy, common commercial policy/world trade, Economic and Monetary Union and financial regulation, the environment/climate change, and digital commerce. When addressing these policy areas the module will draw attention to and encourage student engagement with case studies which illustrate the legislative and policy impact on companies and industries as they seek to comply, adapt and innovate to address the challenges posed. The module is designed to guide independent learning and facilitate the development of critical research skills into the European Union and its policies which can be applied to meet future needs. This is reflected in the formative assignments and module assessment which provide for group and individual research involving the critical selection of primary, academic and complementary sources to address the impact of the European Union on the business environment, industries and individual companies.', 'https://www.ucd.ie/modules/BMGT20210', 'bmgt20210'),
    ('dfb2c331-8159-48d0-a89f-300df23b8cf1', v_uni_id, 'BMGT20220', 'High-tech Entrepreneurship', 'Business', 'This module provides an in-depth exploration of the theories, principles, and practical skills essential for creating and developing high-tech innovative ideas within entrepreneurial ecosystems. Students will gain a solid foundation in understanding the key components of successful high-tech entrepreneurship and entrepreneurial ecosystems. The module offers various theories and frameworks that underpin entrepreneurship, enabling students to grasp the fundamental concepts and strategies involved in starting and managing high-tech startups. Furthermore, the module delves into the essential concepts and actors within the entrepreneurial ecosystem, including policy, finance (e.g., Venture Capital and Business Angels), culture, support structures (e.g., Incubators and Accelerators), human capital, and markets. Students will understand the roles and contributions of these elements in supporting innovation and entrepreneurial endeavors. Students will participate in team projects focused on analyzing the entrepreneurial ecosystem of a city, fostering collaboration and practical application of the course concepts. While the primary focus of this module is on "standard" high-tech commercial innovative ventures, it also encompasses the broader scope of high-tech entrepreneurship. Students will be introduced to social innovations and corporate entrepreneurship, exploring concepts such as Impact Investing, Hybrid Organizations, Social Startups, Open Innovation, and Intrapreneurship. This broader perspective will allow students to understand the diverse forms and applications of high-tech innovation and entrepreneurship in various contexts. Throughout the module, students will be challenged to apply theoretical frameworks, tools, and strategies to real-world situations, such as through guest speakers, to develop their teamwork, problem-solving and critical-thinking abilities.', 'https://www.ucd.ie/modules/BMGT20220', 'bmgt20220'),
    ('08f3b082-f86c-40d0-8472-f09d26dc5305', v_uni_id, 'BMGT30300', 'Business Strategy', 'Business', 'This is a learning-by-doing course. Through the combination of lectures, readings, the simulation, and case studies, this course introduces you to the tools and vocabulary prerequisite to critical and effective strategic analysis, thinking, and communication. Strategy is the central, integrated, externally oriented concept of how a firm will achieve its objectives. A strategy encompasses the pattern of organizational actions taken in pursuit of an advantage over its competitors. Or put another way, a strategy outlines how a firm will create unique value. This course and the simulation will require you to integrate the knowledge and skills you acquired in earlier courses and apply them using the same multi-disciplinary perspective demanded of a general manager.', 'https://www.ucd.ie/modules/BMGT30300', 'bmgt30300'),
    ('44230139-2674-4871-8b08-1f89c551169c', v_uni_id, 'BMOL10030', 'Biomedical Sciences: Understanding Human Disease.', 'Biomolecular & Biomed Science', 'This module will introduce students to Biomedical Science and the molecular basis of neuronal, cardiovascular, infectious, hormonal and immune diseases. Students will learn about fundamental metabolism, the structure and function of each affected organ or biological system, and how these may be disrupted to manifest into disease and clinical symptoms. The risk factors associated with each disease (e.g. genetic, environmental, diet/lifestyle) will be investigated, and current therapies and research efforts to prevent and cure the diseases will be discussed. The module provides a foundation for further studies in Biochemistry, Genetics, Microbiology, Neuroscience, Pharmacology and Physiology.', 'https://www.ucd.ie/modules/BMOL10030', 'bmol10030'),
    ('29538c39-c0ff-4491-83ea-4b0e895e3c1b', v_uni_id, 'BMOL20090', 'Molecular Genetics and Biotech', 'Biomolecular & Biomed Science', 'In living cells nucleic acids direct both self-replication and synthesis of proteins. DNA also undergoes mutation and recombination, which ultimately generate biodiversity and allow evolution to proceed. The course will cover the basics of these fundamental biological processes and explain how this knowledge is exploited in recombinant DNA technology. Specific areas include: nucleic acid structure; DNA replication; mutation and repair; transcription and translation; control of gene expression; gene cloning, DNA sequencing and genetic engineering. A series of in-course assignments will encourage student engagement and assist understanding of key topics. The lecture course will be assessed by an end-of-trimester multiple choice quiz examination.', 'https://www.ucd.ie/modules/BMOL20090', 'bmol20090'),
    ('518d375a-206e-4d95-92e1-72c46db6bc35', v_uni_id, 'BMOL30020', 'Molecular basis of disease', 'Biomolecular & Biomed Science', 'This module will address key biochemical systems and processes within the body associated with disease development and treatment. Amongst the topics to be discussed will be gastrointestinal disorders, the microbiome and bacterial-mediated diseases (e.g TB, MRSA), neurodegenerative diseases, diabetes, cardiovascular disease and cancer. The goal is to demonstrate the importance of a holistic approach to understanding human biochemistry and demonstrate the central role played by basic biochemistry in disease pathogenesis.', 'https://www.ucd.ie/modules/BMOL30020', 'bmol30020'),
    ('a0f4a1a3-a5c6-4f6b-9fbc-0e47f18f3c99', v_uni_id, 'BOTN30050', 'Diversity of Plant Form & Function', 'Biology & Environment Science', 'The Earth''s vegetation is replete with a diversity of plant forms from 40 meter high trees to aquatics to parasites and climbers. Different plant forms are adapted for different functions. This course aims to provide students with the basic tools necessary to understand, describe and appreciate a diversity of plant form and think critically about the likely functional role of different plant structures. There will be an emphasis on the Irish Flora. Students will be introduced to the morphology of the vegetative and reproductive structures of a range of different evolutionary lineages of land plants from the most ancient (bryophytes/mosses) to the most derived (angiosperms/flowering plants). Special emphasis will be placed on the identification of species belonging to various groups using taxonomic keys.', 'https://www.ucd.ie/modules/BOTN30050', 'botn30050'),
    ('daedde3d-e0f6-4c16-ab30-f3710a32e695', v_uni_id, 'BSEN20180', 'Intro to Env Footprinting', 'Biosystems & Food Engineering', 'An environmental footprint is an estimate of the effect that a person, company or activity has, which causes a specific type of environmental impact, e.g., consumption of freshwater resources, emissions of trace gases or land use required. This module will introduce you to the concepts of water, emission, land, and ecological footprints and lead you through the calculation of your own environmental footprints using the best available guidelines, standards, and techniques. Your water footprinting (WF) estimates your personal appropriation of fresh water, considering consumption and pollution potential. Your emission footprinting (EF) is an estimate of the consequences of the emission of trace gases you are responsible for. Your land footprint (LF) is an approximation of the area of cultivable land required to support your lifestyle. Your ecological footprinting (EcF) is a measure of how much natural resources you use to support your lifestyle. We will examine the theoretical basis for each footprint and then use web-based calculators to estimate your personal environmental footprints. Finally, we will consider strategies to reduce our personal environmental footprints.', 'https://www.ucd.ie/modules/BSEN20180', 'bsen20180'),
    ('379fade8-350d-4741-9168-eef164f4e8b5', v_uni_id, 'CELB40020', 'Developmental Plant Genetics', 'Biology & Environment Science', 'This course introduces advanced biology students to fundamental research on plant developmental biology. The course focuses on reading and understanding the current literature in plant developmental genetics. For that purpose, students will read research papers and present the main scientific results in the form of short talks. Subsequent discussions will further evaluate the findings presented. This is a continuous-assessment-only module, the main body of the course consists of presentations given by students and discussions led by students.', 'https://www.ucd.ie/modules/CELB40020', 'celb40020'),
    ('1745a954-2e00-42ba-9334-d1ca43685d7e', v_uni_id, 'CELB40040', 'Cell Signalling in Plants', 'Biology & Environment Science', 'Plant growth and development are controlled by interactions between the plant, environmental conditions and intrinsic developmental programs directed by plant hormones. This series of lectures will give insights into our current understanding of how signal transduction processes are organised in plant cells and appropriate examples from animals, yeast and bacteria will be used to illustrate both conservation and divergence of signalling mechanisms between different organisms. Topics that will be discussed include the role of lipid microdomains on plasma membrane and their role in cell signalling, organisation of two-component signalling systems and the architecture of MAP kinase signalling cascades.', 'https://www.ucd.ie/modules/CELB40040', 'celb40040'),
    ('5c8e8086-f040-455a-a23b-cad0bc41c318', v_uni_id, 'CHEM00010', 'Introductory Chemistry', 'Chemistry', 'The module can only be taken by students without a strong background in Chemistry at second level. It is a pre-requisite for such students who plan to pursue any programme in Chemistry or Biology, but may also be taken as elective by students with an interest in learning the basic principles of chemistry. It will provide an overview of the subject, with an emphasis on fundamental principles and on understanding the structures and properties of familiar substances. Topics will include: atomic structure and the periodic table; chemical bonding; shapes of covalent compounds; Lewis structures; chemical reactions, including balancing chemical equations, calculating chemical amounts as moles; oxidation and reduction reactions and acid base reactions; the properties and structures of carbon compounds. The principles will be illustrated by examples of the chemistry of common elements including nitrogen, carbon, hydrogen, the alkali metals and alkaline earth metals and the halogens.', 'https://www.ucd.ie/modules/CHEM00010', 'chem00010'),
    ('0b07503c-46cb-41e5-80c4-e7d46a9137e3', v_uni_id, 'CHEM00020', 'Introductory Chemistry', 'Chemistry', 'This module introduces first-year agricultural and veterinary nursing students to the basic principles of chemistry and how this central scientific discipline applies to various fields of agriculture, including food science, farming, aquaculture, forestry, and veterinary science. Topics include the structure of atoms and molecules, as well as understanding and measuring physical properties such as mass, volume, and density. A discussion of the first experiments that helped identify parts of the atom and how these components combine to build molecules. The concepts of ionic and covalent bonding are demonstrated, along with the principles of chemical reactions. Students learn how to correctly balance chemical equations, applying the concept of limiting reagents, and calculate molecular mass, molarity and concentrations. There is an introduction to the different phases of matter, including the concept of intermolecular forces and how the type and strength of these forces relate to gases, liquids, and solids. Students learn about the concept of gases, including the ideal gas law. A detailed section is provided on the roles of acids and bases in food science. The course finishes with an examination of energy and thermodynamics. Due to the strong association between agriculture and nature, several key environmental concepts are covered, including atmospheric reactions and the operation of the water cycle. The course content is delivered through on-campus lectures. There are four experiments to be completed, each with a topic based on concepts discussed in the lectures. Continuous assessment consists of four online quizzes completed on Brightspace and four in-class quizzes (also administered on Brightspace) during the in-class tutorials.', 'https://www.ucd.ie/modules/CHEM00020', 'chem00020'),
    ('1835a11e-5008-4dd4-892f-81038d028577', v_uni_id, 'CHEM10010', 'Introduction to the Chemistry of Biomolecules', 'Chemistry', 'The module initially covers the simple chemical functional groups that are found in bio-molecules, (alkane, alkene, alcohol amine, carboxylic acid, ester, amide), their systematic naming and some of their common reactions (acid/base, oxidation/reduction, condensation/hydrolysis). Then the focus will switch to the common bio-molecules themselves (carbohydrates, fats, proteins, DNA/RNA) with a description of their structure, how they are formed and their reactions with water. Later parts of the module will deal with how and why these chemical reactions occur in terms of their energetics and rates. Finally the acidity of certain of these molecules will be discussed. Students should note that they must achieve a minimum of 40% in the practical component of this Module in order to pass the module as a whole.', 'https://www.ucd.ie/modules/CHEM10010', 'chem10010'),
    ('a52aecd9-c675-4f0e-b77e-5977676e2996', v_uni_id, 'CHEM10040', 'The Molecular World', 'Chemistry', 'This is an optional module intended for students with a background in Chemistry at Leaving Certificate or equivalent. The purposes of the module are to reinforce key basic concepts, and to introduce students to the central role that molecular science now plays in understanding our environment, technology, life processes, and in the design of new materials and medicines. The first section of the course consists of a series of case studies of important drugs, including aspirin, the beta-lactam antibiotics and cimetidine. The case studies are used to revise fundamental concepts of structure and reactivity of organic compounds, and to illustrate the development of medicinal chemistry and the key role that it plays in alleviating human suffering. The second section of the course covers several case studies which pinpoint how chemistry is applied in society, technology and how it can be employed in alleviating significant global challenges as derived from the UN sustainable development goals. Alongside with the case studies fundamental principles are covered relevant to the synthesis of synthetic polymers and structure-property correlations which contribute to the current plastic crisis. The main principles of electrochemistry (galvanic cell and thermodynamics involved), and energy storage in batteries will be also covered. Finally, the basic natural/artificial photosynthetic concepts which allow for ‘green’ H2 evolution and conversion of CO2 and waste (e. g., plastics) to useful ‘green’ fuels/chemicals will be also briefly discussed. There will be five experimental sessions associated with the module and each of these will involve student preparation (using an online assessment), carrying out experiments and a laboratory report.', 'https://www.ucd.ie/modules/CHEM10040', 'chem10040'),
    ('397ad85e-70c7-4a5f-a8e1-6a6a9108965c', v_uni_id, 'CHEM20110', 'Env & Sustainable Chemistry', 'Chemistry', 'This module is a core module for those students taking the Chemistry with Environmental and Sustainable Chemistry programme. It is also a prerequisite for a trimester 1, level 4 module in Green and Sustainable Chemistry (CHEM40960). The following topics will be covered; • Sources and effects of air and water pollution with a case study of pollutants generated by different internal combustion engines • Pollution cycles (smog, O3 depletion, greenhouse gas) and remediation • Sustainable / green chemistry • Sustainable energy generated from biomass feedstocks and solar thermal sources. • The basis and tenets of green chemistry • Hazard and risk assessment, introducing the concept of toxicity and life cycle analysis. • Identifying hazardous chemicals and designer safer ones with biodegradability. • Different methods of chemical waste treatment and the treatment of drinking water. • Green solvents including water, ionic liquids, super-critical liquids, solvent-less reactions. • New methods to induce chemical reactivity including microwave heating, photo- and sono-chemistry. • Fuel cells, energy storage in batteries, hydrogen generation and storage. There will be 2 lectures per week, workshops in weeks 6 and 12 and student group presentations in weeks 3 and 9. The laboratory sessions (of which there are 6) will consist of experiments with following themes: • Colourimetric analysis of nitrate concentration in different sources of water. • Synthesis of biodiesel from different commercial oil sources. • A green chemistry approach to the bromination of stilbene. • Conducting a chemical reaction only in the solid-state. • Application of a homogeneous organo-catalyst. • Understanding the physical properties of biphasic aqueous solutions.', 'https://www.ucd.ie/modules/CHEM20110', 'chem20110'),
    ('281ca540-ccc8-4ab6-9faa-98bcb551b358', v_uni_id, 'CHEM40860', 'Chemistry Outreach: Development and Practice', 'Chemistry', 'Distinction/Pass/Fail (GPA Neutral) This module, designed for postgraduate students, introduces them to the subject of outreach, whereby they learn how to interact with and disseminate basic chemistry knowledge to the general public. Importantly, this module teaches postgraduates how to build and present public presentations and chemical demonstrations. In particular, postgraduates will have a chance to visit local Dublin area secondary or primary schools and present their research to a young audience. Moreover, in group session work, discussions on the public’s ideas and attitudes towards chemistry are examined. Finally, an outline of how to utilize basic outreach concepts to construct a positive public image is given.', 'https://www.ucd.ie/modules/CHEM40860', 'chem40860'),
    ('86e6f4e5-1121-4d1b-afbc-06949b5ba847', v_uni_id, 'CHEM41460', 'Env Sus Chem Research Project', 'Chemistry', 'This module comprises a substantial body of research in an area of Environmental or Sustainable Chemistry, undertaken under the supervision of one of the members of the School of Chemistry, sometimes in collaboration with staff from other Schools or Centres. The research is carried out in conjunction with that of the supervisor''s research group.', 'https://www.ucd.ie/modules/CHEM41460', 'chem41460'),
    ('6678346f-8133-4822-8a1f-96bac884491d', v_uni_id, 'CHEM41530', 'Green & Sus Chem - Taught MSc', 'Chemistry', 'This module is for students on taught MSc programmes. It covers advanced topics related to green and sustainable chemistry. In particular, this module goes into more in-depth aspects of the 12 principles of green chemistry, which are the core concepts for green transformation of chemistry, The course begins with an introduction to the history and development of industrial chemistry, leading to the current status and production of crucial fundamental chemicals. The sustainable section of the module includes the development of the application of alternative and renewable energy sources, including the creation of fuels (methanol and hydrogen) and platform chemicals from biomass and artificial photosynthesis. Importantly, a detailed discussion of the current technology which is used to convert and store solar energy along with energy derived from nuclear reactions. An essential aspect of sustainable are the challenges, issues and solutions related to element sustainability. The environmental section discusses advanced aspects of air pollution and current methods in pollution remediation. The green chemistry section is divided into two major topics, including the application of catalysis enabling them to function under mild conditions and in non-toxic, alternative media (in comparison to traditional organic-based solvents). Specific examples of the green transformation of fundamental industry reactions in synthetic chemistry, including oxidation and reduction, carbon-carbon bond formation, and carbon-hydrogen bond activation are outlined. Importantly, tools to understand the greenness of a reaction are introduced termed green metrics. Finally the course introduces the concept of process intensification and includes a discussion on reactor design, such as the use of flow- and membrane-based reactors. Additionally, cutting-edge synthesis techniques (process intensification) such as micro-reactors, mono-lithic supported catalysis and reactive distillation demonstrate how traditional large scale polluting chemical factories are replaced by small foot-print and environmental compatible modulator reactors. A significant portion of the module will involve the preparation and delivery of a report on some aspect of Green and Sustainable chemistry touched on in the lectures. This will involve data collection and analysis from the Green Chemistry Literature', 'https://www.ucd.ie/modules/CHEM41530', 'chem41530'),
    ('72ba07f0-797e-4ad2-9efc-579cf606602f', v_uni_id, 'CHEN10040', 'Intro. to Eng. Computing', 'Chem & Bioprocess Engineering', 'In this module students are introduced to computers, computer systems and software with a view to using these as tools in solving problems and, as a result, in developing problem-solving skills. This is achieved through training in programming in both Microsoft Excel™ and Matlab™ environments, applied to a number of engineering-based case studies. Course Content (note: laboratories include instruction in topic; numbers re. lectures/laboratories are for guideline purposes only and may be subject to change) 1. Introduction (2 lectures) Computers, Computer Systems and Software Data, Data Management, Ethics in Data/Technology 2. Problem Solving and Algorithm Development (4 lectures) 3. MS Excel™ (6 lectures + 2 to 3 laboratories) Introduction Entering and formatting formulas Built-in functions Select Applications in Excel Interpolation Data Analysis Solver/Optimisation Macros/Introduction to VBA in Excel 4. Matlab™ (6 lectures + 4 to 5 laboratories, including 1 lecture + 1 laboratory for each of 3 case studies) Introduction to the MatlabTM Environment Scalars, Vectors, Matrices, Strings I/O, including graphing Functions Matlab Programming User defined functions and anonymous functions Iteration and Decision Data structures in Matlab™ Matlab™ Case-Studies (based on Engineering Problems associated with individual disciplines)', 'https://www.ucd.ie/modules/CHEN10040', 'chen10040'),
    ('4ad3c820-fd07-483c-b185-fba091023597', v_uni_id, 'CHN30060', 'Chinese Economy', 'Irish Institute for Chinese St', 'This module aims to provide students with a basic understanding of the contemporary Chinese economic system and an analytical framework for the study of modern Chinese business behaviour. It covers 10 key topics which together serve to introduce students to China''s economic reform and give a comprehensive account of the modern Chinese economy. Students will develop the ability to comprehend and analyse major theoretical and policy issues in China''s economic development and transformation and their implications for the business environment and practices.', 'https://www.ucd.ie/modules/CHN30060', 'chn30060'),
    ('a642acd8-05fa-4cfc-9bf8-c35bab084628', v_uni_id, 'COMP10010', 'Introduction to Programming I', 'Computer Science', 'This is a module for all students interested in using and understanding computers. In this module students will learn the practical skill of how to program a computer to make it do what they want it to do. Students will learn how to write simple computer programs that can solve problems; how to write simple programs that can process different sorts of information; and how to write programs that can respond differently to different situations. Students will find these skills very useful in all areas of study, not just computer science.', 'https://www.ucd.ie/modules/COMP10010', 'comp10010'),
    ('ea14ae52-21e2-4394-acb2-b9e05c4daca3', v_uni_id, 'COMP10040', 'Introduction to Computer Architecture', 'Computer Science', 'This course provides an introduction and practical overview to computer architecture and organisation. There is a brief historical review of the evolution of computers leading to today''s architecture. The digital electronic circuits underlying computer systems are explained with an introduction to the basic concepts of the transistor and integrated circuits. The main emphasis of the course is to present an understanding of the operation of a typical modern computer from the conceptual instruction level down to the electronic implementation of these instructions. The main components of the module are: 1. A review of the historical evolution of modern computer systems and the emergence of the Von Neumann architecture. 2. Data and number representation in digital computer systems. 3. Instruction format and execution. 4. The basics of integrated circuits: the transistor and logic gates. 5. Boolean algebra and logic circuits. 6. Computer architecture. 7. The Memory hierarchy. 8. Cache memory systems. 9. AI Architectures: GPUs 10. Environmental Impact of Data Centres and the Internet Students will be given exercises to complete approximately every 2-3 weeks. “If students are permitted to use generative AI tools in assignments, that will be indicated in the assignment specification." Use of AI by students in exercises must be declared.', 'https://www.ucd.ie/modules/COMP10040', 'comp10040'),
    ('1e8c24fa-c48e-44bc-add0-43ea8a56946f', v_uni_id, 'COMP10050', 'Software Engineering Project 1', 'Computer Science', 'This module focuses on developing a student''s ability to program and is designed to supplement the Introduction to Programming modules COMP10110 and COMP10120. The main goal is to give the student experience in developing software programs that are significantly larger than those encountered in COMP10110 and COMP10120. On completion of the module the student will have developed at least three software programmes comprising more than 100 lines of code.This module also provides an introduction to some ideas and methods in professional software development. Students are encouraged to use a professional Integrated Development Environment such as Microsoft Visual Studio for project work. The important role of software testing is software development is also emphasised throughout the module. Students are also introduced to the complexities of large scale software development through seminars by external speakers from industry.', 'https://www.ucd.ie/modules/COMP10050', 'comp10050'),
    ('afe9f342-9f5e-4902-9f22-1b3136c593d5', v_uni_id, 'COMP10060', 'Computer Science for Engineers I', 'Computer Science', 'This course provides students with an introduction to computer programming. Major topics include algorithm development, programming fundamentals, control flow, and data structures. By the end of the course, students will be able to write simple programs to solve small-scale problems. The module is introductory in nature and assumes no previous programming knowledge, and so is suitable for first year students, who require a formal and structured introduction.This module will include weekly two-hour computing practicals. It is a requirement that you have access to your own laptop to undertake the practical elements and to learn how to code.', 'https://www.ucd.ie/modules/COMP10060', 'comp10060'),
    ('5929574f-a464-4a83-898e-1b58cb8b74aa', v_uni_id, 'COMP10070', 'Formal Foundations 1', 'Computer Science', 'In addition to becoming skilled in Programming and Problem Solving, Computer Scientists need to be aware of the limitations of particular techniques and be able to test for correctness of programs they produce. This course introduces students to the logical fundamentals underlying proof of correctness (propositional and predicate logic, proof techniques) and to the concept of a finite state machine, a restricted computational model used in many application domains. This course is very practical in nature and students will be required to apply the techniques they have learned to a particular set of problems.', 'https://www.ucd.ie/modules/COMP10070', 'comp10070'),
    ('5b9be748-26c5-48fb-a5c5-c199a156ccfc', v_uni_id, 'COMP10110', 'Computer Programming I', 'Computer Science', 'In this module students will learn how to program a computer using a simple programming language (e.g. C). Students will learn how to make many simple things happen and how to solve simple problems by programming. After taking the course the students should be able to: understand the basic ideas of programming and be familiar with variables, arrays, strings, conditionals, loops, terminal I/O, functions, etc.; confidently write computer programs in the language they have learned during the course; run programs, to produce results.', 'https://www.ucd.ie/modules/COMP10110', 'comp10110'),
    ('5c6ebfe2-93db-4716-8eef-9aa1e02fd775', v_uni_id, 'COMP10120', 'Computer Programming II', 'Computer Science', 'This module builds on the topics covered in COMP 10110 (Computer Programming I). Some core concepts covered in COMP10110 will be revisited through new examples and applications. Other topics covered include program design, recursive functions, enumerations, pointers, dynamic memory allocation, file processing, structures, linked list and multi-dimensional arrays. Examples and concepts are typically presented in C. A strong emphasis is placed on the development of practical programming skills for building software applications to solve real problems. The course is designed to give a sound understanding of programming techniques, and how to get your application programs from the design phase to implementation.', 'https://www.ucd.ie/modules/COMP10120', 'comp10120'),
    ('7969d8d7-1ca0-4c85-bdc8-ec9a4967489b', v_uni_id, 'COMP10300', 'Functional Programming', 'Computer Science', 'This course introduces students to a different style of programming ("functional programming") using a simple, elegant and fun language called Scheme. The course will cover a range of functional programming topics including (but not limited to) function definition, representations using lists, recursion, double recursion, recursive problem solving, and lambda.', 'https://www.ucd.ie/modules/COMP10300', 'comp10300'),
    ('dee3f602-586e-4663-9539-53bd7215084c', v_uni_id, 'COMP10310', 'Web Design', 'Computer Science', 'Website design involves the planning, production and maintenance of website content. This introductory level module assumes no prior experience in web design. Topics covered include: HTML syntax, composition, and validation; cascading style sheets (CSS); basic dynamic scripting examples; site planning, visual information management and responsive design; digital image formats; and Search Engine Optimisation (SEO). Please note that any student taking this module must have their own laptop. It is important that students are available at the times allocated for both the lecture and lab slots. This module requires no prior background in web design but having a basic understanding of programming would be an advantage.', 'https://www.ucd.ie/modules/COMP10310', 'comp10310'),
    ('2ae2b2f3-fcc3-43f4-ac98-43b78a3e3062', v_uni_id, 'COMP10320', 'Intro to Data Science and AI', 'Computer Science', 'This module introduces students to the world of data science, an important sub-discipline of computer science, which focuses on learning about the world by analysing data. This module will give students an introduction to the Python Data Science Ecosystem. Students will learn the fundamentals of Python programming and important Python tools and technologies for data science, including Pandas for data manipulation and analysis and Matplotlib for data visualisation. Students will gain valuable practical experience in many important aspects of data science including data collection and cleaning, data exploration and analysis, visualisation and prediction. The module will also provide an overview of important trends in and current topics in Data Science and AI, for example: - Social Network Analysis - Generative AI and Large Language Models - Machine Learning & Health - Bias & Fairness in Machine Learning - Sport Analytics Note: If students are permitted to use generative AI tools in assignments, that will be indicated in the assignment specification.', 'https://www.ucd.ie/modules/COMP10320', 'comp10320'),
    ('122cf6fa-a718-4142-9687-20aaf53242ec', v_uni_id, 'COMP10330', 'Critical Thinking in Software Development', 'Computer Science', 'Distinction/Pass/Fail (GPA Neutral) The module provides students with the foundational knowledge and develops their critical thinking skills towards making informed decisions in their professional journey and future career. The weekly lectures are designed to help students develop a deeper understanding of longstanding and emerging issues in technological innovation, considering their short and long term impact on humans, societies, and ecosystems. The practical sessions focus on exercises designed to train students'' critical thinking skills. During the weekly practicals, students will have the opportunity to reflect on real case studies and engage with diverse perspectives. The guided in-pair discussions will support students in developing and formulating their own perspective on a contemporary technological innovation issue, critically engage with another perspective, reflect on the similarities and differences, and move beyond these to propose concrete ways to tackle the challenges identified.', 'https://www.ucd.ie/modules/COMP10330', 'comp10330'),
    ('09d02a99-8f79-4125-bb3c-6474cf7698ae', v_uni_id, 'COMP20020', 'Digital Systems', 'Computer Science', 'The module reviews the theory and practice of designing digital systems. Boolean logic and binary number systems are reviewed. Design of combination circuits is covered including truth tables and a range of basic circuits (decoders, encoders, multiplexers, adders, subtracters, multipliers). Use of Karnaugh maps for logic minimisation is explained. Design of sequential circuits is covered including basic elements (clocks, latches and flip-flops) and basic circuits (counts, shift registers). Specification and design of Finite State Machines is explained. Memory systems are described. Design issues including race conditions, hazards and glitches are considered. An introduction to computer system implementation is given.', 'https://www.ucd.ie/modules/COMP20020', 'comp20020'),
    ('b56245c9-59a4-4e1b-a46d-eb280ec1455c', v_uni_id, 'COMP20050', 'Software Engineering Project 2', 'Computer Science', 'The module has two main goals. The first goal emphasizes students working in teams and applying a modern software engineering methodology called Scrum to deliver a working software application with complexity reflective of a real-world software project. On completion of the module, the students are expected to understand how professional software developers practice Scrum. The second goal focuses on evolving a student’s knowledge and skills of the core software engineering concepts, principles of good software architecture, code quality, test quality and documentation. On completion of the module, the students are expected to understand sound software design principles and apply them in their software applications'' design, development and testing.', 'https://www.ucd.ie/modules/COMP20050', 'comp20050'),
    ('9d47abcb-3741-4b18-ada1-8fab352b1231', v_uni_id, 'COMP20070', 'Databases and Information Systems I', 'Computer Science', 'Collection, organisation and storage of data are major tasks in many human activities and in every modern computing system. Computer-based information systems ensure that this data is permanently maintained, quickly updated and made accessible to users. Databases are essential components of computerised information systems. This is a module for students interested in understanding how to design, develop and query databases. In this module students will learn the fundamentals of database models, database designing methodologies, database querying. They will learn details about the relational database model, relational database query languages (relational algebra, SQL), the entity-relationship model for database design. From a more practical point of view they will gain experience in building a relational database. Students will find these skills useful in the development of applications requiring the storage and manipulation of data.', 'https://www.ucd.ie/modules/COMP20070', 'comp20070'),
    ('3bae4418-8f28-492e-b5e8-72e0b036ab98', v_uni_id, 'COMP20180', 'Intro to Operating Systems', 'Computer Science', 'The course is an introduction to operating systems, with an emphasis on fundamental principles underlying modern general-purpose operating systems. The course is based on exploring and modifying a teaching operating system running on a simulated RISC-V computer. References to popular operating systems are also made at different points in order to illustrate concepts and/or implementation issues. The course starts with an introduction to “bare metal” programming using a combination of C and RISC-V assembly languages. The important concepts and historic developments related to Operating Systems are then introduced using a combination of lectures, historic videos, and practical assignments in which students develop extensions to the teaching operating system. These concepts include interrupts, executable file, execution context switching, process, system call, driver, file system, Unix system call API and shell language, process scheduling, virtual memory, interprocess synchronisation and communication.', 'https://www.ucd.ie/modules/COMP20180', 'comp20180'),
    ('03195001-9f89-4b2d-862e-200707e2862b', v_uni_id, 'COMP20200', 'UNIX Programming', 'Computer Science', 'This course focuses on introducing students to the core concepts of the Unix operating system and how to programme this system. Today, Unix and Unix-like operating systems are ubiquitous; they are widely used in servers, embedded devices and have a growing desktop and mobile market (Linux, Mac OS X, Android etc.). This module will teach students how to develop applications for such systems, assuming no other software layer but OS. Students will improve their existing C programming language skills and will learn some key POSIX APIs to support designing and writing programs in a portable, maintainable fashion. They will learn how to write mutlithreaded and multi-process applications as well as some basics of Unix networking. All this will be done through the Unix command line, and students will learn basic tools and how to write shell scripts to automate common tasks. Students will need a version of Unix installed on their own laptop (ideally Linux), help with this will be provided in the first lab.', 'https://www.ucd.ie/modules/COMP20200', 'comp20200'),
    ('a53cb94d-a665-4070-919f-ca64ffec1118', v_uni_id, 'COMP20280', 'Data Structures', 'Computer Science', 'The key objective of this module is to provide students with a grounding in essential data structures through Java. Students will build their own repository of data structures including linked lists, stacks, queues, deques, trees, hashtables. Designing and building the data structures in Java will provide insight into how the data structures are constructed, their performance characteristics, and their wider use in computer science. This module requires a reasonable level of Java (''Introducton to Java'' is essential).', 'https://www.ucd.ie/modules/COMP20280', 'comp20280'),
    ('f5c0e7c8-f43c-4c58-9bae-ecc022c6f3fc', v_uni_id, 'COMP20290', 'Algorithms', 'Computer Science', 'We increasingly live in a world that is driven by algorithms and the services they provide touch our lives in multiple ways, underpinning how we navigate the world, how we retrieve information, how we play and how we manage our health. In this module, you will learn some of the fundamental and most powerful concepts in computer science that distinguish good programmers from talented computer scientists. This module will cover the following major concepts: Introduction to Algorithm Analysis Pseudo Code Divide and Conquer Algorithms Dynamic Programming Algorithms Greedy Algorithms Brute Force Algorithms This module will cover sorting, searching, and data compression algorithms.', 'https://www.ucd.ie/modules/COMP20290', 'comp20290'),
    ('b7021870-a262-4dae-98fe-d9368b7d0d79', v_uni_id, 'COMP20320', 'Computer Networking', 'Computer Science', 'This module introduces the OSI stack to students, and goes through the various layers in detail. The topics covered include: Network Types, functions, topologies, transmissions, switching, routing, management, reference models, architectures, protocols and standards; network user applications; flow and congestion control strategies; design and implementation considerations; use in Internet systems. There will be a few hot topics included each year.', 'https://www.ucd.ie/modules/COMP20320', 'comp20320'),
    ('96c37a31-7228-4e39-a6c8-821f87f3b8a3', v_uni_id, 'COMP20330', 'Functional Programming II', 'Computer Science', 'This module builds on the stage 1 Functional Programming module COMP10300. Where that module focused mainly on recursion and covered some basic functional ideas (functions as arguments, map and filter, introduction to closures) in the language Scheme, this second Functional Programming module will teach ''Pure'' Functional programming in the language Haskell, focusing on the use of static types and type structures, pattern matching, list comprehensions, lazy evaluation, infinite data structures and related topics. This module will also teach approaches to the "broader problem" of programming: producing problem descriptions that allow algorithmic solutions, verifying the correctness of solutions, and identifying problems at the levels of code, algorithm, and problem statement. These topics will be taught using generative ''AI'' assistants such as chatGPT or Copilot: using these tools to generate code requires the programmer to to focus on these "broader problem" questions in depth.', 'https://www.ucd.ie/modules/COMP20330', 'comp20330'),
    ('ed3da7fc-5246-4d23-8da2-4244e9bc8a89', v_uni_id, 'COMP20340', 'Requirements Engineering', 'Computer Science', 'The module will introduce learners to best practice in the critical initial stages of development of large and complex, real-world software systems. The module assumes prior learning of at least one high-level language (Python, Java, C, C++, or similar): it is not a general introduction to software design. Learners with no prior programming experience are not advised to take this module. The module will introduce software systems requirements analysis and management using the tools and methods of requirement engineering (RE) in the era of GenAI. First we will examine the design challenges in the systems development or software engineering lifecycle for large scale systems. Then we describe the role of requirements engineering in addressing these challenges. This will include understanding software requirements specifications, system context like stakeholder goals and constraints, techniques for gathering requirements (e.g. use cases), domain modelling, non-functional requirements and managing the requirements artifacts will be covered. Emphasis will be placed on developing basic system analysis and modelling skills, applying standards and engaging with real world case studies.', 'https://www.ucd.ie/modules/COMP20340', 'comp20340'),
    ('e892622f-e352-4de6-8cc1-bba9896080d1', v_uni_id, 'COMP20350', 'Object-Oriented Programming', 'Computer Science', 'This module is suitable for students interested in introduction to OOP through the Java programming language, building upon prior exposure to programming languages. Specific topics addressed in this module include: • Introduction to Object Oriented Programming • Class Design, Inheritance, Polymorphism • I/O • Unit Testing • Programming in Java', 'https://www.ucd.ie/modules/COMP20350', 'comp20350'),
    ('74db91e5-0c4b-4ef9-b73f-c36457c36373', v_uni_id, 'COMP20360', 'Formal Foundations 2', 'Computer Science', 'This module is intended to introduce a range of topics in discrete mathematics and automata theory which are frequently used in Computer Science. Topics include predicate calculus, elementary number theory and combinatorics, and an introduction to finite automata.', 'https://www.ucd.ie/modules/COMP20360', 'comp20360'),
    ('8117504a-6cdc-4870-8773-a25dc4f63828', v_uni_id, 'COMP20390', 'Introduction to Cybersecurity', 'Computer Science', 'This course is an introduction to cybersecurity. Students are only required to have basic ICT skills to take this course. The course covers the following topics: • Threats, vulnerabilities and risks • Cyber attacks and attack lifecycle • Authentication and access control • Cryptography fundamentals • Secure behaviour and human factors • Web and internet security fundamentals • Data security and privacy • Governance, ethics and legal issues • Security in practice Lecture attendance is mandatory.', 'https://www.ucd.ie/modules/COMP20390', 'comp20390'),
    ('df73c4aa-bed0-4647-a774-66502f2b058c', v_uni_id, 'COMP30060', 'Program Construction I', 'Computer Science', 'This module is intended to introduce students to the idea of the formal correctness of algorithms. We show how how to specify programs as Precondition, Postcondition pairs. We show how programs can be calculated from such specifications. We also show how we can generalise from these solutions to abstract problems and their solutions.', 'https://www.ucd.ie/modules/COMP30060', 'comp30060'),
    ('bd38a7b9-9a2a-4cb7-89ff-c855f4a178a7', v_uni_id, 'COMP30190', 'Program Construction II', 'Computer Science', 'This module follows on from Program Construction I and builds upon the knowledge and skills that have been learned in it. Once again the core aim is to show how to calculate correct algorithms. We lay particular emphasis on constructing efficient solutions. We examine a collection of problems whose solutions exploit properties such as symmetry, monotonicity and operator distribution.', 'https://www.ucd.ie/modules/COMP30190', 'comp30190'),
    ('617b36f3-3769-4b24-b349-1d15ef55a11e', v_uni_id, 'COMP30690', 'Information Theory', 'Computer Science', 'This course provides an introduction to the fundamentals of Information Theory for computer scientists. Shannon''s Information Theory is one of the greatest intellectual achievements of the 20th century. It provides a comprehensive view on the concept of information, whereby fundamental limits to the performance of practical algorithms are established. Information Theory concerns all areas where information is processed, stored or transmitted in some way or another. Consequently, it is an essential component in the education of a computer scientist.', 'https://www.ucd.ie/modules/COMP30690', 'comp30690'),
    ('63425dad-b5a5-4273-8f99-925234dd6dca', v_uni_id, 'COMP30960', 'Human Computer Interaction', 'Computer Science', 'Human-Computer Interaction (HCI) is a distinctive branch of computer science dedicated to understanding the relationship between people and computers. It provides a set of techniques that enable software engineers to develop computing applications that better respond to the needs, abilities and interests of customers, clients and end-users. This module provides theoretical grounding, practical knowledge, and hands on experience of key skills needed to design and build better interfaces for computing systems. The module addresses core areas of the ACM SIGCHI Curricula for Human-Computer Interaction and is intended for students with no prior experience in Human Computer Interaction. The module covers the following core topics: 1. Human cognition and models of interaction 2. Usability and user experience 3. Interface design using user-centred and iterative methods 4. Interface development and rapid prototyping 5. Experimental design and statistics for HCI 6. Qualitative and quantitative evaluation strategies This module will also emphasise the overlap between HCI and software engineering, and consider ways in which interface and software lifecycles can complement and hinder the development of effective interfaces. Please note: This module is an introductory module. It is not appropriate for students with prior experience of human computer interaction, e.g. those who have previously taken a module in human computer interaction, interaction design, or user experience.', 'https://www.ucd.ie/modules/COMP30960', 'comp30960'),
    ('fa09d22d-6cd3-4957-8ec8-d4b094ae4bdf', v_uni_id, 'COMP31020', 'Formal Foundations 3', 'Computer Science', 'This module covers a branch of computer science called language and automata theory, focusing on concepts from computing theory and complexity theory. In particular, it discusses computation models (finite automata, regular expressions, pushdown automata, Turing machines), undecidability (what can be computed at all?), and intractability (how fast can it be computed?). The student will come to understand how these theories relate to, and are used in, everyday practice. Students learn concepts, tools, and techniques individually through a series of written exercises. There are weekly tutorial sessions with demonstrator support.', 'https://www.ucd.ie/modules/COMP31020', 'comp31020'),
    ('2668d622-ab46-4866-8922-7ff477d14989', v_uni_id, 'COMP40660', 'Advances in Wireless Networking', 'Computer Science', 'Overview of current and future wireless technologies, with an emphasis on networking and application aspects; overview of mobile/cellular systems; discussion of relevant IEEE standards (e.g. 802.11 and 802.16); introduction to mobile/wireless applications.', 'https://www.ucd.ie/modules/COMP40660', 'comp40660'),
    ('cebc3658-b93c-4982-8c67-7e833d3a875d', v_uni_id, 'COMP41110', 'Cloud Computing', 'Computer Science', 'Nowadays Cloud Computing is everywhere. Cloud Computing (CC) is not a revolution of Information technology (IT), but It is one of the key evolution steps of IT. It provides computing as a utility, which has recently emerged as a commercial reality. The main characteristics of CC are 1) the illusion of infinite computing resources, 2) the ability to pay-as-you-use, and 3) the elimination of an up-front commitment by Cloud users. In other words, CC is a style of computing in which can be scaled dynamically and virtualised resources are provided as a service over the Network The key idea behind this course is to introduce the CC environment i.e. Parallel Computing, Distributed Computing and Distributed File Systems and then to focus on the services provided by the cloud, namely Software As A Service, Infrastructure As A Service, and Platform As A Service. Other concepts, such as security and the economics of the Cloud, will also be covered. Finally, some existing clouds such as Google cloud, Microsoft Azure, Amazon cloud will be presented, compared, and future directions of the Cloud industry will be discussed.', 'https://www.ucd.ie/modules/COMP41110', 'comp41110'),
    ('c880162d-325c-43ea-977c-161f07bfffa5', v_uni_id, 'CVEN10060', 'The Engineering and Architecture of Structures 1', 'Civil Engineering', 'The purpose is to provide students with a core understanding of what makes buildings, and other structures, stand up. Engineering and Architecture students will work in together in groups to explore these issues. There are four themes, each dealt with over 3 weeks. In each week, there will be a mixture of lecture and tutorial sessions where students will discuss the issues, undertake practical tasks and develop their solutions to the theme. The four themes are: A. Forces and Equilibrium B. Materials and their Properties C. Distributions of Forces in Structures D. How Structures Stand Up.', 'https://www.ucd.ie/modules/CVEN10060', 'cven10060'),
    ('0a8eae78-3e26-4570-80b4-b35ca6bf0e9e', v_uni_id, 'CVEN20040', 'The Engineering & Architecture of Structures 2', 'Civil Engineering', 'This module develops student’s abilities to prepare scheme designs for a range of structures. This involves the determination, by qualitative review, of the appropriateness of a structural element''s material, shape and size to the demands of loading. Students will develop qualitative understanding of load paths, structural forms and structural responses to load.', 'https://www.ucd.ie/modules/CVEN20040', 'cven20040'),
    ('3c9cc7f7-6aae-4178-a036-2fbe90d54380', v_uni_id, 'CVEN40050', 'Design of Structures 3', 'Civil Engineering', 'CVEN40050 is one of the last structural design modules in the program and is designed to prepare the students towards the near future professional life as graduate structural engineers. It covers the two most widely used construction materials (RC and steel) in a comprehensive way. The aim is that the students can prepare code-compliant structural designs based on clear understanding of the structural design principles and code implementation. The module provides an overview of the structural design process and the concepts of reliability, stability and robustness, and is based on Eurocode. It covers sustainability in structural design, the detailed design of reinforced concrete beams for flexure, shear, and torsion, design of slender reinforced concrete columns, design of suspended floors, including ribbed and flat slabs, design of water retaining structures and associated calculation of crack width, as well as strut and tie modelling. The module also covers the design of steel single and multi-storey buildings, design to satisfy lateral stability, and the concepts of plastic analysis and design. The design of steel/concrete composite construction is also covered.', 'https://www.ucd.ie/modules/CVEN40050', 'cven40050'),
    ('0c7155ce-db92-497f-95e9-6f5a290df64f', v_uni_id, 'CVEN40060', 'Transport Modelling', 'Civil Engineering', 'Fundamentals of Transport operations and planning: - Understanding the theories behinds travel choice behaviour - The classic 4 stage model, models used in Ireland - What are the data requirements and sources of data for transport models and how is the data collected? - The model estimation, calibration and validation process - Critiques of the four-stage modelling - Traffic assignment models - Disaggregate models - How is modelling used in policy formulation and appraisal?', 'https://www.ucd.ie/modules/CVEN40060', 'cven40060'),
    ('5441281b-5943-435d-84c4-bd3ed63a3841', v_uni_id, 'CVEN40120', 'Bridge Engineering', 'Civil Engineering', '1) INTRODUCTION: Structural forms, cross-sections, bridge elevations, bearings, joints, substructure, bridge aesthetics, habitat fragmentation, bridge deterioration and monitoring. 2) BRIDGE LOADING: Safety factors and loading combinations, dead and superimposed dead loading, imposed traffic loading, thermal loading, creep and shrinkage, differential settlement, impact loading, dynamic effects, prestress loading. 3) 2-D AND 3-D MODELLING OF BRIDGE DECKS: Thin plate theory, grillage and finite element analysis, simple isotropic slabs, edge cantilevers and edge stiffening, voided slab bridge decks, beam and slab bridges, cellular bridges, skew and curved bridge decks, three-dimensional analysis.', 'https://www.ucd.ie/modules/CVEN40120', 'cven40120'),
    ('c2935ea4-acb5-4e83-ab72-099e5d1530ab', v_uni_id, 'CVEN40690', 'Civil Engineering Systems', 'Civil Engineering', 'A selection of topics under the following headings... 1. Introduction to Systems Analysis. 2. Decision makers and their objectives 3. Assessment criteria, 4. Generation of alternative solutions 5. Computer Modelling and Simulation. 6. Optimisation 7. Multi-criterion decision analysis (MCDA)', 'https://www.ucd.ie/modules/CVEN40690', 'cven40690'),
    ('47fe8982-6b2b-40f1-9a36-33b16dda9dbe', v_uni_id, 'CVEN40710', 'Highway Engineering', 'Civil Engineering', 'Students will be introduced to concepts of pavement engineering and highway design. Bituminous mix characterisation, mix design and volumetric analysis will be a particular focus. Design approaches and developments in test methods will be discussed. Aspects of geometric design will be outlined and the important aspects of pavement evaluation and maintenance will be introduced.', 'https://www.ucd.ie/modules/CVEN40710', 'cven40710'),
    ('5eb6cc1b-fe19-4b67-924b-9ad26ba715ba', v_uni_id, 'CVEN40720', 'Geotechnics 3', 'Civil Engineering', '1. Shallow Foundations – Bearing capacity, settlement, non-vertical loads 2. Deep Foundations- Pile Types, Axial Loading, Lateral Loading 3. Underground Construction – Types of retaining structures, embedded walls, practical issues 4. Site Investigation – Desk study, in-situ tests, lab tests, interpretation, selection of parameters. 5. Rock Mechanics – Overview, shallow foundations, piled foundations.', 'https://www.ucd.ie/modules/CVEN40720', 'cven40720'),
    ('356c450c-f767-40a6-bb42-751c5555bcae', v_uni_id, 'CVEN40760', 'Case Studies', 'Civil Engineering', 'Develop capability to solve conceptual structural design problems. Develop qualitative understanding of load paths and structural response to load. Choose appropriate efficient and cost-effective geotechnical solutions for given outline problems. Students are assigned into groups. Each group is given scheme designs to complete. Groups must present an oral and written design solution for each scheme. Each case study is presented to colleagues and experts from industry and academia in an interruptible forum.', 'https://www.ucd.ie/modules/CVEN40760', 'cven40760'),
    ('191259d9-38f3-44f5-9b4a-b493715b8220', v_uni_id, 'CVEN40810', 'Engineering Report 2', 'Civil Engineering', 'This is a core, degree-year module for students in the BE of Civil Engineering. In this module, students work in pairs to undertake an engineering research project. Project titles are issued at the beginning of Autumn, and allocated based on academic achievement (grade point averages). Students are also encouraged to propose their own projects for consideration. Once teams have been formed and project assignments finalised, students devise research plans to accomplish the projects. Student teams meet regularly with, and receive broad guidance from, academic supervisors, but teams must work largely on their own initiative.', 'https://www.ucd.ie/modules/CVEN40810', 'cven40810'),
    ('fe6d304a-d06a-49c8-b520-0ce6541a536e', v_uni_id, 'CVEN40820', 'Engineering Report 1', 'Civil Engineering', 'This is a core, degree-year module for students in the BE of Civil Engineering. In this module, students work in pairs to undertake an engineering research project. Project titles are issued at the beginning of Autumn, and allocated based on academic achievement (grade point averages). Students are also encouraged to propose their own projects for consideration. Once teams have been formed and project assignments finalised, students devise research plans to accomplish the projects. Student teams meet regularly with, and receive broad guidance from, academic supervisors, but teams must work largely on their own initiative.', 'https://www.ucd.ie/modules/CVEN40820', 'cven40820'),
    ('e108e908-f918-41a3-9d1a-ce2c3452e8cf', v_uni_id, 'CVEN40830', 'Applied Hydrology', 'Civil Engineering', 'Water is one of the critical natural resources that is essential for life and is key to most of the United Nations Sustainable Development Goals (SDGs). Especially to Goal 2: Zero Hunger; Goal 3: Good Health and Well-being, in particular Target 3.9; Goal 6: Clean Water and Sanitation; Goal 11: Sustainable Cities and Communities; Goal 12: Responsible Consumption and Production; Goal 13: Climate Action; Goal 14: Life Below Water; and Goal 15: Life on Land. Hydrology aims captures the occurrence, distribution and movement of water on earth, i.e. the hydrological cycle while applied hydrology use scientific understand to solve water related problems in society, especially related to quantity and quality. This module will explore the concepts of hydrology and the varying methods and techniques to analyse the hydrological cycle from precipitation to discharge.', 'https://www.ucd.ie/modules/CVEN40830', 'cven40830'),
    ('b606a3e2-abec-4435-babd-a53753409e9d', v_uni_id, 'DEV20010', 'Topics in Intl Development', 'Politics & Int Relations', 'This module is designed to introduce students to key themes and debates in the field of international development. It provides both a historical foundation and a contemporary perspective on major issues shaping development outcomes across the world. The course begins with an exploration of the historical origins of development and underdevelopment tracing how colonial legacies and global inequalities have shaped divergent development paths. Building on this foundation, students will be introduced to the concept of the “Middle-Income Trap”—what it is, why some countries remain stuck in this trap, the socio-economic consequences of stagnation, and the policy strategies through which countries may attempt to escape it. We then turn to contemporary challenges and debates in development. Key themes include the impact of globalization, particularly international trade and foreign direct investment, on economic growth and social outcomes. The course also introduces the role of institutions in development. We ask What are institutions? Why are they important? Students will examine how institutional quality influences growth, investment, and prosperity, with special attention to the colonial origins of comparative development. Another major theme explored is corruption and crony capitalism. The module investigates why corruption persists, contrasting the “Grease the Wheels” versus “Sand the Wheels” perspectives, and assessing the developmental consequences of corruption. We also discuss strategies for combating corruption, drawing on both conventional approaches and innovative, out-of-the-box solutions. The course concludes by examining development aid and finance. Students will engage with fundamental questions like What is aid? Who gives aid, to whom, and why? What are the political motivations and consequences of aid flows? Alongside bilateral and multilateral aid, attention will be given to development finance through international financial institutions such as the World Bank and the International Monetary Fund (IMF), evaluating their role in shaping economic policies and development trajectories. By the end of this module, students will have gained a broad yet critical understanding of the historical, political, and economic dimensions of development, while engaging with some of the most pressing debates in the field today.', 'https://www.ucd.ie/modules/DEV20010', 'dev20010'),
    ('0d1aa316-bbec-403c-b44b-e67700797c44', v_uni_id, 'DEV20130', 'Achieving the Sustainable Development Goals', 'Politics & Int Relations', 'DEV20130, Achieving the Sustainable Development Goals, introduces students to the United Nations Sustainable Development Goals (SDGs) and asks what it means to pursue them in practice. The module examines the origins, ambitions and limits of the SDGs, while focusing especially on their implementation in Sub-Saharan Africa. The SDGs provide a global framework for addressing some of the most urgent challenges of our time, including poverty, hunger, health, education, gender equality, economic transformation, climate action, peace, institutions and partnerships. This module helps students understand these goals not only as international commitments, but also as contested development priorities that must be interpreted, measured, financed, implemented and communicated in specific political, economic and social contexts. A central feature of the module is its focus on applying SDG analysis to country contexts in Sub-Saharan Africa. Students will examine development data, policy evidence and country case studies in order to assess progress towards selected SDGs and to understand the challenges that shape development outcomes. The module encourages students to think critically about questions such as: Who sets global development priorities? How is progress measured? Why are some goals harder to achieve than others? What trade-offs arise between social, economic and environmental objectives? How do inequalities within and between countries affect the achievement of sustainable development? The module also recognises that sustainable development work increasingly requires the ability to communicate evidence clearly to wider publics. Students will therefore work collaboratively to produce a short public-facing video on one SDG and one Sub-Saharan African country case study. This group project will help students move from academic understanding to accessible communication, reflecting the growing importance of digital engagement, social media and public visibility in the work of development organisations, researchers, policy actors and civil society. By the end of the module, students will have developed a critical understanding of the SDGs and their relevance to global development, with particular attention to Sub-Saharan Africa. They will also have practised core transferable skills, including evidence-based analysis, collaborative project work, policy communication, digital storytelling and critical reflection.', 'https://www.ucd.ie/modules/DEV20130', 'dev20130'),
    ('ae3ceaec-7194-421b-ab2f-c45b800cf699', v_uni_id, 'DIET40020', 'Nutrition & Communication', 'Public Hlth, Phys & Sports Sci', 'This module will give you a basic understanding of the theory and practice that is essential to the effective communication of nutrition and health messages. The module will initially consider the concept of health and health behaviour to provide a framework for effective communication strategies. Key components of planning, designing, and evaluating nutrition communication strategies will be explored. Contextual approaches will be examined in addition to designing and employing media channels and resources that are appropriate for the target population. This module will include informative lecture sessions from external lecturers with experience in relevant areas of communication. Staff may utilise Artificial Intelligence (AI) during the programme to support teaching and learning and it will be clearly indicated if and when AI is used. Students are prohibited from representing work as their own that they did not write, code or create. Submission of AI-generated content to this Module by a student without explicit permission and attribution is not allowed and it may reflect unacceptable professional behaviour. This may result in the initiation of a student disciplinary procedure in accordance with the University Student Code of Conduct and Academic Integrity Policy. Mapped to CORU Standards of Proficiency: 1.5, 1.8, 1.9, 1.18, 2.1, 2.2, 2.4, 2.7, 2.12, 2.14, 2.15, 3.1, 3.2, 3.3, 3.6, 3.10, 4.4, 5.1, 5.2, 5.3, 5.4, 5.5, 5.8, 5.15, 5.16, 5.17, 5.18, 5.19, .5.20, 5.21, 5.22, 5.25, 5.26', 'https://www.ucd.ie/modules/DIET40020', 'diet40020'),
    ('d93e3c59-90e0-4685-9c0e-785bb7629ef0', v_uni_id, 'DIET40030', 'Project (Human Nutrition)', 'Public Hlth, Phys & Sports Sci', 'The final year project will involve either a Research Project or a Literature Review. Students will be assigned an individualized final year project (and project supervisor) decided upon by the academic team. The decision of the academic team is final and no changes will be made. Students will be notified of their assigned project by Week 2 of Autumn. Students will be expected to meet regularly with their project supervisor (or designate) in order to ensure timely completion of all aspects of the project. All students will submit a near-complete, first draft of their final year project thesis in Week 1 of Spring. This will be corrected by the project supervisor and outline of corrections will be given to the student. Students will submit the completed final year project thesis four weeks after the first draft deadline (week 5 Spring). The specific first and final draft deadline dates will be specified each year by the Project Module Coordinator. All students will complete a presentation outlining the hypothesis, methodology, findings and conclusions of their research project. The final year project presentations usually occur within about 4 weeks of the final year project thesis deadline. Staff may utilise Artificial Intelligence (AI) during the programme to support teaching and learning and it will be clearly indicated if and when AI is used. Students are prohibited from representing work as their own that they did not write, code or create. Submission of AI-generated content to this Module by a student without explicit permission and attribution is not allowed and it may reflect unacceptable professional behaviour. This may result in the initiation of a student disciplinary procedure in accordance with the University Student Code of Conduct and Academic Integrity Policy', 'https://www.ucd.ie/modules/DIET40030', 'diet40030'),
    ('fec6aa40-dc70-47a6-908b-09dc3c84ba2a', v_uni_id, 'DIET40040', 'Molecular Nutrition', 'Public Hlth, Phys & Sports Sci', 'The Molecular Nutrition module covers the broad area of molecular nutrition, nutrigenetics and nutrigenomics. It focuses on how food / nutrition interact with the human genome with a view to understanding the molecular processes that explain diet-related diseases. The module explores this from two perspectives. Firstly, gene-nutrient interactions, wherein an individual''s genetic background modulates their sensitivity to nutrient intake. Secondly, nutrient-gene/protein/metabolome interactions, describes how nutrient intake modulates transcription, translation and metabolic process important in health and disease. Staff may utilise Artificial Intelligence (AI) during the programme to support teaching and learning and it will be clearly indicated if and when AI is used. Students are prohibited from representing work as their own that they did not write, code or create. Submission of AI-generated content to this Module by a student without explicit permission and attribution is not allowed and it may reflect unacceptable professional behaviour. This may result in the initiation of a student disciplinary procedure in accordance with the University Student Code of Conduct and Academic Integrity Policy. Mapped to CORU Standards of Proficiency: 1.18, 2.7, 3.4, 3.5, 5.1, 5.2, 5.3, 5.5, 5.6, 5.26', 'https://www.ucd.ie/modules/DIET40040', 'diet40040'),
    ('e28a304b-1b8e-43dc-99b4-21dd515eb2d9', v_uni_id, 'DSCY10050', 'War: Ancient and modern', 'History', 'Wars and armed conflicts remain a subject of great topicality. From the Middle East to Africa conflicts of different sizes and levels of intensity continue, while in Eastern Europe, the possibility of war remains a permanent threat. War has shaped much of the past and present but it has changed its character over time. This module will introduce students to the changing character of war from ancient times to the present, highlighting the latest research results on a large variety of conflicts and themes: wars, piracy and civil wars in the ancient world, the Viking conquests in Europe, the Crusades, the Wars of Religion, the Napoleonic Wars of the 19th century, the total wars of the 20th century and the current crisis in the Middle East. The module combines insights from history, classics, politics, medicine and sociology. Together, faculty from these diverse disciplines will introduce some of the latest research on the topic, including aspects of violence and gender, medical responses to the outbreaks of war and the new wars on terror in today s Middle East.', 'https://www.ucd.ie/modules/DSCY10050', 'dscy10050'),
    ('89088391-9c98-4e7a-aa60-858e2323930a', v_uni_id, 'DSCY10200', 'Evolution of Food &Agriculture', 'Agriculture & Food Science', 'How did a 10,000-year-old agricultural revolution shape the very DNA, diet, and diseases that define us today? This interdisciplinary Discovery module brings together cutting-edge genetics and archaeology to unravel one of humanity''s most profound transformations. You will explore how the shift to farming fundamentally altered human evolution, nutrition, and health—from our ability to digest milk to the evolution of zoonotic diseases like plague and Salmonella. Through fascinating case studies of domesticated animals (dogs, cattle, sheep, pigs) and crops (maize), you will discover how agriculture catalyzed technological development and reorganized human societies across the globe. Contributors from different disciplines will guide you through the evidence of changing dietary practices worldwide and examine how innovations like wool production transformed economies. You will also investigate how genomic techniques are now being applied to ecosystem recovery, re-wilding, and even de-extinction efforts—connecting knowledge of the deep past to future environmental solutions. Through interactive in-person lectures, recorded content, discussions, and peer learning, you will gain unique insights into how ancient DNA research is revolutionizing our understanding of humanity''s relationship with food, animals, and the environment. In-person lectures are timetabled as 1-2pm Wednesdays, and 11am-1pm Friday.', 'https://www.ucd.ie/modules/DSCY10200', 'dscy10200'),
    ('0e4e7411-a04a-4458-919e-b599fd3d3f54', v_uni_id, 'ECON10010', 'Principles of Microeconomics', 'Economics', 'This module is intended for those who have already taken ECON10770 (Introduction to Economics). It expands upon the basic concepts of microeconomics covered in ECON10770 and seeks to introduce more detailed economic models of consumer and producer choice and place them in the context of empirical data about our world. ECON 10010 uses the CORE (Curriculum Open-access Resources in Economics) curriculum. CORE is a new approach to teaching economics that places greater emphasis on issues of equality, distribution, environmental sustainability and social justice. CORE also places a heavy emphasis of placing teaching within a firm context of evidence from data to support economic theory. The teaching material for ECON 10010 draws heavily on what can be found on the website for CORE, specifically the CORE 2.0 online textbook (https://www.core-econ.org/the-economy/microeconomics/0-3-contents.html). The approach of CORE may be somewhat different from more traditional teaching approaches within economics. Students that have taken leaving certificate economics may not find the approach that familiar. This module is a prerequisite for all students wishing to take economics at level 2 (second year). This includes: (a) economics as a single subject major (b) economics as one of two subjects in a joint major programme (c) economics as a major in a major/minor combination.', 'https://www.ucd.ie/modules/ECON10010', 'econ10010'),
    ('5c8eb90e-5dcd-4a67-b2d4-84d77757e9dc', v_uni_id, 'ECON10020', 'Principles of Macroeconomics', 'Economics', 'This module will introduce students to some basic principles that economists use to understand the macroeconomy. In doing so we will address questions such as how economists measure aspects of the economy like GDP and inflation, as well as how they understand recessions and the role of government policy in managing the macroeconomy. Using the CORE The Economy curriculum, this module will employ economic theory, empirical evidence and informed debate to understand the nature of these questions and how we can begin to answer them.', 'https://www.ucd.ie/modules/ECON10020', 'econ10020'),
    ('eb50788c-7c2c-4a1b-9fb3-a4ba515a796b', v_uni_id, 'ECON10030', 'Introduction to Quantitative Economics', 'Economics', 'This module introduces students to mathematical methods used in solving economic problems. Quantitative techniques are developed through application to core economic concepts, providing an important foundation for Stage 2 and Stage 3 economics modules. The module is designed around a structured, technology-enhanced blended-learning model that gives students repeated opportunities to learn, practise, consolidate and check their understanding each week.', 'https://www.ucd.ie/modules/ECON10030', 'econ10030'),
    ('32172778-55c0-451d-9fd9-4276134fb3af', v_uni_id, 'ECON10040', 'Economics and Sustainability', 'Economics', 'This module is about learning to apply economics to understand the world around us and in particular the main barriers and enablers towards sustainability. The focus is on providing an introduction to the discipline of economics that is practical, intuition-based, and relevant to understand the sustainability challenges of our time. The course requires no previous knowledge of economics and it caters also to those who may never take another course in economics. We will discuss environmental and social dimensions of sustainability and how to measure how “wealthy” we are. We will ask why the actions of people, firms, and countries are not always aligned with societal and sustainability objectives. We will see how economists construct simplified “models” of decision-making based on the benefits and costs of available options (trade-offs) and we will apply these models to understand a variety of contexts: Why did firm in 1800 England (industrial revolution) adopt labour-saving but energy-intensive and fossil-fuel reliant technologies? Can we predict likely consequences of different policies to address the housing crisis before they are put in place? How does a country chooses which products and sectors to specialize on? Why is the environment subject to so much “free-riding” and “tragedy of the commons”? How can policies but also social norms help achieve sustainability? To do this, we will look at the economic principles behind market interactions (what we choose to buy and what firms choose to produce and sell) and assess in what circumstances unregulated markets are likely to fail to achieve social welfare and sustainability. Understanding how people, firms, and countries respond to the "incentives" they face will help us design policies and change the incentives to achieve more socially and environmentally sustainable outcomes. At the end of the course we will have a better understanding of the barriers to achieve more sustainable economic systems and what we can do about it!', 'https://www.ucd.ie/modules/ECON10040', 'econ10040'),
    ('3021c35e-8d16-4397-8f96-a9af9b863ed7', v_uni_id, 'ECON10720', 'Microeconomics for Business', 'Economics', 'The aim of this module is to introduce students to core microeconomic principles and how they can be used to help understand decision making and behaviour in a business environment. The module focuses on markets as the principle arena where these decisions are made and stresses that both firms and consumers make choices under conditions of scarcity and do not have unlimited resources. A model of consumer demand is presented showing how consumers respond to changes in prices, incomes and other factors. On the supply side, a model of the production decisions of firms is presented and the roles of costs and technology are explored. Market structure is also explicitly considered ranging from perfect competition to monopoly. Strategic interaction between firms and individuals is explicitly analysed and account is also taken of altruism and fair play. The module also examines inequality in modern societies. Finally, it is stressed throughout the module that markets often fail and in those cases some form of intervention, typically but not exclusively provided by government, to correct these failures is warranted. Examples from the area of climate change are presented and recent developments in international tariff policy are also explored. The module assumes no previous knowledge of economics.', 'https://www.ucd.ie/modules/ECON10720', 'econ10720'),
    ('1f4e01db-6b87-480f-a4c6-321fc9b1d8c1', v_uni_id, 'ECON10730', 'Data Analysis for Economists', 'Economics', 'Distinction/Pass/Fail (GPA Neutral) In today’s world, data are everywhere. Businesses and governments have access to more data on their customers and citizens than ever before and there is high demand for people with the skills to analyse this information in a systematic manner. This module will introduce students to the basic tools used by economists when analysing data. Various types of data are introduced and students will learn how to use spreadsheets to do basic calculations, analyse economic policy issues, make graphs and calculate statistics. Issues relating to interpreting statistics and distinguishing causation from correlation will also be explored.', 'https://www.ucd.ie/modules/ECON10730', 'econ10730'),
    ('833cf5ca-4dac-4947-8b18-74626cb31808', v_uni_id, 'ECON10740', 'Exploring Economics', 'Economics', 'Pass/Fail (GPA Neutral) This module introduces students to the practical side of economics: how economists find, use, and communicate information in real-world contexts. Through weekly activities, guest speakers, and a group project, students will explore how economics is applied in the real world – across sectors such as policymaking, regulation, consultancy, central banking, international organisations, and research. The module also supports the development of essential academic and professional skills including information literacy, collaboration, presentation, and reflective writing. In addition, it encourages early career exploration by helping students understand the range of career paths open to economists, and begin developing practical skills such as CV writing and professional communication. Attendance and active participation are expected, particularly for workshops and presentations.', 'https://www.ucd.ie/modules/ECON10740', 'econ10740'),
    ('2bf55b11-ff3e-4750-bda4-b363eb13617d', v_uni_id, 'ECON10760', 'Macroeconomics for Business', 'Economics', 'Macroeconomics is “big picture”economics. It looks at the economy as a whole and examines how it is performing. In this module, we introduce students to measuring the key macroeconomic variables such as GDP, inflation and unemployment. We explore what determines whether economies experience booms and recessions and the factors that influence unemployment and inflation. We also examine how the government should influence the economy via fiscal policy (decisions about public spending and taxation) and monetary policy (decisions about money creation and interest rates made by a central bank). We also look at longer term trends in living standards and the factors that drive these trends. No assumption is made that students have previously studied economics.', 'https://www.ucd.ie/modules/ECON10760', 'econ10760'),
    ('95f46875-e940-452d-9b64-4002226f64a7', v_uni_id, 'ECON10770', 'Introduction to Economics', 'Economics', 'This module will introduce students to the subject of economics. Students will be introduced to microeconomics. We will discuss the factors that determine supply and demand in markets and how these determine the prices of the goods and services we buy as well as how much is purchased. We will discuss strengths and weaknesses of free markets and the rationales for government intervention in the economy. Students will also learn the basic concepts of macroeconomics: How to measure gross domestic product, inflation and unemployment as well as the role played by government fiscal and monetary policy. A number of topical economic issues will be discussed in the course such as inequality, international trade and financial crises. The use of AI for any purpose is not allowed in this module. This module may be taken as part of a Structured Elective in Economics. This means that if you combine this module with at least 10 additional credits from other economics modules you will be awarded a ‘structured elective in economics’ on your transcript.', 'https://www.ucd.ie/modules/ECON10770', 'econ10770'),
    ('f86e6632-f1da-47a7-91e3-a5a35c9b7dcc', v_uni_id, 'ECON10790', 'Mathematics for Economists', 'Economics', 'This module introduces students to mathematical methods used in solving economic problems. It will cover: algebra, linear and quadratic equations, optimization techniques. These quantitative techniques will be illustrated by application to basic economic concepts.', 'https://www.ucd.ie/modules/ECON10790', 'econ10790'),
    ('7d528587-fee7-4301-89f3-cc6b4ea85b65', v_uni_id, 'ECON20010', 'Intermediate Microeconomics I', 'Economics', 'This is the first module in a two semester intermediate microeconomics sequence. Intermediate Microeconomics II completes the sequence. Relative to first-year modules in microeconomics, this module provides a more formal approach. All concepts will be discussed intuitively, graphically, and mathematically. The module will focus on supply and demand, consumer theory, applications of consumer theory; it will also explore topics on uncertainty, asymmetric information, contracts and moral hazard. The required textbook for this module is Microeconomics by Jeffrey Perloff. This module is a core requirement for all students taking economics as a major or minor subject in Stage 2. This includes (a) economics as a single subject major (b) economics as major in a joint major programme (c) economics in a major/minor combination, and (d) the sustainability degree.', 'https://www.ucd.ie/modules/ECON20010', 'econ20010'),
    ('c4f4c5c5-e10c-423e-812c-72a0341eb455', v_uni_id, 'ECON20020', 'Intermediate Macroeconomics', 'Economics', 'The focus of this module is on developing foundational models that provide insights into macroeconomic issues and stabilisation policies within a domestic and international context. The famous IS-LM model is introduced and used to analyse monetary and fiscal policies, with a particular focus on the small open economy. The course builds on the Principles of Macroeconomics module (ECON 10020).', 'https://www.ucd.ie/modules/ECON20020', 'econ20020'),
    ('58ba5e86-f062-42fd-918f-3e41aaa85ae2', v_uni_id, 'ECON20040', 'Statistics for Economists', 'Economics', 'This module introduces the main techniques of statistics as used in economics. Students will be introduced to numerical and graphical techniques for representing data. The course outlines the use of simple linear regression, the basic tool of empirical economics. Following a revision of basic probability theory, the use of probability distributions of random variables will be covered. The final part of the course covers the theory of estimation, statistical inference and hypothesis testing. There will be regular exercise sheets for self-assessment.', 'https://www.ucd.ie/modules/ECON20040', 'econ20040'),
    ('9ce86ec6-297a-4771-b486-4c6e30bb2a02', v_uni_id, 'ECON20060', 'Irish Economy: Policy Making in a Global Context', 'Economics', 'This module examines how Ireland’s economy has evolved since independence, and how policy makers respond to ongoing challenges in a small, open economy. In recent decades, Ireland’s economy has moved from the Celtic Tiger boom through recession and recovery, followed by the challenges arising from Brexit, a global pandemic, geopolitical conflicts, the need for sustainable development, and changes in international trade and US policy. Ireland’s economic performance is shaped by government policy within the context of domestic and international developments. Looking at the evolution of the Irish Economy, from Independence to the present day, provides an important backdrop for our analysis of contemporary issues. Using a framework for policy analysis, we consider the rationale for intervention, the policy instruments available, whether policies achieve their objectives, possible unintended consequences, and the implications for efficiency, equity and sustainability. The Care Economy is examined as an important topic in its own right, but it also provides a useful link across many wider policy issues. We then apply the framework to Ireland’s manufacturing and internationally traded services sectors, education, and inequality and poverty. A distinctive feature of the module is the integration of the UN Sustainable Development Goals (SDGs) across teaching, learning and assessment. Recommended textbook: O''Hagan, John , Francis O’Toole and Ciara Whelan (eds): The Economy of Ireland: Policy Making in a Global Context (15th edition), 2025, Bloomsbury', 'https://www.ucd.ie/modules/ECON20060', 'econ20060'),
    ('7e74fcb6-d8f7-464f-a0a8-62a7c0df50c6', v_uni_id, 'ECON20080', 'Economic Policy Analysis', 'Economics', 'This is a course that uses economic theory and empirical evidence to analyse current policy issues such as the economic impact of the minimum wage, the potential impact of legislation on collective bargaining, taxation and arguments for a Universal basic income.', 'https://www.ucd.ie/modules/ECON20080', 'econ20080'),
    ('c143ffc3-ee48-47a1-9e49-5552a4f784f1', v_uni_id, 'ECON20100', 'Game Theory', 'Economics', 'Game theory is a formal way of thinking about and analysing strategic situations. This module will provide the tools that will enable you to use game theory to analyse a range of different problems. Through the analysis of many examples in a variety of contexts you will 1. learn how to take into account strategic interactions when making your own choices; 1. learn how to predict other people or organizations'' behaviour when they are in strategic settings; 3. learn how to apply these tools to settings from economics and other disciplines. This module may be taken as part of a Structured Elective in Economics. This means that if you combine this module with at least 10 additional credits from other economics modules you will be awarded a ‘structured elective in economics’ on your transcript. See https://www.ucd.ie/students/registration/structuredelectives/ for details.', 'https://www.ucd.ie/modules/ECON20100', 'econ20100'),
    ('4ee41329-a480-4fe5-9d7a-12d15fd2fb05', v_uni_id, 'ECON20120', 'The Economics of the European Union: Institutions, Policies and Crises', 'Economics', 'The course covers the integration of European countries through the lens of economic theory and policy. We use microeconomic and macroeconomic tools to examine the motivation for and development of core EU policies. First we examine the origins of economic and later European integration., through to the Single Market. We cover core policies such as trade, agriculture, and competition with microeconomic tools, examining economic efficiency. Then we discuss fiscal and monetary policies of the EU, including the common currency. Two crises that highlight the triumphs and pitfalls of European integration are studied in-depth: Brexit and the Financial Crisis. Using the economic policy analysis tools developed in class, students pursue research, independently and with classmates, on other EU policies such as the environment and social protection.', 'https://www.ucd.ie/modules/ECON20120', 'econ20120'),
    ('5e605f01-e993-473b-897f-2100ea325dfa', v_uni_id, 'ECON20130', 'Economic History: From the Middle Ages to the Second World War', 'Economics', 'This course draws on economic reasoning to examine the transformation of European economies from a predominantly agrarian base to a much more diversified economic structure. This transformation culminating in what is often called the Industrial Revolution marks one of history''s great changes. This course aims to provide both historical perspective on Europe and on Ireland and experience in the application of economic analysis to major issues. The topics of the course divide into three chronological and logical sections. The first examines the preconditions of European economic development, paying particular attention to the demographic, technological and institutional changes that supported growth. The second section focuses on the Industrial Revolution in England asking what exactly it was, how it can be measured, and who benefited? The third examines the shift to modern economic growth in other European economies, including (eventually) Ireland. This course also enables us to explore the question ''why are some so rich and some so poor?'' and provides a basis for your understanding of both the Irish economic growth and that occurring in other parts of the world.', 'https://www.ucd.ie/modules/ECON20130', 'econ20130'),
    ('ddaf92e3-8833-4d20-9600-356cc87a736b', v_uni_id, 'ECON20160', 'Economics of the Environment', 'Economics', 'This module is an introduction to environmental economics, discussing how to use economic principles to understand environmental problems, design appropriate incentives for change, and evaluate policy responses. Students will acquire the tools to participate in discussions of environmental issues and policy through an economic lens. This will be done using economic models, policy discussions and case studies with applications to key environmental challenges such as climate change, pollution regulation, and environmental and water conservation. We will discuss sources and taxonomies of environmental problems, how economic principles can be used to understand environmental issues, how to design and evaluate policy instruments to resolve environmental issues (especially related to pollution and greenhouse gas emissions), how to conduct a socio-environmental cost-benefit analysis, and motivations for but also criticisms against ecosystem valuation. Key concepts covered include market failure, externalities, public goods, property rights, cost-benefit analysis, pros & cons of ecosystem valuation, command-and-control policies, and market-based policies in the form of taxes/subsidies and cap-and-trade/tradeable allowance systems. The application of these tools to present-day local and global environmental challenges, such as local pollution, climate change, water and nature conservation, will be discussed in lectures and in small-group tutorials.', 'https://www.ucd.ie/modules/ECON20160', 'econ20160'),
    ('84f9f6f6-1d46-46c7-9afd-fc2e74615529', v_uni_id, 'ECON20180', 'Intermediate Microeconomics II', 'Economics', 'This is the second module in a two-semester study of intermediate microeconomics. It focuses on production and covers the following topics: -Firms and Production -Costs -Competitive Firms and Markets -Applying the Competitive Model -General Equilibrium and Economic Welfare -Monopoly -Pricing and Advertising -Oligopoly and Monopolistic Competition', 'https://www.ucd.ie/modules/ECON20180', 'econ20180'),
    ('085f4a2a-475e-419c-8446-7a75856d81d2', v_uni_id, 'ECON20190', 'Introduction to Financial Economics', 'Economics', 'This module introduces students to the basic concepts of financial economics. Topics covered will include (1) How to value assets that generate a sequence of cash flows over time for their owners. (2) Guidelines for capital budgeting decisions by firms (3) How firms raise money from equity markets and bond markets. (4) The trade-off between risk and return in financial assets (5) Basic principles for investing wealth in a portfolio (6) The theory and practice of corporate financial structure This module may be taken as part of a Structured Elective in Economics. This means that if you combine this module with at least 10 additional credits from other economics modules you will be awarded a ‘structured elective in economics’ on your transcript.', 'https://www.ucd.ie/modules/ECON20190', 'econ20190'),
    ('67e0b070-18d1-4233-bd60-6143831928d9', v_uni_id, 'ECON20230', 'Economics, Organisation and Management', 'Economics', 'This module deals with firms and organization and intends to analyze them in their complexity. It relies on rigorous economic theory to derive the principles that are at work. Students will get a better understanding of key economics concepts and variables that play an essential role in securing an efficient production and exchange.', 'https://www.ucd.ie/modules/ECON20230', 'econ20230'),
    ('276f6dd0-eff1-4e79-9e84-5270d6e4dc31', v_uni_id, 'EDUC10170', 'Human Learning', 'Education', 'Human Learning is a module that focuses on developing core competencies for effective learning, wellbeing, personal growth and coping with stress, so that you can equip yourself with lifelong skills for learning, working and being well. You will spend 11 weeks developing yourself to thrive in university life and beyond - including leadership skills for future employment. Some concepts covered in this module are managing stress, motivation, time management, critical and creative thinking, happiness, personality, positive self-identity, and most importantly fostering physical, cognitive, emotional and social skills that will support your learning and wellbeing. Your assignments will provide you with the opportunity to focus on yourself, working towards your personal goals that you will identify as part of the module and track your own personal data and progress in areas of your choice (e.g. emotional wellbeing, study habits, time management, exercise). You will reflect on how your values and goals map onto the way you are currently living your life and you will be facilitated in exploring how you wish to reach your potential. Expert speakers will join us for sessions around areas such as personality, time management, and mental health. Human learning is taught using pre-recorded online lectures, and in-person interactive practical, providing you with the perfect mixture of learning. Each week you will prepare for class by engaging with online materials by watching pre-recorded lectures and readings. You will also attend weekly small group practical classes which will be conversational in tone where you will undertake a variety of activities both individually and in small groups that focus on enhancing your personal development, self-enquiry and reflection and build your learner competencies. Some examples of activities include simulation games, quizzes, debates, and problem solving. We look forward to meeting you!', 'https://www.ucd.ie/modules/EDUC10170', 'educ10170'),
    ('f3cca0a1-ede2-42d4-a006-e1c23fad42eb', v_uni_id, 'EDUC10280', 'Why Trust Science?', 'Education', 'Are you curious about how science works and its place in our world? Would you like to learn about conspiracy theories, ‘alt facts’, and about how scandals and controversies have affected our trust in science? If so, this module is for you. This module is open to all students in UCD. It offers an interdisciplinary space where students from across campus can come together to think and learn about the role of science in our society. Using lively classes, debate, and forms of assessment that aid your learning, we’ll explore the complex relationships between science, expertise, policy and trust. We’ll question whether science is more trustworthy than other forms of knowledge and consider how we might build a climate of trust in diverse expertise to tackle the big issues facing our world – things like climate change, biodiversity loss, equity in health care, pandemics, AI, mental health, etc. No previous knowledge of science is required. This module is designed to be accessible to students from across UCD.', 'https://www.ucd.ie/modules/EDUC10280', 'educ10280'),
    ('3d388326-0dce-4a8d-8125-42beebb48bb0', v_uni_id, 'ENG10020', 'Children''s Literature', 'English, Drama & Film', 'This module will explore a range of children’s literature by an eclectic set of writers from different cultural and historical contexts, surveying the nineteenth and twentieth centuries, representing what we have come to understand as a ''golden age''. Through a series of lectures, students will read a variety of different texts, and by the end of the course, through close reading and analysis, will be able to demonstrate a knowledge of major children’s authors, identify different categories of children’s literature, and illustrate an understanding of how these works reflect key social, political and cultural issues, with a particular focus on less-obvious aspects of the texts, and some of their radical underpinnings.', 'https://www.ucd.ie/modules/ENG10020', 'eng10020'),
    ('b983c0fd-fca4-4279-9601-bbe638cc2ffa', v_uni_id, 'ENG20780', 'Critical Theory', 'English, Drama & Film', 'This 10-credit module introduces students to key theoretical debates and issues in the Humanities, particularly pertaining to the study of language and literature. It demands careful reading of theoretical texts and close attention to a series of difficult concepts, but in return this module repays students’ efforts by providing an indispensable grounding in the foundational vocabularies and conceptual tools of the most exciting and progressive areas of critical and cultural studies. The module will have a special emphasis on applying the insights of critical theory to the analysis of contemporary political and ethical issues, as well as to literary and cultural texts.', 'https://www.ucd.ie/modules/ENG20780', 'eng20780'),
    ('01787569-22cb-499e-8df7-8955bff69435', v_uni_id, 'ENG32560', 'Writing Black: African American Literature and Racial Consciousness', 'English, Drama & Film', 'This module explores the historical development of racial consciousness in African American writing from the nineteenth century to the present. With the legacies of transatlantic slavery and W.E.B. Du Bois’s classic notion of “double consciousness” as central through-lines, the module addresses texts from across a range of genres: fiction, autobiography, drama, poetry, film, and theory. We will explore how consciousness of race and racialization has been articulated by Black writers in a variety of historical contexts, from slave narratives through the New Negro Renaissance and Civil Rights era to the contemporary moment of Black Lives Matter. We will also examine how race has intersected for African American writers with other concerns, including class, gender, sexuality, economy, and political activism. The title of the module is intended to signify in multiple ways: as a suggestion that blackness can be as much a question of writing as of being; as a gesture towards the figure of black type on a white page, found in the work of many African American writers; and as an allusion to “writing back,” a mobilizing phrase for many anti-colonial literary movements. Attending to these varying resonances, the module offers students an opportunity to explore how African American writers have grappled with and shaped American racial consciousness, in the political sphere and on the page.', 'https://www.ucd.ie/modules/ENG32560', 'eng32560'),
    ('1492a31f-c395-4667-86c2-d614eb72444d', v_uni_id, 'ENVP10010', 'Environment Change & Policy', 'Architecture, Plan & Env Pol', 'The aim of this module is to introduce students to processes of environmental change and to explore how policy-makers have responded to these challenges. The module has three primary components: firstly, it will examine key environmental challenges facing society at a range of spatial scales. This will introduce you to a range of issues, from global environmental issues such as climate change and biodiversity loss, to more local concerns such as environmental quality, land use change and various forms of pollution. Secondly, the module will consider the relationship between environment and society. This will include an exploration of the changing ways society has viewed or valued the environment and will also chart the emergence of environmentalism as a political force. Thirdly, the module will outline the policy response to environmental change. This component of the module will introduce students to the broad concept of sustainable development and will also provide an overview of various forms of policy instruments to address environmental challenges.', 'https://www.ucd.ie/modules/ENVP10010', 'envp10010'),
    ('32b0e421-d4a4-4f65-87cd-f869878f784f', v_uni_id, 'FDSC10010', 'Food Diet and Health', 'Agriculture & Food Science', 'This module will introduce students to the principles and understanding of Healthy Eating Guidelines and Food Science, with a particular emphasis on the composition and manufacture of key food and beverage commodities, Food Safety (including microbial and non-microbial contamination of foods), and Nutrition-related issues (such as food choice and obesity). This module will be delivered entirely online. Online video lectures, accompanied by notes, will be released weekly. Students are requested to watch and read the lecture material independently and then submit questions or queries each week for a scheduled online live classroom, where questions and issues raised will be addressed.', 'https://www.ucd.ie/modules/FDSC10010', 'fdsc10010'),
    ('7492d7e3-2fe9-4401-8a75-25ea29423ea5', v_uni_id, 'FDSC20010', 'Food Macronutrients', 'Agriculture & Food Science', 'After a brief review of key concepts in chemistry, with a view to highlight the importance of water in all biochemical processes, this module is intended to equip students with an introduction to the key biologically important food macronutrients, namely, carbohydrates, lipids and proteins. The main aim of the module is to focus on the occurrence, chemical structures, physical and chemical properties of important members of each group in order to illustrate why cell structure and metabolism in plants and animals is dependent on these substances. This module underpins Agricultural Biochemistry (FDSC20100) which deals with the nature of the metabolic processes taking place in living cells.', 'https://www.ucd.ie/modules/FDSC20010', 'fdsc20010'),
    ('8a6137b0-292a-4dd0-a63d-41798d600956', v_uni_id, 'FDSC20020', 'Nutritional Energy Metabolism', 'Agriculture & Food Science', 'The main aim of this module is to introduce students to how living cells (animal and plant) can extract energy from highly reduced organic molecules (i.e. carbohydrates, fats, proteins) and convert them to a usable form of energy suitable to the functions of the living cell. Selected metabolic pathways will be covered, as will the regulation mechanisms and interactions of the metabolic pathways operative in the cell. This module will contribute to the development of the following COMPETENCIES that are CORE to your development as a professional in Food Science: Understanding the role of enzymes in energy metabolism and toxicology Understanding the structure and properties of food components, including water, carbohydrates, protein, lipids, other nutrients and food additives Knowledge of the chemistry of changes occurring during processing, storage and utilization Knowledge of the principles, methods, and techniques of qualitative and quantitative physical, chemical, and biological analyses of food and food ingredients.', 'https://www.ucd.ie/modules/FDSC20020', 'fdsc20020'),
    ('735cff3f-19ba-4a00-b276-c04ed2b9a1ca', v_uni_id, 'FDSC20030', 'Food Analysis', 'Agriculture & Food Science', 'The aim of this module is to provide students with the knowledge and practical laboratory skills required to conduct basic, quantitative chemical analysis, including food analysis. The module provides an understanding of 1) the principles of stochiometry and solution chemistry that underpin calculations in quantitative chemical analysis; 2) the principles of volumetric and gravimetric analysis; 3) the basic theory of acid /base chemistry. A comprehensive introduction to the application of the principles of quantitative chemical analysis to foods is also given. Subject to availability under public health guidelines weekly laboratory sessions are designed to directly relate to the lecture material being covered at that time and to develop the following : group work; practical laboratory skills; critical analysis of problems, report writing and information technology skills. This module will contribute to the development of your understanding of the following areas that are considered core to your development as a professional in Food Science. Food chemistry and analysis: Structure and properties of food components, including water, carbohydrates, protein, lipids, other nutrients and food additives; Principles, methods, and techniques of qualitative and quantitative chemical analysis of food and food ingredients. Success skills: Report writing skills; Critical thinking/problem solving skills; Professionalism skills; Life-long learning skills; Interaction/teamwork skills; Information acquisition skills; Time management skills. Food processing and engineering: Characteristics of raw food material; Principles of food preservation; Principles of food engineering – introduction to mass balances. Applied food science: Integration and application of food science principles to real life situations; Computer skills.', 'https://www.ucd.ie/modules/FDSC20030', 'fdsc20030'),
    ('ad5cadf7-6a48-40b5-8388-8006b61581eb', v_uni_id, 'FDSC20110', 'Food Diet and Health II - Making Healthy Food Choices', 'Agriculture & Food Science', 'Ever wondered what''s in your food and is it good for you? This module introduces students to the health attributes of the main food groups Cereal Products, Fruit and Vegetables, Dairy products, Meat/Fish/Eggs. Students will learn how production and manufacturing processes influence the health attributes of foods. Throughout the course you will learn about where foods come from (e.g. organic versus inorganic), how foods are made, the nutritional quality of food and potential health benefits/risks. Students will also learn about the role of additives in foods and food regulation and how to produce effective posters. The goal of the module is to help students make informed food choices based on scientific evidence that can help to maintain health. NOTE: This module can be taken before or after FDSC10010 Food Diet and Health 1, and Food Diet and Health 3 Stage 4 Food Science students may not access this module as an elective. This module will contribute to the development of the following COMPETENCIES that are CORE to your development as a professional in Food Science: -FOOD SAFETY and MICROBIOLOGY: This module will allow students to explore the use of beneficial microorganisms in fermented food systems, and determine the influence of the food system characteristics and processing parameters on the growth survival, and control of microorganisms. -FOOD PROCESSING and ENGINEERING: The group project in this module requires the student to research and understand the variability inherent in raw materials and how they impact the production and quality of fermented foods. Students should be aware of the principles that make food products safe to consume and will explore some processing techniques and the effect of processing parameters on the fermented product quality. - SUCCESS SKILLS This module will take a multimedia approach to develop students'' research and communication skills. Students will demonstrate Research skills by sourcing 8 relevant peer-reviewed research articles on a selected topic from which they will extract the key points of each paper in a research portfolio. They will communicate this technical information to an expert audience using e-posters. Assessment will be 100% continuous Assessment. 1. There will be 3 MCQ exams. MCQ 1: 5 % ONLINE / REMOTE: Delivered in week 4 ( 5%) to ensure engagement with learning materials MCQ 2: 5 % ONLINE / REMOTE: Delivered in week 8 ( 5%) to ensure engagement with learning materials MCQ 3: 50% IN PERSON ON CAMPUS Delivered in WEEK 12 at 13.00 - see schedule for venue. Attendance on this date is MANDATORY unless you have valid extenuating circumstances. MCQ 3A- 50% IN PERSON ON CAMPUS Delivered on Monday WEEK 13 at 13.00 - see schedule for venue. This offering is only for students with clashing core modules who cannot make the Week 12 offering. 2. There will also be a research project worth 40%. This can be completed as a group or as an individual. If working as a group, you will need to join a group by the end of Week 3. Students who have not joined a group by then will complete the project as an individual. 2A. Each student will produce A RESEARCH PORTFOLIO which will be updated each week. In this Portfolio, students will research and summarise 8 recent papers relevant to their topic. They will then write a short essay using these resources as the final entry, using the Scientific Writing Rubric provided. This is worth 20%. 2B. Each student/ group will produce a poster, using the rubric provided, communicating their project findings to PhD students. this is worth 20%. 2C. GROUPS ONLY: Each student must provide a peer assessment, breaking down the contribution of each person in the group. This is to ensure fair distribution of the group grade. This has no assigned grade but is required to complete your submission. Dates and grade breakdown can be found in the Module ''MY LEARNING'' section of the module page.', 'https://www.ucd.ie/modules/FDSC20110', 'fdsc20110'),
    ('96627f11-8a2d-4834-a114-7aacc7199e20', v_uni_id, 'FDSC20240', 'Professional Skills Developmen', 'Agriculture & Food Science', 'Pass/Fail (GPA Neutral) This module is designed for undergraduates in the School of Agriculture and Food Science before they go on Professional Work Experience (PWE). The face to face lectures and online materials will give the student the foundation for understanding the skills they already have and those they wish to develop before and during their professional placement to maximise the benefits of the experience and to think about preparing for their future preferred career.', 'https://www.ucd.ie/modules/FDSC20240', 'fdsc20240'),
    ('8823b710-d1e9-474d-802c-82983662ccab', v_uni_id, 'FDSC30040', 'Food Chemistry I', 'Agriculture & Food Science', 'This module focuses on food proteins, carbohydrates and lipids with emphasis on relationships between their structure and functional properties. The module emphasises how food processing operations and storage alter the functionality of these food components. The role of water in foods and its influence on food stability is also examined.', 'https://www.ucd.ie/modules/FDSC30040', 'fdsc30040'),
    ('3633544a-ca8f-40aa-a8cb-670cdef2395b', v_uni_id, 'FIN20010', 'Principles of Finance', 'Business', 'This subject is an introduction to modern finance. As domestic and international companies became more sophisticated, it was realised that every executive required an understanding of corporate finance. Topics covered include corporate governance, agency theory, financial analysis and planning, asset valuation, capital investment decisions, the concept of risk and return, and introduction to portfolio theory.', 'https://www.ucd.ie/modules/FIN20010', 'fin20010'),
    ('01c5df94-f5b1-4afd-ac18-ee16801e122f', v_uni_id, 'FIN30030', 'International Financial Management', 'Business', 'As the international company becomes the norm rather than the exception, the need to internationalize the tools of financial analysis is apparent. We live in a highly integrated world economy, and it is critical that businesses understand both the risks and opportunities that globalization brings. This module is about multinational management, and more specifically, the financial management dimensions of leading a multinational corporation (MNC). Financial managers must be able to assess the international environment, recognize opportunities, implement strategies, assess exposure to risk, and manage that risk. In this module we examine exchange rate systems and their determination, international sources of finance for firms, and discuss the best approaches to managing exchange rate risk. Consequently, derivatives and hedging techniques are examined and, inter alia, we study international flow of funds, multinational capital budgeting and multinational capital structure.', 'https://www.ucd.ie/modules/FIN30030', 'fin30030'),
    ('6f2e9ecd-640b-4e0f-ae64-0349c74c5533', v_uni_id, 'FIN30080', 'Financial Institution Management', 'Business', 'This module is primarily about banking and the wide variety of activities undertaken by banks. It is intended to be topical so being aware of current events will be useful. As a student of the Quinn School you can avail of a subscription to the FT. Financial institutions lie at the heart of any economic system, providing a safe place for people and firms to save, to borrow and to transfer money to others. There is a focus on making banks safer after the events of 2007/08. The challenges have been further complicated by the recent Covid-19 pandemic and in this country; Brexit. The module covers: • Asset and liability management, • Types of banking (Retail, Corporate & Investment), • Fintech, • International banking, international financial markets, • Central banking (Regulation, Monetary Policy, Financial Crises) The module will look at banking from economic, regulatory and practitioner perspectives. It will also touch on Insurance and Assurance activities. In other words, this is a high level look at banking (in its broadest context) and you are expected to do some research, analysis and communicating. I hope you enjoy it.', 'https://www.ucd.ie/modules/FIN30080', 'fin30080'),
    ('69ded83d-8894-471a-984c-e7f92d8fafaf', v_uni_id, 'FIN30090', 'Treasury and Risk Management', 'Business', 'This course deals with the ways in which risks are quantified and managed by financial institutions. Among the topics covered are the core fundamentals of derivative securities and the important role that they play in financial markets. Our primary focus will be to provide a very good understanding of the practical applications of risk management in financial markets using real world examples.', 'https://www.ucd.ie/modules/FIN30090', 'fin30090'),
    ('41ec70fe-8feb-4762-af7b-1112392204ef', v_uni_id, 'FIN30100', 'Investment and Portfolio Management', 'Business', 'This course focuses on the theoretical and empirical underpinning of modern portfolio theory and investment analysis. We begin with an overview of financial markets and the available asset classes. The course shall then outline the main theories of risk and return and explore the implications of these theories for investors’ decisions. To address the question of how investors might decide on the weightings of different assets in their portfolios, the course will examine portfolio theory and diversification. We also investigate the efficient market hypothesis and delve into the different types of investment companies. Finally, we examine the valuation of equity, bond and derivative instruments.', 'https://www.ucd.ie/modules/FIN30100', 'fin30100'),
    ('57cb3aa6-05f2-4ba8-9df4-f6444e4f9b82', v_uni_id, 'FIN30170', 'Corporate Financial Management', 'Business', 'In this subject we build on the corporate finance content of 20010 Principles of Finance (or a similar introductory finance course). We cover the theory, practice and evidence on corporate investment and financing decisions: capital budgeting, capital structure, cost of capital, raising finance, dividend policy, agency issues, corporate control and governance.', 'https://www.ucd.ie/modules/FIN30170', 'fin30170'),
    ('6bd96f81-29c1-4d05-94e5-8eab0ecb65fc', v_uni_id, 'FIN30190', 'Behavioural Finance', 'Business', 'Behavioural Finance applies the theoretical and experimental methodologies and results of the cognitive sciences to questions concerning the ways in which individuals actually make financial decisions, in contrast to the traditional idealised economic models of choice behaviour. It also considers the impact of various individual behavioural biases, feelings, and social forces on aggregate market behaviour, addressing issues such as market efficiency and financial crises.', 'https://www.ucd.ie/modules/FIN30190', 'fin30190'),
    ('3fa8110f-f2c6-4341-9a7b-2b9ecc7e8d5e', v_uni_id, 'FIN30200', 'Econometrics of Financial Markets', 'Business', 'This module aims to provide students a solid understanding of the econometric approaches that are commonly employed in finance and economics from an applied perspective. In particular, the module begins with an overview of the classical linear regression model, the ordinary least squares (OLS) estimator, progressing to hypothesis testing and model diagnostics. The module then covers univariate time series modelling, including ARMA processes, forecasting and explores the topics of stationarity and cointegration. It further introduces volatility modelling with ARCH and GARCH frameworks. Real-world data will be used throughout to demonstrate applications and to answer empirical questions in finance.', 'https://www.ucd.ie/modules/FIN30200', 'fin30200'),
    ('ec76c123-d305-43d7-8e4d-00fa72886271', v_uni_id, 'FIN30530', 'Sustainable Finance', 'Business', '“There can be no Plan B, because there is no planet B”, Former United Nations General Secretary, Ban Ki-Moon. Environmental risk, climate change, and societal concerns have been at the centre of public debate for some time and there is growing evidence to suggest such concerns are increasingly important to the decision-making process. The United Nations developed the 2030 Agenda for Sustainable Development (UN, 2015) to guide the transition towards a sustainable and inclusive society that incorporates environmental and societal challenges. They established 17 Sustainable Development Goals that are of critical importance in facilitating this transition. While achieving these goals and successfully transitioning to a net zero carbon society requires a transdisciplinary approach, finance plays a central role. The primary function of the financial system is to channel funds to their most productive uses to maximise growth. Hence, finance can play a leading role in accelerating the transition to a decarbonized and more circular system by allocating investment to sustainable corporations and investment opportunities. Sustainable finance examines how finance interacts with economic, environmental, and societal issues. The traditional approach to finance focuses on maximising shareholder wealth, whereas here we will focus on financing that incorporates the interests of multiple stakeholders (both internal and external). In this module we will examine sustainability and why it matters, the challenges and opportunities for corporations including corporate governance and behaviour, internalizing externalities, changing business models, and sustainable reporting; and how to finance sustainability including sustainable equity investment, sustainable debt (green bonds, blue bonds, social bonds), and investing for long-term value creation. Please note that this module is designed to be interactive, so student participation is essential.', 'https://www.ucd.ie/modules/FIN30530', 'fin30530'),
    ('6fc2039e-8f3d-4c4d-a7e2-d5facefc3f55', v_uni_id, 'FOR20120', 'Apiculture - bees, pollination and people', 'Agriculture & Food Science', 'This module examines the most important insect pollinators and gives an insight into their taxonomy, biology and ecological role. The focus will be on bumble bees, solitary bees and honey bees. It will provide the student with an understanding of the variation in their biology and provide them with knowledge of specific pollinator species. The module will also identify human activities that affect (improve or impair) survival of pollinating insects. Emphasis is placed on the honey bee because of its importance, both as a honey producer and as a pollinator of cultivated crops. Beekeeping is described in some detail with practical demonstrations of management, and every student will have an opportunity to handle honeybee colonies in an apiary. Apiary practical sessions will be arranged for groups of 10 at a time (protective clothing provided), depending on student and staff availability for practical sessions based in Rosemount Environmental Research Station. The video project will also be arranged in small groups and will make use of student’s own mobile phone video recorders. The lectures will be delivered by UCD staff as well as invited speakers, who will cover topics such as pollinator ecology (bumblebees, honey bees and solitary bees), pests and diseases of honeybees and other pollinators. These guest lecturers have come from backgrounds such as the National Biodiversity Data Centre, Crop Policy Production and Safety Division of the Department of Agriculture, Food and the Marine, the Teagasc Bee Disease Diagnostic Service at Oak Park and the Federation of Irish Beekeepers Associations.', 'https://www.ucd.ie/modules/FOR20120', 'for20120'),
    ('28ad8409-dd70-492f-b08f-b1e7de51d38a', v_uni_id, 'GEOG10080', 'Dynamic Earth', 'Geography', 'This module introduces students to the Earth, to its environmental systems and to the ways in which these systems operate and change both spatially and temporally, producing distinctive physical geographies. Topics that are introduced include: the history of physical geography; the Theory of Plate Tectonics and the Rock Cycle; the Atmosphere, the Hydrological Cycle, Glacial, Fluvial and Coastal systems. An important theme of the course is the impact of the physical environment on humans and vice versa. The scale and intensity of human activities are now large enough to affect the Earth’s planetary systems — e.g. global warming. This theme will be explored through an introduction to the Risk Management of Natural Hazards. The module is delivered via lectures and three tutorials during the trimester that cover a lecture topic in detail.', 'https://www.ucd.ie/modules/GEOG10080', 'geog10080'),
    ('fbbe9cdd-5c05-411c-8df0-e61a4f01522e', v_uni_id, 'GEOG10100', 'People, Places, Regions', 'Geography', 'People, Places, Regions introduces students to the field of Human Geography, which is the study of the dynamic relations between people and places. In this module, our aim is to gain an understanding of such complex processes as globalization and development, and the regional disparities in prosperity and inequality that result from these. The discussion will evolve around the three main themes of economic, political, and social actions, all of which significantly shape the spatial organization of human activities. The module will present a general overview of the discipline, provide the opportunity to develop independent critical thinking skills, and offer insight into practical skills and tools that can be applied to a wide range of research settings. Overall, People, Places, Regions supplies the foundation for further, more topic specific, modules that focus on the spatial analysis of political and socio-economic phenomena at later stages.', 'https://www.ucd.ie/modules/GEOG10100', 'geog10100'),
    ('7b3ca7d8-d699-4c2b-a2a0-767e3b5e4f47', v_uni_id, 'GEOG10140', 'Mapping a Sustainable World', 'Geography', 'As a core first year module, Mapping a Sustainable World aims to provide students with a foundation in geographical data, mapping, spatial analysis and writing skills. It will explore the organisation and manipulation of geospatial data, cognitive mapping and basic statistics, and will address locational considerations (e.g. coordinates and space), map projections, and map design. It will also introduce technological tools and methods available to map, analyse and disseminate geographical information. The module will be mainly tutorial-based but will include lectures and local fieldwork, providing an interactive and applied learning environment to explore technical and technological geospatial methods and approaches. In doing so, it will enhance students’ geospatial awareness and provide them with skills to examine relationships, interactions and interdependencies between human and physical components of the environment. It will provide skills applicable across the rest of the modules in the first and subsequent stages of the Geography curriculum and, in particular, prepare students for the core Geographic Information Systems module in stage 2.', 'https://www.ucd.ie/modules/GEOG10140', 'geog10140'),
    ('0989f2f8-0050-4687-8e03-b79fcfc85bc3', v_uni_id, 'GEOG20230', 'Intro: GIS for Sustainability', 'Geography', 'Welcome to GEOG20230 - Intro: GIS for Sustainability. This module will introduce you to the use and application of a Geographic Information System (GIS) which allows the acquisition, processing, analysis and visualisation of location-based data. With the increasing application of GIS in research and practice across a wide range of disciplines and sectors including the three pillars of sustainability and, as such, this technical skill is valuable, transferable and highly sought after. This module will particularly introduce you to the basics of GIS and its applications in sustainable development using mainly the ArcGIS Online (AGOL) software. Applying the problem-solving approach and hands-on practical sessions, you will be trained on the collection, visualization and analysis of sustainability-related geographic data with real-world working examples, and exercises focused on broad analytic themes that GIS is designed to handle. The lectures will initially focus on mapping and the main parts of a GIS. Later lectures and the assessments will be concerned with the tasks that GIS is designed to handle, i.e. digitisation, spatial analysis, data management. An aspect of the course, for which you will be assessed, is the integration of GIS work with broader analyses and writing skills to produce relevant and comprehensible reports. In the end, you will have technical skills and competencies in GIS which is highly desirable while your problem-solving, decision making, and academic writing skills will be sharpened.', 'https://www.ucd.ie/modules/GEOG20230', 'geog20230'),
    ('fb1ef35f-6267-4166-86db-630ed30e5097', v_uni_id, 'GEOL10060', 'Introduction to Earth Sciences', 'Earth Sciences', 'This module introduces students to Earth Science, the multi-disciplinary study of the past, present and future of planet Earth and other planets in our solar system. The course is in 3 parts, each comprising 5-8 lectures, one or two laboratory class(es) and an independent on-line exercise. Most lectures and all practicals will be presented Face-to-Face, with recordings of all lecture and practical classes also provided online. No previous knowledge of the subject is assumed. The examinable content is that presented in the lectures, practical exercises and independent on-line exercises. No textbook is required. The first part considers the origin of the solid Earth, its atmosphere and oceans and how these have evolved over the past 4,600 million years. It examines in detail the concept of plate tectonics and explains how this relates to the global distribution of earthquakes and volcanoes, and impacts on other important processes that shape the Earth, including oceanic circulation, and climatic patterns. The second part examines how surface processes and burial generate the sedimentary rocks that record Earth’s history. This geological record is an archive of environmental change over time. Particular emphasis is placed on detailing the broad scale geological evolution of Ireland via analysis of sedimentary rocks of different age. The final part reviews the history of life on Earth as recorded in the fossil record, and emphasises the coupled evolution of the geosphere and biosphere. Selected key events in the evolution of life through time are discussed, including the origin and early evolution of life, evolution of animals and plants, and global scale environmnetal catastrophes through time. Particular emphasis is placed on the role mass extinction events have played, and whether the global scale biotic changes the Earth is currently experiencing warrants the descriptor ‘the sixth mass extinction event’.', 'https://www.ucd.ie/modules/GEOL10060', 'geol10060'),
    ('7fa6bd77-44f4-4ef0-97a0-273bcd8508ec', v_uni_id, 'GRC20130', 'Study Tour of Ancient Greece', 'Classics', 'This module provides students with experience of the landscape, monuments and material culture of ancient Greece, facilitating a greater understanding of the societies that flourished in this region in the past. It consists of a 10-day study tour to mainland Greece, visiting key sites and museums, and is followed by related class sessions during Autumn trimester. The archaeological remains date from a range of periods, enabling an appreciation of the main chronological developments in Greek society from the Bronze Age, through Iron Age, Classical, Hellenistic, Roman and into Byzantine. Sites on the itinerary include Mycenae, Tiryns, Corinth, Eleusis, Epidaurus, Delphi, Olympia, Bassae, Mystras and a number of important locations within Athens (e.g. Acropolis, Agora, Kerameikos). The tour is led by lecturers associated with the Irish Institute of Hellenic Studies at Athens (IIHSA), who provide guided tours at each site. The Autumn class sessions focus on building research skills and enabling you to carry out the module assessments: a travel journal and an individual research project relating to a site visited on the tour. This module is available as an elective. NB - this tour takes place in summer 2026 and students MUST have gone on the tour to take this module, which runs in Autumn trimester of 2026-27.', 'https://www.ucd.ie/modules/GRC20130', 'grc20130'),
    ('237fd0bc-27c4-40b1-9f70-643ddaf57c81', v_uni_id, 'HIS20950', 'European Statecraft, Strategy & Culture, c. 1470-c.1770: Personalities & Power', 'History', 'Europe or Western Christendom as it was more generally known underwent a major transformation following the fall of Constantinople – the capital of the Byzantine Empire or Eastern Christendom in 1453. It was a crucial time – a life or death moment for Europe. Faced with the real prospect of conquest by the overwhelming power of the Ottomans and their allies, European Society, riven by dissension and crippled by mediocrity faced an existential crisis. Yet against the odds, individual personalities at different times such as, for example, Isabel de Castilla, Pope Julius II, Armand Cardinal Richelieu of France, Friedrich-Wilhelm von Brandenburg, and Maria Theresa and Wenzel von Kaunitz of Austria emerged to give serious leadership in politics, culture, military strategy and diplomacy. The impact of the political and legal ideas of Machiavelli, Vittoria, Erasmus, Hotman de Villiers, Montesquieu, Lipsius and Spinoza for example, upon the exercise of power will be assessed. This module examines who the great personalities of the age were, and who and what formed their mindsets and inspired them to the significant achievements that reversed the rot, rescued their peoples and brought about the rise of the nation-states as great powers with political and cultural influence on the world stage from the sixteenth to the twentieth centuries.', 'https://www.ucd.ie/modules/HIS20950', 'his20950'),
    ('7d1bbbda-b476-41f0-a5fb-c31b95baf862', v_uni_id, 'HIS31250', 'Old Germany', 'History', 'It is not without significance that after 1945 the founding fathers of the movement for European Union looked to the supra-national federative structures and institutions of the Holy Roman Empire of the German Nation for inspiration as a role model or precursor. This module will examine the constitutional, political and cultural natures of the Empire and the historiographical debates concerning its viability. Within this context, the module will analyse the rise of ‘imperial patriotism’ and early German national consciousness, the emergence of the ‘balance of power‘ in International Relations after 1648, the German Enlightenment and Cultural Renaissance in the princely courts, the rise of Brandenburg-Prussia, the evolution of Austro-Prussian Dualism and the bi-polarisation of the German world between Vienna and Berlin.', 'https://www.ucd.ie/modules/HIS31250', 'his31250'),
    ('d1efb882-e0bf-4fce-a7be-a885a23c9a7a', v_uni_id, 'HIS31700', 'Origins of the First World War', 'History', 'The origins of the First World War remains one of the most controversial episode in modern history. This module will examine not only why war came about in 1914, but also how the European great powers maintained peace between themselves for over four decades following the Franco-Prussian War of 1870/1. We will examine key developments in European politics, such as the formation of alliances and the resolution off major crises. We will analyse key themes, such as the role of the military, the impact of imperial expansion, and commercial relations. The module will conclude with an assessment of the July crisis, showing how peace between the European powers finally collapsed.', 'https://www.ucd.ie/modules/HIS31700', 'his31700'),
    ('07c3122b-8cb4-48b2-aa38-0d8f51a797f8', v_uni_id, 'HIS32310', 'Revolutionary Russia, 1905-1921', 'History', 'In under twenty years, Russia experienced three revolutions, world war, civil war, the collapse of the three-hundred-year-old Romanov dynasty, and the rise of the Soviet state. This course examines the causes and consequences of these tumultuous years from 1905 to 1921, exploring the rich political, social and cultural world of revolutionary Russia. It looks at the challenges of reform and modernisation in late imperial period, the rise of revolutionary politics, the impact of the First World War and the immediate events of 1917 leading to the establishment of Bolshevik power, before assessing the Red victory in the civil war, utopian culture and the consolidation of the early Soviet state. In doing so, the course focuses on the centres of power in Moscow and Petersburg, but also ventures into provinces and countryside to assess the ways in which political and social change unfolded elsewhere. We will also engage with critical historiographical debates on the ‘inevitable’ fall of the Romanov dynasty, continuities between the late imperial and early Soviet systems, and the relationship between state, society and the individual before and after 1917. Our discussions are rooted in weekly thematic seminars which use a set of primary sources to dig deeper into individuals’ experiences of, and responses to, the arc of revolution from 1905-1921.', 'https://www.ucd.ie/modules/HIS32310', 'his32310'),
    ('7191e374-b875-4b18-ad1e-07b075d22a97', v_uni_id, 'HNUT10020', 'Human Nutrition I - Understanding Nutrition', 'Agriculture & Food Science', 'This module is designed to give a comprehensive introduction to nutrients and human nutrition. We will look at individual macronutrients (protein, carbohydrate, fat and alcohol) and micronutrients (vitamins, minerals and trace elements), the functions of each and what happens if a person is deficient in any one of these. We will also look at the food sources of nutrients, our requirements across the life span and the national food based dietary guidelines recommended to ensure adequate intakes. Tutorial classes will introduce you to nutrition research, how and where research is published, and how to refer to nutrition research when writing about nutrition. The tutorial classes are mandatory and will cover your continuous assessment for this module.', 'https://www.ucd.ie/modules/HNUT10020', 'hnut10020'),
    ('b601de64-b2e7-40f1-a0f3-94ff2337975c', v_uni_id, 'HNUT10030', 'Physiology for Nutrition', 'Agriculture & Food Science', 'This module will provide students with the fundamentals of human physiology covering the following body''s systems (muscular, gastrointestinal, renal, cardiovascular, respiratory, nervous, and immune) with a focus on the application of nutrition to these systems. The module covers a large amount of content and requires students to complete weekly assessments to support engagement with this learning. This foundational knowledge is required in the later study of the control and integration of body systems with nutrition in health and disease states.', 'https://www.ucd.ie/modules/HNUT10030', 'hnut10030'),
    ('2ea3bc9c-151a-4ba7-92fc-17a45de5f3c9', v_uni_id, 'HNUT20020', 'Nutrition and Health', 'Agriculture & Food Science', 'This module will introduce basic concepts of immunology, endocrinology and metabolic balance. The main focus will be on the physiology of key biological systems in the study of Human Nutrition. The module will examine the relationship between diet and chronic diseases such as cardiovascular disease, osteoporosis, obesity and diabetes.', 'https://www.ucd.ie/modules/HNUT20020', 'hnut20020'),
    ('a9cde293-d0c1-4df8-a1f0-76274064ed56', v_uni_id, 'HNUT20060', 'Human Nutrition II - Nutrients in Life Stages', 'Agriculture & Food Science', 'This module will cover the key physiology and biological changes that occur from pregnancy through to old age, with an emphasis on the importance of nutrients during these different stages of the lifespan. Other areas of study will be an introduction to nutrition epidemiology and the relationship between diet and chronic diseases such as cardiovascular disease, osteoporosis, obesity, cancer and diabetes.', 'https://www.ucd.ie/modules/HNUT20060', 'hnut20060'),
    ('d58617d2-e028-4faf-8c24-0a8854b7f0ed', v_uni_id, 'HNUT20070', 'Population Nutrition Research', 'Agriculture & Food Science', 'This module will introduce students to nutrition research techniques commonly used, both in the field and laboratory settings. Topics covered will include: study design, dietary intake assessment, body composition analysis, energy expenditure analysis and others. Both the application and theoretical background of such techniques will be dealt with in detail. Students will learn how to analyse and manage dietary intake data The module will use a mix of online and face-to-face teaching methods.', 'https://www.ucd.ie/modules/HNUT20070', 'hnut20070'),
    ('22096391-0bae-482b-9924-bca148c11e95', v_uni_id, 'HNUT20080', 'Laboratory Nutrition Research', 'Agriculture & Food Science', 'This module will introduce students to techniques commonly used in a research laboratory. The theoretical background of these techniques will be dealt with in detail. Laboratory and techniques classes will give hands on-experience with some of the techniques covered in lectures. This module will introduce students to nutrigenomics.', 'https://www.ucd.ie/modules/HNUT20080', 'hnut20080'),
    ('72eeaef8-ad9c-44a0-a08f-cd1938be3948', v_uni_id, 'HNUT30170', 'Professional Work Experience', 'Agriculture & Food Science', 'Distinction/Pass/Fail (GPA Neutral) Students will complete a 10-month placement in the food industry, nutrition research, health promotion or nutrition regulatory bodies in their 3rd year. Placements will be in Ireland, UK, Europe or possibly further afield. It is intended that on completion of their Professional Work Experience (PWE) placements students will have a greater understanding of the role of the nutritionist and a greater appreciation of the relevance of technical information presented to them in their degree course. Students will see the practical application of many subjects, analyses and principles, will have the opportunity to improve their written, oral and communication skills and to practice appropriate professional conduct in the workplace. This period of Professional Work Experience is mandatory and must be undertaken in Stage 3. Successful completion of this module is mandatory for graduating on completion of Stage 4.Students must familiarise themselves with and abide by the regulations for PWE as set out by the Agricultural Sciences Programme Board. For each placement, a host contract must be completed, signed by the host and received by UCD, before the placement will be deemed to have commenced by UCD. Furthermore, placements (and parts thereof) which have been completed in the absence of an appropriately completed host contract will not be accepted. Only in the most exceptional circumstances will any deviation from this requirement be permitted and this must have the agreement, in writing, of the PWE co-ordinator.', 'https://www.ucd.ie/modules/HNUT30170', 'hnut30170'),
    ('0fb61033-4b65-4389-bbd5-42e1fa27e705', v_uni_id, 'HNUT40020', 'Nutritional Metabolism', 'Agriculture & Food Science', 'This module will cover lipid metabolism, vitamin metabolism and integration of macronutrient metabolism. All subjects will be covered in detail with specific emphasis on current literature and in the context of diet-related diseases/conditions such as Metabolic Syndrome, obesity and non-alcoholic fatty liver disease.', 'https://www.ucd.ie/modules/HNUT40020', 'hnut40020'),
    ('7e957799-cd97-4c73-ae88-cce1eb5e2f55', v_uni_id, 'HNUT40220', 'Clinical Nutrition', 'Agriculture & Food Science', 'This module aims to give you a basic understanding of some key topics and case studies in clinical nutrition. Obtaining this information will allow you to understand the basics of clinical nutrition recommendations. This module provides an integrated study of the role of diet in the cause and treatment of disease. It will explore the interaction of disease and diet in various areas of metabolism and specific disease states. It will examine the use of diet in treatment of certain diseases and examine methods of nutritional assessment. This knowledge is integrated with an understanding of the medical aspects of common disease states.', 'https://www.ucd.ie/modules/HNUT40220', 'hnut40220'),
    ('0eccc026-7ea1-4305-945b-5c7c43627489', v_uni_id, 'HNUT40240', 'Food Regulation', 'Agriculture & Food Science', 'Food Regulatory Affairs represents the integration of many different disciplines including food science, health, law, ethics, policy, economics and politics. This module is intended to give you a basic understanding of how European food regulatory processes work and to study some of the key drivers of European food regulatory affairs. Emphasis will be placed on the following areas: the European model for food safety, the food chain, risk analysis, food additives and food labelling. Practical examples and case studies will be used to support learning.', 'https://www.ucd.ie/modules/HNUT40240', 'hnut40240'),
    ('aeccaf1b-3c67-45ed-b016-4c7050c0af12', v_uni_id, 'HORT10040', 'Introduction to Sustainable Horticulture', 'Agriculture & Food Science', 'This module covers the Environmental, Social and Economic sustainability of horticultural production. Environmentally, horticulture provides the following ecosystem services: food, fibre, fuel, genetic resources, biochemicals, natural medicines, fresh water and improved air quality. Socially, horticulture contributes to our physical and mental health through the consumption of fresh horticultural produce and by providing amenity spaces in which people can exercise, relax and spend time in nature. Economically, horticulture plays a key role in mitigating the climate crisis through increasing carbon sequestration, reducing GHG emissions using sustainable soil management, and reducing inputs through implementation of advanced technologies such as Precision Horticulture.', 'https://www.ucd.ie/modules/HORT10040', 'hort10040'),
    ('52775d8c-1027-41dc-94f5-b14d92c06081', v_uni_id, 'HORT20070', 'Agricultural Botany', 'Agriculture & Food Science', 'This module integrates our understanding of basic plant science with the objectives of agricultural plant production systems. Knowledge of fundamental plant biology and physiological processes allows manipulation of factors that are key to plant growth and development; and which underpin good husbandry practice, and improved yield and quality in both crop and livestock production systems. The module focuses on the following topics: 1) The role of plants in food production, and as regulators of air, soil and water quality. 2) The basic requirements of plant growth and development. 3) Plant morphology: roots, stems, leaves, fruits and seeds. 4) Major plant groups of agronomic importance, including forage grasses, cereals, legumes and other important field crops. 5) Biology and ecology of weed species. 6) Environmental and physiological regulation of plant growth and development. 7) Plant relationships with beneficial and pathogenic microorganisms. 8) Introduction to selective breeding of crops', 'https://www.ucd.ie/modules/HORT20070', 'hort20070'),
    ('6ecbc49b-5048-4089-aebb-889afb423cb9', v_uni_id, 'HORT2008K', 'Fundamental of Horticulture', 'Agriculture & Food Science', 'Introduction to the principles and concepts of Horticulture through an understanding of the scientific basis of horticultural practice. Areas covered include: Importance of site selection for plant production under field and protected environments; Growing media; Propagation techniques (seed and vegetative propagation); Training and pruning techniques for food and amenity plants; Selection and use of different plant species for a range of landscape situations; Outline of Plant Protection Methods.', 'https://www.ucd.ie/modules/HORT2008K', 'hort2008k'),
    ('9087d540-5c29-4428-9137-11450053bdf1', v_uni_id, 'HRM10730', 'Business in Society', 'Business', 'This module considers the nature of the relationship between business and society, and how societal issues are increasingly affecting all aspects of corporate strategy and behaviour. It will introduce students to the key issues of morality, ethics and policy and explore contemporary issues in this arena. Moreover, topical issues, around which informed perspectives and opinions diverge, will form an integral part of the curriculum, e.g. climate change and sustainability, globalization, working conditions in MNC supply chains and gender equality. The module aims to provide students with a strong sense of the connections (and tensions) between individual, organisational, and societal actions and outcomes, a sense of social embeddedness, while also retaining a positive business outlook. This module will interrogate these issues and frame student assessment and evoke student engagement through critical analysis and written and verbal expression. The following questions will be discussed: Should firms be responsible and sustainable if it negatively impacts the bottom line? What role should the state play in regulating businesses and ensuring firms are more sustainable? What labour standards should western companies adhere to when manufacturing in developing countries? And others. These are questions to which there is no ‘one right answer’. Rather there are a range of viewpoints and the challenge of students of the subject is to critically assess differing viewpoints by drawing on appropriate empirical and theoretical academic research.', 'https://www.ucd.ie/modules/HRM10730', 'hrm10730'),
    ('90e49bc3-043f-456c-98fd-f049bf29d28b', v_uni_id, 'HRM30010', 'Human Resource Management', 'Business', 'Human resource management is concerned with the effective management of people and is a challenge faced by all organisations. Although operational and technical excellence are fundamental to ensuring continuous customer satisfaction, the effective management of human resources also plays an important role in gaining and maintaining organisational success. There is no one ''best'' way to manage an an organisation''s human resources. This course aims to examine the tensions and ambiguities commonly associated with HRM. Each of the core HR policy areas will be explored and students will be encouraged to critically assess recent trends and developments in HRM.', 'https://www.ucd.ie/modules/HRM30010', 'hrm30010'),
    ('c1d35651-e98e-49fa-a97e-4e39b6582fbd', v_uni_id, 'HRM30020', 'European IR and HRM', 'Business', 'This module provides you with an introduction to European industrial relations and HRM: What are the major issues at work and employment relations in Europe by comparison to the USA? How do globalisation and European integration processes affect workers, managers and the state? The module is essential for students in international business, industrial relations and HRM. Students of European politics, sociology, social policy, law, and social justice have also found this module very interesting. This module includes additional activities: 1) a study trip to Brussels. In Brussels, students will have direct access to actors that shape the emerging multi-level European employment relations system, such as EU-level employer and union federations, and the European Commission and Parliament. 2) tutorials to help students preparing their team presentations', 'https://www.ucd.ie/modules/HRM30020', 'hrm30020'),
    ('17800625-3e49-410e-9ceb-73a061906d16', v_uni_id, 'HRM30060', 'An Introduction to Equality, Diversity & Inclusion', 'Business', 'The module aims to examine the origins and theories of inequality in employment, as well as the mechanisms for tackling these inequalities. Labour market data and the main theoretical explanations for the segregation of labour by various diversities will be examined. The economic, political, and social context in which such divisions are perpetuated will also be examined. The module is also concerned with attempts at overcoming inequalities in the workplace. This involves a critical examination of equal opportunities and managing diversity in theory and practice, including legislation at domestic and EU levels, as well as employer and trade union initiatives and procedures.', 'https://www.ucd.ie/modules/HRM30060', 'hrm30060'),
    ('3f693fba-7044-4b51-8336-9519a7a0de7b', v_uni_id, 'HRM30070', 'HRM in Multinationals', 'Business', 'This module provides students with an opportunity to explore critical areas of international human resource management (IHRM), examining how people management has changed in the face of globalisation. The core principle of this module is that to understand HRM in multinational companies (MNCs), we must be sensitive to the question of context. The way that HRM develops and is implemented is shaped by a wide range of institutional and cultural factors, strategic and political interventions and struggles over the balance of power between capital and labour. In this module, students will be encouraged to critically debate key trends within IHRM including the convergence and divergence of HRM policies and practices in a global context, the difficulties of managing a global workforce, and the ethical and sustainability challenges created by the expansion of global capital. Many of you will go on to work in MNCs, whether that might be one of the ‘Big Four’, a social media company such as Google or LinkedIn, a manufacturing company like Smurfit Westrock or Siemens, or an international professional services company in law, marketing, or public affairs. In working for such companies, you will encounter the influence of different national business systems, different work cultures, and different regulations and laws, all of which will have a bearing on how IHRM systems and practices are developed. This module will help you understand the management of such complexities.', 'https://www.ucd.ie/modules/HRM30070', 'hrm30070'),
    ('40331db8-f0af-4b18-8fd7-d710cd02a3c9', v_uni_id, 'HRM30100', 'International HRM', 'Business', 'The module is designed to provide students with an opportunity to explore critical areas of international human resources management. Student will attend classes on core topics. These will include: globalisation and multinationals; strategy, structure and HRM in multinationals; managing across different regulatory regimes; employee voice; recruiting and selecting international managers; and reward and performance management systems in MNCs. There will be a team-based assignment related to these topics.', 'https://www.ucd.ie/modules/HRM30100', 'hrm30100'),
    ('3ff61e6d-2fb2-4c4b-ab87-e7e53cea0cc0', v_uni_id, 'HRM30120', 'People at Work', 'Business', 'This module is an introductory course in employment relations and human resource management. The module is intended to introduce students to academic debates in these two fields and, in particular, to equip students with the means to critically appraise the normative prescriptive literature that is abundant in this area of management. The module’s primary concern is to examine what management does when it manages people and its implications for decent work. It is not a techniques course, rather it is designed to develop an informed and critical understanding of how the management of people at work is undertaken, and with what consequences. Being sensitive to the context within which employers and employees work is particularly important. Thus, a key element of this module will be to help students understand how the national and international contexts of the enterprise influence the management of people at work. The module is organised in two parts. During the first half, we will look at key debates in the fields of ER and HRM, and in the second half, apply these debates to three “mega trends”: climate change, labour governance, and technology. This module recognises that the relationship between labour, capital, and the state within its broad political, historical, economic, and social context is experiencing dramatic changes. These changes raise important questions, many of which we cover. Are traditional forms of labour market regulations sustainable? Will unions continue to play an important role in helping to protect the interests of workers? Are new forms of employee voice developing and will they be as effective? Is work getting better or worse? Is conflict at work intensifying or abating? What role will new business practices such as algorithmic management and the rise of the gig economy have on managing people at work? How do we ensure a just transition for all? All of you have either worked, or will go on to work in a variety of jobs, not just the exclusive “Big Four”. You may be a manager, a CEO or a shopfloor worker. Just as in the ‘real’ world of work and business, there will be no ‘easy answers’ to some of the questions raised in this module. The nature of the phenomena under study is complex and their implications for people at work are uncertain. You will be expected to evaluate competing claims and evidence, establish and present your line of analysis, and provide coherent reasons for your conclusions.', 'https://www.ucd.ie/modules/HRM30120', 'hrm30120'),
    ('dbd20daf-1b81-49f3-8dc4-60cbf5638466', v_uni_id, 'HRM30140', 'Climate Change & Business Sustainability', 'Business', 'Climate change is one of today’s most pressing issues. As major emitters of greenhouse gases, business bears some responsibility for the environmental problems the planet faces and needs to contribute to the solutions. This module will provide students with a deeper understanding of the science of climate change, the international and regulatory framework, and emerging resource challenges and market opportunities. The module culminates in a two-day intensive workshop and negotiation of a mock United Nations Framework Convention on Climate Change (UNFCCC - a COP30 Agreement). Lectures will take place in the first 7 weeks of the Spring Trimester and the two-day workshop will take place in the first week of the Reading Weeks period (Mar 9-10). Attendance for both days of the roleplay is compulsory. Do not register for this module if you are unable to attend the in-person workshops in the first Reading Week (Spring Break 2027) on March 9 & 10.', 'https://www.ucd.ie/modules/HRM30140', 'hrm30140'),
    ('1b79e19e-9eb7-4b3a-b75b-22f6c4e88c42', v_uni_id, 'IA20100', 'Innovation for Sustainability', 'Innovation Academy', 'Pass/Fail (GPA Neutral) As we face historic challenges of climate degradation, biodiversity loss, geopolitical instability and technological displacement the overall aim of this module is to develop your ability to build community, develop creative approaches and explore new ways of living to ensure a better future for us all. The challenges of sustainability are increasingly urgent, inherently complex, and beyond the remit of any one discipline, sector or community. Over the course of this module you will develop your trans-disciplinary thinking via a series of activities, projects and real-world challenges. You will travel off-campus to visit and engage with a community organisation and a sustainable business to observe and explore how sustainable approaches work in practice and are conceived, launched and scaled in the real world. You will learn about the key challenges in sustainability and contribute to the circular economy pilot (mushroom farm) based at UCD Greenacre, while developing your hands on skills and innovation and sustainability mindsets. "I have learned you are never too small to make a difference." Greta Thurnberg UCD INNOVATION ACADEMY At the UCD Innovation Academy, we are Educator Practitioners with extensive real-world experience as academics, business and social entrepreneurs, tech thinkers, creative professionals and design practitioners. Our teaching is grounded in academic rigour. Our focus is on ‘learning from doing’ in a real-world context. Classes include a combination of individual and team tasks and activities, along with discussions, presentations and reflection. Enrollment on an Innovation Academy module means a commitment to active participation and engagement, which necessitates attendance at all scheduled classes. Notes: Class Size : We limit our class size to 36 students or less. We require a minimum of 16 participants to ensure enough people for teamwork and a dynamic classroom environment. On very rare occasions, if fewer than 16 registered students register, we will offer students the opportunity to join another class. For further information about the UCD Innovation Academy see www.innovationacademy.ie', 'https://www.ucd.ie/modules/IA20100', 'ia20100'),
    ('eacb730a-1798-4bf6-b61b-b181dadf3d39', v_uni_id, 'IA20130', 'Designing the Future', 'Innovation Academy', 'Pass/Fail (GPA Neutral) Both the working and academic worlds are changing rapidly. ''Designing the Future'' will help to develop your innovation, communication, and design skills needed to evolve and thrive. Through a series of tasks and challenges, you will learn how to use a variety of MakerSpace tools and the Design Thinking Process to solve real challenges, concluding the module with a portfolio-ready project. We will consider the impacts of design, material, and environments / social sustainability in the prototyping and making process. We will cover both transversal skills and technical skills such as 3D printing, laser cutting, vacuum forming, and more. Open to all disciplines, this module is suitable for those with little or no prior making experience and those who know the basics but may want practical hands-on experience with prototyping technology. TOPICS INCLUDE: The Design Thinking Process Physical prototyping 3D Modelling and Vector Design essentials 3D Printing & biomaterials Vacuum Forming and mould making Laser Cutting/Engraving Electronics Over the course of the module, you will be introduced to a variety of technology and visualisation tools. You will build ideation, testing, and prototyping skills while improving your communication skills with non-technical audiences. Using these skills, you will make physical prototypes using 3D printing, wood, acrylic and other materials culminating in a creative project which may be used in a professional portfolio. FORMAT: This module is offered face-to-face only. There will be a mix of facilitated classes and practical sessions, as well as teamwork and individual tasks to be completed outside of class time. Enrolment in an Innovation Academy module means a commitment to active participation and engagement, which necessitates attendance at all scheduled classes. NOTE ON ASSESSMENTS: Assessment is continuous throughout the module, with a final reflection due at the module end.', 'https://www.ucd.ie/modules/IA20130', 'ia20130'),
    ('10f72ab4-0607-4685-8ce2-2eeff7331a95', v_uni_id, 'INRL10020', 'Foundations of Intl Relations', 'Politics & Int Relations', 'This module offers an introduction to the main issues in contemporary international politics. It first examines the development of the modern international system, focusing especially on the post-Cold War era. It then examines a range of substantive issues that occupy students of contemporary international politics: war and other forms of inter-state conflict, global trade and communication, migration, economic inequality, international integration, terrorism, human rights, the United Nations and the role of multinational corporations and transnational pressure groups. Note: This is an attendance-critical module. Students must attend lectures and tutorials in person. There is no possibility of taking this module online. It is recommended to complete this introductory module before attempting INRL20040 International Relations.', 'https://www.ucd.ie/modules/INRL10020', 'inrl10020'),
    ('faa8beda-d395-4782-80e7-7828003e7108', v_uni_id, 'INRL20040', 'International Relations: Introduction to Theories and Empirics', 'Politics & Int Relations', 'What drives conflict and cooperation in international relations? Why do countries trade? To what extent do international organizations matter? Can countries work together to protect the environment? This course explores all these questions and more. You will be introduced to the different theories and concepts scholars have used to understand and explain international relations, as well as empirical findings of scholars in the fields of Political Science, International Relations (IR), and beyond. The course builds on introductory courses such as INRL10020 and POL10180. It prepares students for further study of International Relations or related fields, work in international political contexts, and critical engagement with world politics as citizens.', 'https://www.ucd.ie/modules/INRL20040', 'inrl20040'),
    ('3a069dad-412c-469b-9d6d-e279c59ee895', v_uni_id, 'INRL20080', 'Irish Foreign Policy', 'Politics & Int Relations', 'This module offers an exploration of the derivation, development and practice of Irish foreign, security and defence policies, with a particular focus on contemporary challenges. Students will gain a detailed insight into Ireland''s place in the contemporary world order, the transformation of Irish national foreign, security and defence policy through its membership of the European Union and the efforts of Irish policy makers to pursue Irish interests and values within an evolving global order. This will include an analysis of Irish foreign policy strategy, policy making and economic, political and military enagement. It is intended that this module will provide a solid theoretical and empirical grounding for further advanced study, and will encourage students to compare and to evaluate critically competing understandings of Ireland in the world. Transferable skills will be developed in independent research, teamwork, communications and role play.', 'https://www.ucd.ie/modules/INRL20080', 'inrl20080'),
    ('59e49f39-f8fb-4bcc-9034-6018127a8873', v_uni_id, 'INRL20110', 'Intro to Middle East Politics', 'Politics & Int Relations', 'This module introduces students to the emergence of the modern Middle East and key approaches to political life of the region. The first part of the module addresses broad historical background. The second part of the module examines a number of contemporary issues such as political economy, gender , political Islam and regional conflict. The module concludes with an exploration of recent changes in the politics of the region.', 'https://www.ucd.ie/modules/INRL20110', 'inrl20110'),
    ('e982d952-48d2-4ee8-85b9-9b63343ec851', v_uni_id, 'INRL20160', 'Introduction to European Union Politics', 'Politics & Int Relations', 'This module draws on a range of political science research on European integration and European Union politics to analyse the development of the EU and how it operates today. The module addresses one of the most important questions in the study of European politics and international organisations: Why did a diverse group of states construct what is currently the world’s most extensive example of international integration? The module provides an extensive overview of the contemporary EU, including its institutions and policy-making processes using approaches from modern political science. We will assess how the EU is coping with economic and political challenges to its prosperity and legitimacy. By the end of the module, students will have a thorough grounding in EU politics and the manner in which EU institutions function and cooperate to make policy.', 'https://www.ucd.ie/modules/INRL20160', 'inrl20160'),
    ('f298b424-42ae-4d3b-9eaa-2a077d0cd186', v_uni_id, 'INRL30320', 'Gender in War & Peace', 'Politics & Int Relations', 'Since 2000, the United Nations recognises with Security council Resolution 1325 the interconnectedness between gender and peace and security concerns. This comprehensive, active-participatory course explores the relations between gender, war, militarism, violence and peace from both normative and empirical perspectives. First, the course will introduce a critical feminist framework for exploring international relations and examine various topics that illustrate the connection of gender, war/conflict and peace. Second, it will explore the connection between gender, war/conflict and peace in different case studies. Questions that will be addressed in the course include but are not are not limited to the following: Theories of peace and conflict; what changes with a gendered perspective? Gender in foreign policy; what does a feminist foreign policy look like? Normative changes; what is the normative impact of gendered efforts in international peace and conflict policy making?', 'https://www.ucd.ie/modules/INRL30320', 'inrl30320'),
    ('7e215992-5b14-4641-b105-45d7682c4712', v_uni_id, 'INRL30350', 'International Justice', 'Politics & Int Relations', 'In an increasingly connected and unequal world, it is increasingly difficult to argue that the claims of justice can be limited to the society or group we happen to find ourselves in. This course examines the main rival theories of justice and their application, first on a national and then on a global level. We will first examine certain key concepts such as justice and human rights, second the main moral and political theories of global justice and finally we will conclude with an examination of concrete policy issues related to global inequality.', 'https://www.ucd.ie/modules/INRL30350', 'inrl30350'),
    ('550a9b71-fbcc-4b5e-88f4-1a4f6dcec594', v_uni_id, 'INRL30370', 'Terrorism & Political Violence', 'Politics & Int Relations', 'The concepts of Terrorism and Political Violence loom large in contemporary politics and policymaking but are frequently misunderstood and under-theorised. This module will introduce students to a range of approaches to terrorism and political violence. The first part of the module will explore the history of terrorism and to a diversity of understandings of, and theoretical approaches to terrorism and political violence. The second part of the module will explore a range of topics including: types and causes of terrorism, the state and terrorism, the role of religion, policy responses and the so-called ''war on terror''.', 'https://www.ucd.ie/modules/INRL30370', 'inrl30370'),
    ('92368ad4-e5ca-4876-8211-82c3d022a750', v_uni_id, 'INRL30400', 'EU Foreign Policy: understanding how the European Union and its member states engage with the world', 'Politics & Int Relations', 'This module explores the origins, development and contemporary practice of the European Union as an international actor. Particular attention is given to the challenges confronting EU foreign policy in an increasingly contested international order, including geopolitical competition, war and insecurity in Europe and its neighbourhood, economic security, human rights, development, migration, climate change and the changing transatlantic relationship. Students will examine the Union''s efforts to define and pursue common interests while reconciling the different priorities of its Member States. The module considers EU foreign-policy strategy and decision-making alongside the Union''s diplomatic, economic, regulatory, developmental and security and defence instruments. A distinctive feature of the module is its use of Problem Based Learning (PBL). Students work in teams on contemporary foreign-policy problems and assume professional roles such as EU and national diplomats, government officials, journalists and civil-society actors. Rather than simply studying EU foreign policy, students are therefore asked to research, negotiate, formulate and defend policy responses to realistic international challenges.', 'https://www.ucd.ie/modules/INRL30400', 'inrl30400'),
    ('4b67128c-7e49-4dcd-b09f-16804cb88cc0', v_uni_id, 'IS10010', 'Introduction to Communication & Media Studies', 'Information & Comms Studies', 'This module introduces students to the key concepts, theories, and models in communication and media studies. It explores the historical development and societal impact of various media forms, helping students understand how media shapes our world. By developing critical thinking and analytical skills, students will learn to evaluate media content and communication processes effectively. Students will engage with the history of media, the economic and cultural frameworks of media industries, and the ways media texts create meaning and influence audiences. In doing so, the module will examine key concepts like semiotics, representation, and media power, analysing how various media—from advertisements to films—construct narratives and convey ideologies. The module also examines the business side of media, including ownership, production cultures, and the economic forces shaping content and audience perception. Additionally, it critically explores representation and visibility in media, investigating how different social groups are portrayed and the power dynamics involved. Throughout the course, students will develop analytical skills to assess media texts and their broader social implications.', 'https://www.ucd.ie/modules/IS10010', 'is10010'),
    ('a65a526a-332f-4c01-901c-603acb2eff39', v_uni_id, 'LARC40700', 'GIS for Creativity', 'Architecture, Plan & Env Pol', 'Traditional Geographic Information Systems (GIS) are often taught as objective, data-crunching tools used to trace the physical world. This module frames GIS as a departing point for using geospatial information as a creative medium for landscape architects, architects, and urban designers. Addressing the growing demand for digital place-makers, GIS for Creativity transcends standard map-making and engages students in speculative cartography. By merging geospatial analysis with 3D and immersive media, students will learn to use geospatial data for spatial analysis and inquiry, while getting in touch with a variety of software and tools for enriching geovisualization. The core approach of the module is Virtual Site Analysis and Re-imagination. This module empowers students to use spatial data to propose speculative landscape and urban interventions. Students will translate 2D geospatial data into immersive 3D environments, ensuring their virtual landscapes are grounded in the functional and ecological realities of a site and the built environment, while actively pushing the aesthetic and narrative boundaries of digital world-building. To guide this translation from the physical to the virtual, the module operationalizes key theoretical frameworks of spatial communication. Jacques Bertin’s Semiology of Graphics and Kevin Lynch’s The Image of the City serve as the fundamental bases for understanding perception and representation. Through the creative application and intentional "misuse" of visual variables and 3D terrain modeling, students will learn to construct complex thematic maps and immersive digital twins that communicate compelling, future-oriented landscape narratives.', 'https://www.ucd.ie/modules/LARC40700', 'larc40700'),
    ('1ed1103b-e371-41b5-bcf0-30749242e975', v_uni_id, 'LAW10050', 'Constitutional Law: Institutional Framework of the Constitution of Ireland', 'Law', 'This course examines the institutional structure of the state which is set out by the Constitution. It will detail the various institutions and offices which are established by the Constitution. It will also consider the way in which the Constitution''s various provisions affect the relationship between the different branches of government. A number of core concepts will be discussed including democratic accountability, judicial review and the separation of powers. Broader questions of constitutional governance, concerning the divergence between the vision of government set out in the Constitution and the reality of how government works today, will also be referred to.Constitutional Law (of which this module forms a part) is an entry examination subject for both the Law Society and the Honorable Society of King''s Inns.', 'https://www.ucd.ie/modules/LAW10050', 'law10050'),
    ('640a5e76-5634-445d-ac21-8378dc0fb6bf', v_uni_id, 'LAW10060', 'Constitutional Law: Fundamental Rights under the Constitution of Ireland', 'Law', 'This course considers how the Constitution of Ireland protects fundamental rights and the relationship of these rights to the State''s obligations under the international human rights treaties to which it is a party. Examples of the fundamental and human rights that may be considered are: personal liberty; trial in due course of law; freedom of expression, assembly and association; religion; the family and education; private property; other personal rights, enumerated (such as the right to life) or unenumerated (such as privacy) and equality before the law. The course also considers which remedies a court can grant for violations of rights and may also deal with some other incidental topics - such as the Directive Principles of Social Policy. Irish Constitutional Law (of which this module forms a part) is an entry examination subject for both the Law Society and the Honorable Society of King''s Inns. Students on this module are expected to have read and understood the UCD Academic Integrity Policy and the School Protocol on Academic Integrity. Students must ensure that they comply with all requirements laid down therein and avoid academic misconduct. Students are not permitted to use generative artificial intelligence, or other machine learning technology, in their learning and in completing assessments on this module. Students are expected to follow Oscola Ireland in citing sources in completing assessments.', 'https://www.ucd.ie/modules/LAW10060', 'law10060'),
    ('44266e7d-6a8a-4b11-a3e2-54bf3c6dd52b', v_uni_id, 'LAW10190', 'Negligence and Related Matters', 'Law', 'The topics covered in this module will be:, Negligence;The Duty of Care; The standard of care; Policy considerations in negligence; Negligent Misstatement; Nervous Shock; Economic Loss; Omissions; Liability of public authorities; Professional negligence; Causation and remoteness of damage. The module is taught on a comparative basis with other common law jurisdictions.', 'https://www.ucd.ie/modules/LAW10190', 'law10190'),
    ('b25a10ee-7a36-44bf-851e-6d49339d5d53', v_uni_id, 'LAW10200', 'Nominate Torts', 'Law', 'Co-requisites: LAW 10190 Law of Tort I Description: The Topics covered in this module will be: Occupiers Liability; The Rule in Rylands v. Fletcher; Liability for Injury caused by Animals; Nuisance; Trespass to Land; Products Liability; Defences; Trespass to the Person;Trespass to Goods; Defamation and Defences to defamation. The module is taught on a comparative basis with other common law jurisdictions.', 'https://www.ucd.ie/modules/LAW10200', 'law10200'),
    ('5632b3a4-ffb9-40da-99e4-e706084c0e4b', v_uni_id, 'LAW10260', 'Criminal Procedure', 'Law', 'This module examines the various steps in the life-cycle of a criminal trial. It introduces the various state agencies and actors who play a role in the criminal process, including the police, the prosecutor, the judge and the jury. As well as pre-trial procedures such as bail and the decision to prosecute, students will consider the rights of persons who are arrested and accused of crimes. Students will gain a deeper understanding of the criminal trial and the principles which underpin it (including the presumption of innocence). This is an introductory module and no prior knowledge of law or criminal processes is required. This module is designed using principles of Universal Design for Learning (UDL) and includes guest lectures by external experts working in the criminal justice system. ** Penultimate and final year Law students are not permitted to register to this module as their in programme or Horizons elective.**', 'https://www.ucd.ie/modules/LAW10260', 'law10260'),
    ('27ab3faf-f8f4-4f89-859b-f59568595b86', v_uni_id, 'LAW10270', 'Civil Procedure', 'Law', 'This module examines the Irish Civil Processright from accrual of cause of action through to execution of judgment. Topics to be examined include - accrual of cause of action, limitation periods and statutes of limitation; civil jurisdiction of the courts; initiation of proceedings, including summonses and service; pre-trial aspects such as injunctions and discovery; aspects of the civil trial including the burden of proof, and the role of expert witnesses; enforcement and execution of judgment. Attention will also be given to alternative forms of dispute resolution ("ADR") including mediation and arbitration. There is also a focus on the history of civil procedure and the influence it has had on the development of modern civil law. ** Penultimate and final year Law students are not permitted to register to this module as their in programme or Horizons elective.**', 'https://www.ucd.ie/modules/LAW10270', 'law10270'),
    ('7586f8f4-9741-42ab-b708-c68e80ab3fb5', v_uni_id, 'LAW10340', 'Contract: Formation', 'Law', 'This module introduces students to the law relating to the formation of contracts. It will include a study of the following issues: Offer & Acceptance; Consideration (incl. Estoppel); Intention; Certainty & Formal Requirements; Terms of a Contract v Mere Representations; Rules of Construction; Exemption Clauses; and Implied Terms.The module focuses primarily on a study of relevant case law and statute.', 'https://www.ucd.ie/modules/LAW10340', 'law10340'),
    ('a5b91a88-f100-444f-88a0-bad24b6ee2a0', v_uni_id, 'LAW10350', 'Contract: Vitiating Factors and Remedies', 'Law', 'This course will look at possible vitiating factors for a contract. Students will consider the capacity to contract of certain vulnerable groups, such as children. We will look at what happens if one of the parties enters the contract due to improper pressure that was placed on them be it duress or undue influence. We will also consider what is the effect of a party entering a contract because of a misrepresentation that was made or whilst labouring under a mistaken belief. We will also consider the effect on a contract of an unexpected event occuring after a contract has been entered but before it has been performed. We will also consider the range of remedies that are available following on from a breach of contract. Particular emphasis will be placed on damages and we will look at the principles underpinning the assesement of damages. Students will also consider the range of other remedies available that a court might award.', 'https://www.ucd.ie/modules/LAW10350', 'law10350'),
    ('a7ae5119-406d-41eb-9792-b821ed13ba98', v_uni_id, 'LAW10360', 'General Introduction to the Irish Legal System', 'Law', 'General Introduction to the Irish Legal System (GIILS) acts as a critical introduction for students to the Irish legal system. Students examine the sources and hierarchies of laws in the common law Irish legal system within a rule of law framework. The concept of the rule of law is one that is threaded throughout this module. In this module we examine a number of key issues pertaining to: the rule of law; the role, function and jurisdiction of Irish courts; the creation of legislation and how judges interpret legislation- statutory interpretation; the system of common law; the doctrines of precedent and stare decisis; lawyering in the digital age, the Irish administrative state and the status of international law in the Irish legal system. Lectures in this module provide a substantive introduction to a topic/issue (20 hours). Most of your time engaging with this module will consist of completing reading lists in the remaining 105 hours (minimum). This will include tasks such as: - Reading legislation: Often, but not always, you will be directed to the specific sections and sub-sections of legislation you must read. - Reading case-law, be it a case in its entirety or certain sections of a case. Case-law you must read will be indicated on reading lists. - Reading texts and journal articles: A significant amount of time must be spent furthering your knowledge of the issue(s) introduced in a lecture. The core text for this module is often just a starting point. Where indicated, you must complete readings of other journal articles etc. This module is assessed by a two-hour end of Trimester examination (closed-book). A full outline of the structure of the examination will be provided via Brightspace. Students on this module are expected to have read and understood the UCD Academic Integrity Policy and the School Protocol on Academic Integrity. Students must ensure that they comply with all requirements laid down therein and avoid academic misconduct. Students are not permitted to use generative artificial intelligence, or other machine learning technology, in their learning and in completing assessments on this module. Failure to comply will have serious consequences.', 'https://www.ucd.ie/modules/LAW10360', 'law10360'),
    ('7b80aed7-8b98-4b0f-93af-17cfb9161bd5', v_uni_id, 'LAW10400', 'Business Law 1: Transactions, Negotiations and Organisations', 'Law', 'This module introduces commerce students to the fundamental features of the Irish legal system and to some of the major pillars of Business Law. General legal principles such as precedent and statutory interpretation are covered, as are core aspects of substantive areas of Law including the Law of Contract , Consumer Law, Employment Law and the Law of Tort. The role which law plays in shaping the business environment is demonstrated by reference to case studies (on, for example, consumer protection). The module also introduces students to concepts such as Health and Safety Law, Data Protection Law, Professional Regulation, and Money Laundering. Negotiation and the skills associated with it feature prominently in this module. Please note: Law students (BCL, BBL, BSc in Criminology with Psychology) may not register for LAW10400.', 'https://www.ucd.ie/modules/LAW10400', 'law10400'),
    ('a529b0d4-97a8-4f87-83b7-a849ca3c2543', v_uni_id, 'LAW10420', 'Legal and Professional Skills', 'Law', 'This five-credit module introduces students to the skills and knowledge which are essential to the study of law, effective learning at university and professional development. Students will be given a solid foundation in the skills of legal research; reading and analysing legal materials; legal writing and referencing skills. Students will have the opportunity to reflect on activities that will support their career and professional development, and develop their presentation and negotiation skills. Students are also introduced to their Academic Advisor and will have an opportunity to discuss their skills development with their Advisor. This module also includes an online workshop on Consent, run in conjunction with Active* Consent. The module is delivered face to face with supplementary support provided online via Brightspace. Teaching will be interactive and students are encouraged to ask questions in lectures and in the tutorial ** Penultimate and final year Law students are not permitted to register to this module as their in programme or Horizons elective.**', 'https://www.ucd.ie/modules/LAW10420', 'law10420'),
    ('f766b975-63b3-45f6-971c-5d11927bcf9d', v_uni_id, 'LAW10440', 'Law in Europe', 'Law', 'This module is designed as an Introduction to EU law and Institutions and is not offered to UCD Law students enrolled in a four year BCL or BBL programme . It is available to ''visiting'' or international law students and UCD students enrolled in non-law programmes. r It examines the powers and roles of key EU institutions and pays close attention to the European Commission and the European Courts (Luxembourg). It examines important EU principles such as supremacy and direct effect. It analyses selected areas of EU Economic Law such as free movement of citizens/workers/ goods throughout the EU. Students on this module are expected to have read and understood the UCD Academic Integrity Policy and the School Protocol on Academic Integrity. Students must ensure that they comply with all requirements laid down therein and avoid academic misconduct. Students are not permitted to use generative artificial intelligence, or other machine learning technology, in their learning on this module. Because this module is assessed by an unseen, invigilated examination, no formal citation methodology is prescribed.', 'https://www.ucd.ie/modules/LAW10440', 'law10440'),
    ('14da9b35-750d-4ef9-a9f9-67e6fe46c5a7', v_uni_id, 'LAW10470', 'Comparative Study of Law', 'Law', 'The aim of this module in Comparative Study of Law is to provide students with a general knowledge of the comparative approach for studying law. Comparative law is a unique legal subject in that it does not concern, in and of itself, any established legal products on its own, such as comparative rules or comparative jurisprudence. In that sense, comparative law may be distinguished from international law. One cannot locate any statutes or court decisions citing or referencing comparative law per se. Rather, comparative law is a field of legal study related to a methodology, or an approach, in probing and understanding other ( i.e., foreign) legal systems and/or legal cultures. The module will focus on the methodology of comparative law, in the field of comparative constitutional law in particular. Students will be provided with a syllabus and a general reading list at the start of the trimester. Students will be given specific readings and tasks to prepare for each lecture. This module will use Brightspace. This module fits within the 2030 Agenda for Sustainable Development of the UN, with SDG Number 16 on Peace, Justice and Strong Institutions in particular. Further instructions will be given in the Module Handbook which will be posted on Brightspace one week before the first due class.', 'https://www.ucd.ie/modules/LAW10470', 'law10470'),
    ('80a6f039-693d-4542-9709-2e4fe5954a49', v_uni_id, 'LAW20090', 'Company Law I', 'Law', 'This module is the first of two focusing on the law of companies in Ireland which, when taken together, cover the required syllabus for the professional bodies in the subject Company Law. This module aims to give students a basic understanding of the fundamentals of Irish Comapny law. It covers the entrire life cycle for the company from incorporation to dissolution. The syllabus of topics which may be explored in this module includes - Characteristics of companies, Types of company, Formation of companies, The consequences of incorporation, Disregard of separate legal personality, Corporate capacity, Authority of corporate agents, Corporate governance structures, Corporate membership, Directors and other officers, Meetings & resolutions, financing and reporting, mergers reconstructions and takeovers, examinerships and investigations, and the dissolution of companies. Specific topics to be covered include: Corporate finance; Share capital and loans; Allotment, transfer and transmission of shares; Debentures and charges; Receivers and receivership; The maintenance of capital; Accounts and auditors; Corporate investigations; Amalgamations and reconstructions; Examinership; Windings up. The module includes significant reference to English company law in addition to the primary focus which is on the law of Ireland, including the Companies Bill 2012.', 'https://www.ucd.ie/modules/LAW20090', 'law20090'),
    ('861abe32-35f8-400a-932c-793db0525288', v_uni_id, 'LAW20170', 'Company Law II', 'Law', 'This module is the second of two focusing on the law of companies in Ireland which, when taken together, cover the required syllabus for the professional bodies in the subject of Company Law. This module builds on learning acquired in the module Company Law I and on basic legal knowledge acquired at Stage 1. The focus is on new topics and the focus is more detailed. The syllabus of topics which may be explored in this module includes - financing and reporting; mergers, reconstructions and takeovers; examinerships and investigations; and the dissolution of companies. Specific topics which may be covered include: corporate finance; share capital and loans; allotment, transfer and transmission of shares; debentures and charges; receivers and receivership; maintenance of capital; accounts and auditors; corporate investigations; amalgamations and reconstructions; examinership and liquidation. The module includes significant reference to English company law in addition to the primary focus which is on the law of Ireland, including the Companies Act 2014.', 'https://www.ucd.ie/modules/LAW20170', 'law20170'),
    ('75f9a25e-fc38-48b8-89d2-8dfdbc60626b', v_uni_id, 'LAW20330', 'EU Constitutional Law', 'Law', 'The aim of this module is to give students a grounding in the institutional and constitutional framework of the European Union. European Union law is first put in its historical framework by considering the constitutional evolution of the European Union, including an analysis of the impact of the Treaty of Lisbon. The law relating to the institutions as this stands post-Lisbon is then analysed in some detail, beginning with the the political institutions (including analysis of the legislative process at European Union level). The institutional structure and operation of the Court of Justice of the European Union are also examined, as are the forms of litigation which come before the Court. Various sources of European Union law are looked at: including Treaty articles, secondary legislation and general principles (including fundamental rights). The great doctrines of European Union law, such as the autonomy of European Union law, supremacy, direct effect, the interpretive obligation and state liability are looked at. European Union citizenship is also examined.', 'https://www.ucd.ie/modules/LAW20330', 'law20330'),
    ('9932a75e-8047-426f-83ab-be190e82972e', v_uni_id, 'LING10010', 'Language Use and Communication', 'Languages, Cultures & Linguis', 'This module introduces students to the study of language in its social and cultural context (Sociolinguistics and Pragmatics). It examines different communication systems and how they are used and perceived. The module introduces students to various social and cultural variables and their impact on language use. It explores the following types of topics: the similarities and differences between communication systems, the factors that affected human communicative behaviour (e.g. context, gender, social group, language ideologies, interactional goals) and pertinent aspects of language use (bilingualism/multilingualims, language choice, language contact). Students are introduced to pertinent theories and practices in sociolinguistic research using a combination of different learning approaches such as lecturing, group work and in-class discussion. This module forms part of the BA programme for Linguistics.', 'https://www.ucd.ie/modules/LING10010', 'ling10010'),
    ('e2d60b1e-954b-4af2-a70f-40fb8dc2277f', v_uni_id, 'LING10020', 'Language Acquisition and Language Disruption', 'Languages, Cultures & Linguis', 'This module introduces the areas of Linguistics that focus on two related aspects of Language study: Language Acquisition and Language Disorders. The first part of the module examines both first language acquisition from birth and second language acquisition by individuals who already have a complete first language. The second part introduces the area of Linguistics that concerns itself with the study of language disorders and language impairment. The overall objective is to see how the patterns of language breakdown shed light on the way language is acquired, is used and is represented in the mind/brain of the language user. This module forms part of the BA programme for Linguistics.', 'https://www.ucd.ie/modules/LING10020', 'ling10020'),
    ('4ed681ad-f213-43aa-a55a-2803d21d5cd4', v_uni_id, 'MATH00010', 'Introduction to Mathematics', 'Mathematics & Statistics', 'This is an introductory module that is intended to help incoming students understand and master basic topics that are necessary for successful engagement with future Science, Computing and Mathematics modules. Topics include: exponents, logs, manipulating and simplifying algebraic and numeric expressions, solving equations, functions, graphs, and differentiation.', 'https://www.ucd.ie/modules/MATH00010', 'math00010'),
    ('2fc276d1-c55c-490a-be2a-84a5ce746d05', v_uni_id, 'MATH10030', 'Mathematics for Business', 'Mathematics & Statistics', 'This mathematics module has been specifically designed with the mathematical needs of the business undergraduate in mind. Mathematics plays an important role in subject areas such as Accountancy, Economics, and Finance, but skills such as the ability to problem solve, interpret and analyse information pervades all of Business. This module will focus on some of the major concepts and mathematical techniques of Calculus which the business undergraduate is likely to encounter.', 'https://www.ucd.ie/modules/MATH10030', 'math10030'),
    ('88c0e812-ae93-4bb1-8284-3ffe82912a73', v_uni_id, 'MATH10200', 'Matrix Algebra', 'Mathematics & Statistics', 'This is an introductory module in matrix algebra designed for computer science students. A course outline is as follows: Systems of linear equations (solving systems of linear equations, in/consistent solutions, solution sets), Matrix Operations (addition and multiplication of matrices, properties of matrix operations (assoc., dist. Laws etc), transpose, trace, inverse, determinant, partitioned matrices), and applications. Students may be introduced to a mathematics software system.', 'https://www.ucd.ie/modules/MATH10200', 'math10200'),
    ('029c4860-df9f-40d3-aa1e-4006cff253b1', v_uni_id, 'MATH10210', 'Foundations of Mathematics for Computer Science I', 'Mathematics & Statistics', 'This module offeres a first introduction to principles of discrete mathematics, with a presentation for students of computer science. A brief course outline can be read below. Basic Algebra: algebraic manipulations, substitutions, inequalities, summations, operations, binomial coefficients Principles of Proof: predicates and quantifiers, direct argument, contrapositive, constructive proofs, proof by contradiction, proof by induction Sets: operations and constructions on sets, properties of sets, De Morgan''s laws Functions: domain and range, injectivity, surjectivity, invertibility, floor and ceiling, max and min', 'https://www.ucd.ie/modules/MATH10210', 'math10210'),
    ('3b88bd03-4283-4b1f-b2c0-a7fb21a6c7a7', v_uni_id, 'MATH10220', 'Foundations of Mathematics for Computer Science II', 'Mathematics & Statistics', 'This module consists of topics in Discrete Mathematics that are fundamental to Computer Science. 1. Modular arithmetic. 2. Permutations: Cycles, Disjoint Cycle Representations, Order, Sign. 3. Basic Counting Principles: Pigeonhole Principle, Inclusion Exclusion, Ordered and Unordered Selections with or without Repetition, Binomial and Multinomial Theorem. 4. Advanced Counting Principles: Generating Functions, Linear Recurrencies, Counting Equivalent Colourings, Symmetry Groups and Cycle Index. (STUDENTS MUST HAVE A LAPTOP COMPUTER.)', 'https://www.ucd.ie/modules/MATH10220', 'math10220'),
    ('28fc25b7-9623-44d4-a051-f1d724c71754', v_uni_id, 'MATH10230', 'Mathematics for Agriculture I', 'Mathematics & Statistics', 'MATH10230 is an introductory module in mathematics which is designed to complement the Agricultural Science programme. Topics covered include Introduction: numbers, arithmetic, exponents, sets, functions, trigonometry Calculus: more on functions, graphs, discontinuities, secants to tangents, slope and derivative, calculating the derivative of a polynomial, exponential function, inverse functions, log function Applications: velocity, acceleration, finding a maximum, graphs, linear approximation Integration: areas under a curve, anti-derivatives, fundamental theorem of calculus Prelude to Probability: Permutations and Combinations, Sample spaces, events, probability measure, equiprobability, examples', 'https://www.ucd.ie/modules/MATH10230', 'math10230'),
    ('21c7ec71-12e1-45c4-9cc5-7c0710ab26c4', v_uni_id, 'MATH20290', 'Multivariable Calculus for Eng', 'Mathematics & Statistics', 'This module is an introduction to calculus of several variables. In addition, the study of linear ordinary differential equations is extended from first order (seen in stage 1) to higher order. The module is currently divided into nine chapters on the following topics (details below): 1. Functions of several variables; 2. Partial derivatives, chain rule, linear approximation; 3. Gradient and directional derivatives; 4. Second order partial derivatives and the Hessian matrix; 5. The Jacobian matrix, chain rule and inverse function theorem; 6. Maxima and minima, classification of critical points; 7. Constrained optimization and Lagrange multipliers; 8. Higher order linear differential equations with constant coefficients. [Disclaimer: module content and assessment strategies may be subject to minor changes during the trimester. These changes may not be reflected in this module descriptor at that time, but will be clearly communicated to all students via other means.]', 'https://www.ucd.ie/modules/MATH20290', 'math20290'),
    ('2a84f643-b106-457c-aa01-cff796493c56', v_uni_id, 'MATH20320', 'Quantitative Methods in Business', 'Mathematics & Statistics', 'This module is designed for anyone interested in pursuing more quantitative specializations such as Economics, Finance and Accounting. The aim of this module is to introduce students to a range of mathematical techniques used in these areas of specialization, together with many applications. Topics include: (1) integration, with applications such as consumer and producer surplus, and continuous revenue streams; (2) matrix algebra and linear models including Markov chains; (3) first-order difference equations and their use in certain ''lagged'' micro and macroeconomic models; and (4) an introduction to differential equations (time-allowing). The module builds on and uses techniques from MATH10030, Maths for Business, to give the student a solid foundation in the quantitative methods used in business.', 'https://www.ucd.ie/modules/MATH20320', 'math20320'),
    ('eb83e3c0-b412-41c9-b767-daad784e95e5', v_uni_id, 'MEEN40430', 'Professional Engineering (Management)', 'Mechanical & Materials Eng', 'Engineering decisions are often affected by far more than just technical considerations. As professional engineers it is essential recognise these factors, and also to recognise how our work may impact others both within and outside our organisation. This module addresses four aspects of professional engineering practice: management, applied ethics, economics, legal and regulatory aspects of engineering. Each of these practices encompasses the following indicative contents. (1) Management: management principles; environmental, social, economic, and technical interactions; influences of individual and organisational biases; analysis and decision making tools; planning and monitoring of work and projects. (2) Applied Ethics: Ethical theory and principles; professional codes; the ethical use of technology and data; managing ethical dilemmas. (3) Economics: macro and microeconomic fundamentals; ecological economics; engineering for sustainable development. (4) Legal/Regulatory: contract law; professional liability; product liability; arbitration; employment law; negligence; employment equality; safety in the workplace; safety regulations; data law.', 'https://www.ucd.ie/modules/MEEN40430', 'meen40430'),
    ('16e3d4dc-2f1f-41f8-ae0d-021bc64ad533', v_uni_id, 'MEMI30010', 'Medical Microbiology', 'Medicine', 'This module is designed to provide students with an understanding of theoretical and practical aspects of Medical Microbiology. Starting from basics, students are initially introduced to the properties (structure and replication) of medically important groups of bacteria and viruses that influence the pathogenesis of these infectious agents in humans. Following on from this, the module covers specific medically important bacteria (Weeks 1-5) and viruses (Weeks 6-12). These lectures provide insights into modes of transmission, epidemiology, pathogenic mechanisms, immune response of the host, treatment strategies, prevention/control of infection and the principles behind methods used to diagnose infection. Lectures are complemented by practical laboratory sessions consisting of approx. 18 hours in total split between Bacteriology and Virology. These sessions account for 30% of the final grade for this module and provide students with the opportunity to apply material covered in the lectures in a practical setting. Students obtain hands-on experience of methods used in the diagnosis of bacterial and viral infections in the laboratory and an understanding of how results are interpreted and their relevance in a clinical context. Assessment is as follows: End of trimester (MCQ and essay paper): 50%; Practical exams/assignments in trimester: 30%; Mid term MCQ: 20%', 'https://www.ucd.ie/modules/MEMI30010', 'memi30010'),
    ('d7815c5e-8279-4487-add7-5b4a3ce5e4aa', v_uni_id, 'MICR20010', 'Agricultural Microbiology', 'Biomolecular & Biomed Science', 'In this course you will be introduced to microbiological concepts relevant to agricultural, environmental and food applications. Examples will relate microbiological theory to the production & spoilage of foods & fodders, water quality, microbiological regulation of nutrient cycles, animal and plant health, and biotechnology. You will be introduced to common microorganisms and will consider growth, classification, genetics, survival and control by sterilization, disinfection, immunization and antibiotics. As part of the theoretical and practical aspects of the course you will gain experience with microbiological laboratory methodologies such as microscopy, sterile technique & the isolation and identification of pure cultures.', 'https://www.ucd.ie/modules/MICR20010', 'micr20010'),
    ('700ee3e2-9fd5-4313-855a-d37f08b1ad2d', v_uni_id, 'MIS10040', 'Web Design and Analytics', 'Business', 'This module is designed to familiarise students with key concepts central to web design and web analytics and it also provides a guide to implementing a successful web site and web analytics strategy. The module involves both conceptual and practical aspects, including coding in HTML5 and CSS. Topics include: web design; web development; web usability and user experience; designing for mobile, web analytics; goal setting strategies; metrics and measurement; search engine optimization and leveraging the Social Web.', 'https://www.ucd.ie/modules/MIS10040', 'mis10040'),
    ('6f362ceb-36ac-45f7-baf5-ffbda3550ca1', v_uni_id, 'MIS10050', 'Digital Technologies in Business', 'Business', 'Digital Technologies, applications, and initiatives have become an integral part of all business activities. Throughout this applied, hands-on module, students will gain insights into both the opportunities and challenges posed by conducting business in an increasingly digital domain. MIS10050 provides students with essential Artificial Intelligence (AI) literacy, practical AI prompt engineering skills, and the ability to evaluate AI outputs critically. Students will explore how AI and Generative AI (GenAI) are transforming industries, enhance business problem-solving using structured AI workflows, and learn responsible and ethical AI usage in both academic and organisational settings. Throughout the trimester, students will - Research how innovative digital technologies have transformed a real organisation. - Design a mobile application prototype for an organisation (no programming/coding skills required) - Become familiar with using industry-standard AI tools both efficiently and ethically.', 'https://www.ucd.ie/modules/MIS10050', 'mis10050'),
    ('9e960d29-d42c-4586-ab5a-1eb77628c833', v_uni_id, 'MIS10090', 'Data Analysis for Decision Makers', 'Business', 'In the era of Analytics, there is a challenge to turn data into insight. Data Analysis is the application of statistical techniques to describe and explore a set of data with the objective of highlighting useful information. Data Analysis is used to support evidence-based decision making and so is a core part of Business Analytics. This module is a foundation in data analysis for all business students and aims to serve the needs of subsequent courses in areas such as marketing, finance, accounting and business analytics. The three main areas introduced in this course are: 1. Quantitative Analysis and Descriptive Statistics: how to gather and interpret large volumes of data in order to describe the information in concise and useful ways. Practical exercises will use a spreadsheet tool such as Excel. 2. Probability and Distributions: discrete and continuous with examples from the real world 3. Inferential Statistics: how to infer population parameters from sample statistics. For example, estimate the average of a population, giving a confidence interval (margin of error). This module is delivered using blended learning. Learning resources, including quizzes, are available on Brightspace and students engage in active learning exercises during face-to-face contact time.', 'https://www.ucd.ie/modules/MIS10090', 'mis10090'),
    ('bd8c8016-8919-477f-9ba9-3744e3381bed', v_uni_id, 'MIS20010', 'Business Analytics', 'Business', 'Business Analytics focuses on the use of mathematical, statistical, data-oriented and computer-based techniques to help businesses operate optimally. It seeks to understand what has happened and predicting what is going to happen, and making optimal decisions to take advantage of that. The main techniques we consider are Correlation, Regression, Time-Series Forecasting, Linear Programming, Classification, and Clustering. For each technique, we learn how it works on paper before proceeding to software-based implementations. We also consider practical applications of these techniques, including sales forecasting, credit risk, resource allocation, employee assignment, investment, customer churn, inventory, and product mix. Emphasis is placed not only on formulating and using models to obtain solutions, but on understanding case study problems, choosing the appropriate models, and interpreting and critiquing the results. This module is unique in the sense that it not only offers a strong understanding of how to use data to drive decision making in the business world, but also that many of the quantitative techniques that are taught are foundations for advanced Machine Learning and Artificial Intelligence, which are at the core of Business decision-making nowadays.', 'https://www.ucd.ie/modules/MIS20010', 'mis20010'),
    ('3e4255cc-add3-4dc0-af3a-0784dbed38f0', v_uni_id, 'MIS20040', 'Digital Business and Social Media Strategy', 'Business', 'Digital Business is rapidly evolving into a central resource for pursuing business objectives and strategies. As a result, the role of digital business, social media, and emerging, rapidly evolving artificial intelligence tools in business needs to be reevaluated to develop a sophisticated understanding of how these tools and initiatives may help organisations obtain and sustain competitive advantage in the local and/or global marketplace. This applied module incorporates a generic Digital Business Strategy Framework published by Harvard Business Publishing (Davin & Gupta, 2015 & 2019). It evaluates and discusses the components of a comprehensive Digital Business strategy and investigates its impact on different industry sectors. Students are required to draft a digital business strategy for an organisation as part of a major group project. Additionally, module participants will complete a Harvard Business Impact certification course (Leading with Generative AI), requiring them to purchase a single-user license valued at approximately EUR10.', 'https://www.ucd.ie/modules/MIS20040', 'mis20040'),
    ('a72ca4bb-6b81-4aa3-9b34-937a2ec0cba3', v_uni_id, 'MIS20060', 'Inside the Modern Crypto Industry', 'Business', 'The Crypto industry is now fifteen years old. Its history has been tumultuous, but it has shown its staying power. But how did it come to its current point and what preoccupies the attention of modern Crypto entrepreneurs, companies and protocols? In this module, we take a pragmatic approach to succeeding in the Crypto industry as a business student. We’ll start with foundational knowledge about the technical underpinnings of blockchains, focusing our attention on Ethereum. We’ll then turn to popular Decentralized Finance (DeFi) applications, Decentralized Autonomous Organizations (DAOs), Ethereum’s main competitor Solana, Ethereum Layer 2s and then finally Cypherpunk values. The module features talks and panels from experts working in the local Crypto industry, who will tell you about how they made it and what their day-to-day life is like. Throughout the module, students work on a hackathon concept that they could apply in the local Dublin scene and beyond. No coding is required for the hackathon concept.', 'https://www.ucd.ie/modules/MIS20060', 'mis20060'),
    ('f922cb7b-3bf4-4e88-aa66-e72a30ceb495', v_uni_id, 'MIS20070', 'Digital Society', 'Business', 'This module examines power, policy, and regulation in the digital era. We examine how Big Tech cascades its data power across lines of business to spread monopoly; whether Europe is caught in an East-West pincer; and a tragic irony that the information technology revolution may be decreasing the quality of information in society. We will discuss regulatory tools to counter Big Tech’s concentrated power, and the challenges posed by cybercrime and the Crypto industry. Finally, we will debate the future of AI, including Artificial General Intelligence (AGI), alongside emerging ideological currents from Silicon Valley such as network states and accelerationism. Combining technology, law, economy, politics and philosophy, this module is intended to equip students to think beyond the latest hype cycle and consider the societal implications of digital change. The module group project asks students to work together to imagine and describe a future digital society.', 'https://www.ucd.ie/modules/MIS20070', 'mis20070'),
    ('775a9df5-39c6-40b8-b89b-42c8f6443fa7', v_uni_id, 'MIS20090', 'Design Thinking', 'Business', 'Design Thinking for Digital Projects equips you to act as an effective problem finder, solver and designer of human-centred solutions. You will acquire practical experience in user facilitation, requirements gathering, and collaborative design idea generation for human-centred design initiatives. Coursework is built around practical field studies of people encountering challenges and everyday problems. These learning experiences will prepare you contribute to the requirements, analysis and design stages of digital projects. This class is relevant to a career path in product management.', 'https://www.ucd.ie/modules/MIS20090', 'mis20090'),
    ('8937d649-2b1e-449c-95ee-e7d26555f81d', v_uni_id, 'MIS30010', 'Decision Analytics', 'Business', 'Much of business decision-making has a common base, for example dealing with risk or identifying optimal levels of service to provide. Decision Analytics helps to develop an appreciation of these common structures. This becomes most helpful later in one''s career as one moves into general management when it becomes important to have an ability to get a quick understanding of the dynamics of many different and apparently unstructured situations. The emphasis is on developing practical experience in solving business analytics problems by means of real decisions. We include techniques such as Expected Value of Perfect information, Markov Processes and Multi-Criteria Decision Making. The course also includes elements of “Behavioural Decision Making” which is an academic discipline which seeks to apply the insights of psychologists to our decision making. The course readings provide many examples of how decision making is not always driven by “rational” consideration but by aspects of personal and market psychology. This module will provide us with the ground work to recognise our biases and errors of judgements, and make better decisions in the future.', 'https://www.ucd.ie/modules/MIS30010', 'mis30010'),
    ('cfc6c718-490a-4459-9eee-27e2fb86250d', v_uni_id, 'MIS30150', 'Strategic Decision Making in the Digital World', 'Business', 'In a business environment increasingly shaped by Artificial Intelligence (AI), big data and rapidly changing markets, managers have access to more information and analytical capabilities than ever before. Yet simply accessing data and using AI does not automatically lead to better business decisions. The ability to analyse information, exercise judgement, challenge assumptions and make well-informed strategic decisions under conditions of uncertainty is becoming an increasingly important managerial capability. This applied, project-based module develops these capabilities through two key pillars: Bloomberg Global Trading Challenge As part of the annual Bloomberg Global Trading Challenge, students work in teams and use Bloomberg Terminal data and analytics to define market assumptions, develop an investment strategy and make trading decisions in a competitive global environment. Through this experience, students apply data-driven analysis and strategic judgement to real-world market conditions and evaluate the outcomes of their decisions. Artificial Intelligence for Strategic Decision Making Students explore how AI tools can support strategic decision-making, solve business challenges and identify emerging business opportunities. Particular emphasis is placed on using AI critically and responsibly, recognising both its potential and its limitations as a decision-support tool. As part of this module section, students will also complete the Harvard Business Publishing “Leading with Generative AI” online certification course, which, on successful completion, will be a great addition to both your LinkedIn profile and CV.', 'https://www.ucd.ie/modules/MIS30150', 'mis30150'),
    ('dc37b477-2cf5-4a64-8e1c-091f23a44218', v_uni_id, 'MKT20020', 'Marketing: Firms, Customers & Society', 'Business', 'The primary objective of this course is to introduce students to the key concepts, analytical tools, and activities that comprise marketing management. Students will also be provided practice in assessing and solving important marketing problems. This course is a foundation for advanced courses in marketing, which is designed to help students equip themselves with strong theoretical and practical foundations. People often think about marketing as advertising – a highly visible activity by which organizations try to persuade customers to buy products and services. Marketing, however, is much more than advertising alone; advertising itself cannot single-handedly make customers buy things that they don’t want. Rather, marketing involves a wide range of activities that can be broadly categorized into two: (1) having a comprehensive understanding of the market and (2) developing a marketing strategy as a value creation process. With this in mind, I have organized the course into two modules. The first module covers the principles of marketing which are the bases for marketing strategies, such as identification of market needs and problems. The second module will focus on specific marketing practices and tactics as vehicles of value creation. These marketing decisions comprise the marketing mix, which should be designed based on a rigorous analysis of market situations. “What is marketing and how are marketing problems analyzed?” * The definition and scope of marketing * Marketing as a value-creation process * A wide range of analytical frameworks * The objective, process, and importance of marketing research * Consumer behavior and decision making process based on the latest findings from consumer psychology Module 2: Strategic Marketing Management “How are marketing strategies developed and implemented?” * Segmentation, Targeting, and Positioning: How to assess market potential and choose the right positioning * Branding: How to develop, measure, and capitalize on brand equity * Product: How to develop products that maximize customer lifetime value * Pricing: How to set prices that capitalize on value to customer and capture value for the firm * Distribution: Marketing across geographic boundaries The entire business sector is at a phase in the adoption cycle of Artificial Intelligence (AI). It is crucial to understand how AI can reshape consumer behavior and marketing operations so that students are ready for the new world with AI. Our understanding of AI, however, is limited despite lots of research in progress. Therefore, a significant proportion of class hours will be allocated on the role of AI in marketing based on the most recent academic research findings and reliable industry reports.', 'https://www.ucd.ie/modules/MKT20020', 'mkt20020'),
    ('1262789d-e63a-4d25-9877-cb941618c063', v_uni_id, 'MKT29030', 'AI-powered marketing: concepts, tools and applications.', 'Business', 'This module introduces students to core concepts, tools and applications of artificial intelligence in marketing and business contexts. It provides a broad and accessible overview of how AI-enabled tools may support marketing-related thinking, analysis and practice, while encouraging students to consider their limitations, risks and responsible use. The module will be delivered through lectures, combining conceptual discussion, live demonstrations and applications of AI tools in marketing and business contexts.', 'https://www.ucd.ie/modules/MKT29030', 'mkt29030'),
    ('1eb3962d-e270-4d01-8109-445d5eeee587', v_uni_id, 'MKT30040', 'Consumer Psychology', 'Business', 'Why do people buy things they don’t need? Why do peers influence what people like and do? How can people be persuaded to buy a product? Consumers are the most essential stakeholder of any company, yet marketing professionals often lack the foundational understanding of consumer psychology and its crucial impact on the marketplace. In this course you discover the psychological underpinnings of consumers’ decisions making processes and how consumer insights can be applied to marketing practice. Interest in psychology in addition to marketing is important for students to succeed in this module.', 'https://www.ucd.ie/modules/MKT30040', 'mkt30040'),
    ('e2b72749-9f63-4cee-976e-12538c4e471b', v_uni_id, 'MKT30050', 'Consumer Insight: Research and Data Planning', 'Business', 'Market research provides management with the information needed to identify and solve marketing problems. The overall objective of the course is to provide students with a fundamental understanding of the field of market research. This course is designed to introduce students to the central concepts of market research, the methods of conducting market research and how to use research to solve the problems faced by marketing and business managers. The course looks at each stage of the research process from problem definition, to research design, collecting data, data analysis and reporting results. As part of this module students will be required to undertake a research project from start to finish. This module is relevant for those considering a career in marketing or general management, and essential for students interested in pursuing a career in consumer insight.', 'https://www.ucd.ie/modules/MKT30050', 'mkt30050'),
    ('acaf88c2-799e-4e68-b68e-6e50c7a44bfc', v_uni_id, 'MKT30060', 'Building Effective Marketing Plans', 'Business', 'This module aims to give the enrolled bachelor students an introduction to key marketing principles and concepts to enable them to create efficient marketing plans for their future organizations or personal endeavors. Over the course of the module, students will learn about various aspects of marketing that are necessary for ideating and executing important strategies in the marketplace. Students will learn about the marketing driven approach, which builds on understanding one’s environment and one’s customers efficiently to create and communicate value for customers, in a manner that maximizes positive outcomes for not just the customers, but also for the company (profits) and society in general. This module will give the students an overview of theory and practice of marketing with a strategic perspective, so that students can confidently build effective marketing plans by the conclusion of this module.', 'https://www.ucd.ie/modules/MKT30060', 'mkt30060'),
    ('9305ca46-8b85-49f2-af87-22c92fb1d627', v_uni_id, 'MKT30080', 'Global Marketing', 'Business', 'The course introduces participants to the various aspects of global marketing. The module’s overarching objective is to develop participants’ skills in the identification, analysis and solving of problems encountered in international marketing operations. Increasingly, international markets are becoming both homogenous (thanks to technology), and heterogeneous due to multifaceted environmental and socio-economic factors across the globe. International marketers are therefore faced with complex marketing challenges and opportunities. These issues demand a deeper and broader understanding of the environmental, competition- and company-specific dimensions, in order to promote the creation of value for various stakeholders and communities by companies.', 'https://www.ucd.ie/modules/MKT30080', 'mkt30080'),
    ('86732fde-40b8-4413-8281-68c7e2fbf173', v_uni_id, 'MKT30090', 'Marketing Communications: Content and Campaigns in the Digital Age', 'Business', 'Marketing managers require useful frameworks to effectively communicate and advertise their products and services. This course discusses all aspects involved in designing effective marketing communications campaigns. The purpose of the course is to get introduced to the major topics in marketing communications and to further develop your communication skills through team-based work and presentations. The goal of this course is to help you to set marketing communications objectives for a variety of products/services; to help you understand and apply the principles that are necessary for persuasive advertising, from strategic principles (information, influence, emotion, and mere exposure) to more specific tactics (resistance, acceptance, message, attention); to help you generate, select, and evaluate creative ideas for an advertising campaign; to help you to select appropriate media (still/motion) for a marketing communications campaign, taking into account strategic and tactical rules for implementation of the media plan; and to help you propose/design an advertising campaign and discuss, present, and defend the proposed campaign.', 'https://www.ucd.ie/modules/MKT30090', 'mkt30090'),
    ('bf0d1233-0805-4e47-bc92-65f75b0454c4', v_uni_id, 'MKT30120', 'Digital Marketing', 'Business', 'This module provides a comprehensive overview of the fundamentals of digital marketing. The focus of the course examines how businesses can use the Internet and other digital media technologies to support their marketing goals. The module introduces participants to digital marketing principles, strategy development and digital marketing implementation and practice including social media marketing techniques.', 'https://www.ucd.ie/modules/MKT30120', 'mkt30120'),
    ('aea26db4-9448-4cb7-90ee-d7559ffc62e1', v_uni_id, 'MKT30140', 'Consultative Selling and Negotiations', 'Business', 'Delivered primarily on site in the classroom (Covid guidelines permitting). With the possibility of a few online sessions. Regardless of the mode of delivery, attendance and interaction during the live (online or in-class) sessions will be expected and will form part of the continuous assessment. The success of this module and the learning environment depends on a high level of interaction by all. For any questions please don''t hesitate to contact aisling.roche@ucd.ie This module is designed to provide a knowledge and understanding of the role of negotiations and sales in the marketing environment. It includes the importance of understanding communication styles as well as what influences decision making. This understanding supports the development of a relationship strategy to created customer value in an ethical context. Through interactive, experiential learning in both group and individual situations, the module will also provide the student with the opportunity to analyse their own personal communication style, and equip them with tools to improve their own communication sales and negotiation approaches. The development and role of personal selling in the marketing concept will be developed. Topics covered include The Science Of Selling Communication styles, Selling The Way Buyers Buy, Emotional Intelligence In Sales, Neuromarketing, Buying Motives, Questioning and Virtual Negotiations.', 'https://www.ucd.ie/modules/MKT30140', 'mkt30140'),
    ('b89411f8-3b70-4bab-9df1-b3513b9f1619', v_uni_id, 'MKT30150', 'Responsible Marketing', 'Business', 'We live in a time where practising marketing sustainably and ethically is vital, but also in a time when such actions are caught up in current geopolitics and the culture wars that have arisen as a result. In these times of uncertainty and polycrisis, it is more incumbent than ever on a business school to equip its graduates with the knowledge to engage in responsible marketing. This module considers the nature of the relationship between marketing and society. Responsible Marketing combines theoretical reflection and practical discussion on critical ethical issues relating to marketing''s role and relationship with society. Students will gain a critical understanding of marketers'' responsibilities and their impact on society by exploring various prevailing problems and criticisms facing marketing. The module will equip students with theoretical and practical skills that will encourage them to identify these criticisms and the drive and ability to seek solutions to the ethical and sustainable issues they will face as marketers. The module will build on the core ethical issues debated and discussed in the Business in Society module (Year 1) and develop these to explore the ethical dimensions of marketing, thus also building on the Marketing: Firms, Customers and Society module. Specifically, the module will explore contemporary ethical issues within marketing. Marketing is a crucial business activity, but due to its practices, it also faces considerable criticism. Understanding and appreciating ethical marketing issues is an essential facet of marketing. This Responsible Marketing module discusses some of the key criticisms levelled at marketing and the ethical issues marketers confront in their marketing endeavours, such as developing products, segmenting markets, advertising, and pricing. We will also consider ethical issues concerning the consumer, such as materialism and unsustainable consumption patterns, advertising to young and vulnerable consumers, promoting harmful products, and the challenges posed by new media outlets and online issues. This module will encourage students to navigate the challenges and pitfalls present in a variety of activities.', 'https://www.ucd.ie/modules/MKT30150', 'mkt30150'),
    ('9c87d22c-80f8-43f0-a03b-dc3cd16ff7d4', v_uni_id, 'MKT30170', 'Brand Management', 'Business', 'This course is designed to help you develop a practical understanding of the tools, rules, and strategies of brand management. Firms realize that the brand names associated with their products or services are the most valuable assets they have. Despite this realization, the task of how to manage a brand is difficult. Much of this difficulty stems from our inability to identify and accurately assess the value of brands (i.e., brand equity). In other words, if you cannot measure the value of your brand, how can you determine if your marketing plans were successful or not? Given these types of difficulties, I start with the position that the focus should be on consumer knowledge (i.e., how consumers perceive your brand) because this is where brand equity resides. If we have frameworks and tools that can measure what consumers think of a brand, we can get an estimate of brand equity. Then, we can examine how managerial decisions are likely to shape and contribute to brand equity. With this in mind, I have organized the course into two modules. Module 1: Understanding and Measuring Brand Equity “What do brands mean to consumers?” * Understand and apply the concept of brand equity * Assess how consumers perceive brands * Determine how you can change these perceptions to achieve brand positioning by applying some of the latest findings from consumer psychology Module 2: Strategic Brand Equity Management “How does branding go wrong?” * Evaluate how marketing decisions that are made to improve brand performance can advance brand equity or inadvertently lead to an erosion of brand equity * Apply these principles and conduct a brand audit that not only measures brand perceptions of a brand but also identifies current marketing decisions that are leading to an erosion of brand equity', 'https://www.ucd.ie/modules/MKT30170', 'mkt30170'),
    ('82a8caa9-cbc5-4786-a5f7-5d22f41837e1', v_uni_id, 'MST10010', 'Calculus I', 'Mathematics & Statistics', 'This is an introductory module in Calculus where the basic concepts of function, limit, continuity and derivative are introduced and discussed. There are two main areas of emphasis throughout the course: firstly basic skills in Calculus such as finding limits, differentiating and graph sketching; and secondly the development of a thorough understanding of the basic concepts such as function, limit, continuity and differentiability.', 'https://www.ucd.ie/modules/MST10010', 'mst10010'),
    ('0cc6429b-f55d-4f95-a60b-0359cf0d43e0', v_uni_id, 'MST10030', 'Linear Algebra I', 'Mathematics & Statistics', 'In this module we introduce and develop some of the basic ideas in Linear Algebra. A sample of topics covered are: systems of linear equations; elementary row operations and Gaussian elimination; matrices; determinants; inverses of matrices; vectors in 2- and 3-dimensional space; dot product, vector product and scalar triple product; triangle inequality, Cauchy-Schwarz inequality; orthogonal projection; lines and planes in 3-dimensional space.', 'https://www.ucd.ie/modules/MST10030', 'mst10030'),
    ('fcc31436-1b53-40ac-8fa3-dfb8fff25f24', v_uni_id, 'MST20050', 'Linear Algebra II', 'Mathematics & Statistics', 'This module gives an introduction to the theory of (finite-dimensional) vector spaces over fields and linear transformations (i.e., the functions between vector spaces that preserve the vector space structure). The module relies on the theory of systems of linear equations and matrix algebra, developed in first year. The main topics are as follows: brief revision of Gaussian elimination and Gauss-Jordan elimination, vector spaces over a field, subspaces, spanning sets, linear independence, bases, dimension, coordinate spaces, matrix techniques, row space, column space, null space, rank and nullity of a matrix, eigenvalues, eigenvectors, diagonalization, revision of functions on sets and their properties, linear transformations, kernel and image, isomorphisms, matrix of a linear transformation, vector space of linear transformations, change of bases for matrices of linear transformations, rank and nullity of a linear transformation, quotient spaces, dimension formula, first isomorphism theorem, rank-nullity theorem. [Disclaimer: module content and assessment strategies may be subject to minor changes during the trimester. These changes may not be reflected in this module descriptor at that time, but will be clearly communicated to all students via other means.]', 'https://www.ucd.ie/modules/MST20050', 'mst20050'),
    ('9c3dad46-26ff-4361-9c75-df9885030f50', v_uni_id, 'NMHS10100', 'Health across the Lifespan', 'Nursing,Midwifery & Health Sys', 'The module aims to introduce students to the concept of health across the lifespan, the various ways in which health is understood and promoted. It examines aspects of the health of individuals and populations from birth to old age, with particular reference to health in Ireland, and discusses a range of factors that influence the health and well-being including psychological, social and cultural factors, and political and economic factors. Milestones and transitional periods in the lifespan such as birth, adolescence, middle and old age, are examined in detail. This module also provides a brief overview of the ways in which the health of individuals and populations are assessed and measured, with reference to health statistics, demographic data and social research. This module also looks at various factors that affect the health of individuals such as alcohol and drug abuse, smoking, sudden adult death syndrome, mental health and depression, eating disorders, cancer, and diabetes.', 'https://www.ucd.ie/modules/NMHS10100', 'nmhs10100'),
    ('11d8a514-5466-489d-85f6-f69695773beb', v_uni_id, 'PERS10020', 'Fundamentals of S & C Online', 'Public Hlth, Phys & Sports Sci', 'Pass/Fail (GPA Neutral) The aim of this module is to provide students with an introduction to strength and conditioning and its application to athletic populations. This module will present students with the most up to date physiological and biomechanical data regarding the central tenets of strength and conditioning applications and delivery. This module will be exclusively delivered online through a combination of pre-recorded and/or live-lectures and online video tutorial/content. Each topic will be presented as a separate work package. Each work package will be allocated different specific goals. These goals will be achieved through self-directed learning and through interaction with the course material provided via Brightspace.', 'https://www.ucd.ie/modules/PERS10020', 'pers10020'),
    ('7bb47e65-09ea-471a-8585-83905c7f8044', v_uni_id, 'PERS10060', 'Introduction to Exercise Science', 'Public Hlth, Phys & Sports Sci', 'The aim of this module is to develop an introductory knowledge base in exercise physiology. A systems approach is used concentrating on the responses of the metabolic, cardiovascular, respiratory, neurological, hormonal, thermoregulatory and muscular systems to exercise. Specifically, completion of this module will enable the student to understand how acute and chronic bouts of exercise alters the structure and function of the human body.', 'https://www.ucd.ie/modules/PERS10060', 'pers10060'),
    ('74b0dc88-ac50-4859-93f1-c8b87506943f', v_uni_id, 'PERS20020', 'Introduction to Nutrition for Health and Exercise', 'Public Hlth, Phys & Sports Sci', 'This unit introduces students to the fundamentals of evidenced-based nutrition. The basic principles of healthy eating are covered with a focus on energy, macronutrients, and micronutrients. Health risks linked to body composition, nutrient deficiencies and dietary habits will be explored. Approaches to assessing the food and nutrient intake of individuals, and the role of nutrition for exercise is introduced.', 'https://www.ucd.ie/modules/PERS20020', 'pers20020'),
    ('0ca8925a-24ba-4a53-9c1b-0fecc9eb4cb4', v_uni_id, 'PERS20030', 'Sort your life out and thrive', 'Public Hlth, Phys & Sports Sci', '‘Sort your life out and thrive’ is a module that focuses on your wellbeing, personal growth and coping with stress, so that you can equip yourself with lifelong skills for learning, working and being well. You will spend 10 weeks developing yourself to thrive in university life and beyond - including leadership skills for future employment - through fostering physical, cognitive, emotional and social skills that will support your wellbeing. Your assignments will provide you with the opportunity to focus on yourself, working towards your personal goals that you will identify as part of the module, while also practicing self-care and self-compassion. The module will be delivered in the context of our digital world: understanding your data and finding digital supports and strategies for life management. Expert speakers will join us for sessions around areas such as nutrition, sleep and mental health and you will have the opportunity to track your own personal data and progress in areas of your choice (e.g. emotional wellbeing, study habits, time management, exercise). The weekly in-person classes will be conversational in tone, where you will undertake a variety of activities that will enhance your personal development. You will prepare for class each week by watching pre-recorded material. You will reflect on how your values and goals map onto the way you are currently living your life and you will be facilitated in exploring how you wish to reach your potential. There are no prerequisites for this module. Students who are interested and ready to develop their self-knowledge and wellbeing skills will be most suited. It is recommended to consider your preparedness for tasks that involve self-reflection before registering for this module. If you are unsure, please email the module coordinator: jessica.surdey@ucd.ie', 'https://www.ucd.ie/modules/PERS20030', 'pers20030'),
    ('02e4f684-f994-44a9-9b90-414b7ffbc024', v_uni_id, 'PERS30010', 'Appl Nutr Health Ex & Sp Perf', 'Public Hlth, Phys & Sports Sci', 'After natural talent and appropriate training, nutrition is the next most important factor influencing sports performance. On the other hand, health risks linked to body composition, nutrient deficiencies and dietary habits are readily altered by manipulation of nutrient intake in the short- and long-term. This module builds upon existing modules in the sports and exercise sciences, and in particular the theoretical framework given in PERS20020, by exploring practical nutrition strategies in health and sporting contexts. Greater focus will be given to practical applications of current nutrition guidelines including meal planning and provision, food choices, and both broad and goal-orientated dietary strategies.', 'https://www.ucd.ie/modules/PERS30010', 'pers30010'),
    ('6d717831-67f7-4c3e-834b-10d5f77a2b54', v_uni_id, 'PERS30070', 'Skill Acquisition', 'Public Hlth, Phys & Sports Sci', 'The purpose of this module is to understand the principles underlying skill acquisition. Specifically, students will learn the stages of motor learning, the cognitive processes supporting skill acquisition, how motor skills are acquired, how learning can be enhanced and why skills attempts might fail. Each class will comprise of theoretical and practical components designed to encourage student interaction, curiosity and discussion. Most often examples from sport will be used to clarify these, however it is important to keep in mind that the principles and concepts introduced in class apply to any situation in which movement is the primary means of achieving a particular goal (e.g. leisure activities, activities of daily living, rehabilitation, & sport).', 'https://www.ucd.ie/modules/PERS30070', 'pers30070'),
    ('599e6287-1eee-454f-9772-fcaae8c22e7a', v_uni_id, 'PHIL10020', 'Mind, Language and Meaning', 'Philosophy', 'What is the nature of mental phenomena like thought, perception, and conscious experience? Do animals or computers have thoughts like we do? Could they be conscious or have beliefs and desires? How does consciousness relate to the physical world and the brain? In this module we address various philosophical puzzles concerning thought and experience, introducing students to classical and contemporary philosophical views of the mind, thought, language, and meaning. Note: If you are taking this module as an elective you may be interested in pursuing a Structured Elective programme in Philosophy (this will entail taking two more Philosophy electives). Your University Transcript could show that you have a Structured Elective in either Existential Philosophy & Critical Theory or Philosophy of Mind & Science depending on which other electives you choose. See https://www.ucd.ie/students/registration/structuredelectives/ for details.', 'https://www.ucd.ie/modules/PHIL10020', 'phil10020'),
    ('52a5d330-5a3b-490e-a714-9743db856b27', v_uni_id, 'PHIL10030', 'Introduction to Modern Philosophy', 'Philosophy', 'Can I be certain that there is a world outside me, or am I confined to my own mind alone? What can I know reliably about the world, if there is one? And if it exists knowably, how can I live with other people within it? Are we naturally selfish and dangerous? Or do we have a compassionate and gentle nature brutalised by a corrupt society? These are some of the questions to be discussed in this introduction to early modern philosophy of knowledge and social and political philosophy. The way of approaching the questions will be through a critical and historical treatment of selected writings by Descartes (1596-1650), Hobbes (1588-1679) and Rousseau (1712-1778).', 'https://www.ucd.ie/modules/PHIL10030', 'phil10030'),
    ('59a83bec-e930-4195-9aa1-48ac4223a2d2', v_uni_id, 'PHIL10040', 'Introduction to Ethics', 'Philosophy', 'Ethics—sometimes called Moral Philosophy—is the part of philosophy that asks some of the most important and difficult questions about about human life: How ought we to live? How should we treat one another? What makes an action right or wrong? What do we owe to other people, and what do we owe to ourselves? These aren’t just theoretical questions, because we encounter them constantly in our everyday lives, often without realising that we are doing ethics. Should we tell the truth when doing so might hurt someone? Is it ever acceptable to break a rule for a good reason? What do we owe to people who are less fortunate than ourselves? Do our friends and family deserve more consideration than strangers? Is it morally wrong to eat meat? How should we respond to injustice? Do we have obligations to future generations? And how should we think about difficult new questions raised by technology, artificial intelligence, climate change, medicine, and social media? The first part of the module introduces students to some of the major ethical concepts, theories and arguments that have shaped the history of moral philosophy. We will consider different answers to questions about where moral values come from, whether moral values are absolute or relative, what makes an action morally right, and whether morality is grounded in consequences, duties, character, or reason. The second part of the module broadens this perspective by asking us to consider the social, political, and historical conditions within which our lives and choices take place. We are not simply autonomous individuals who freely choose the circumstances in which we live. Our lives are shaped by social structures and relationships, and by histories that we did not choose. In this sense, human beings are not only agents; we are also, in important ways, thrown into particular social, political, and historical conditions. This raises a further set of ethical questions: How much freedom do we really have? How do social structures shape our opportunities and responsibilities? And what kinds of societies are necessary for human beings to live good and flourishing lives? This shift from the individual and their choices towards the structural dimensions of human life brings ethical reflection into dialogue with questions of justice and the kind of society that can make the good life possible. We will explore these questions through themes including gender and care work, racism and racial justice, and knowledge and extractivism. In doing so, the module examines how apparently personal and individual ethical questions can be connected to wider structures of power, inequality, knowledge, and social organisation. The aim of the module is not to provide students with a set of definitive answers, but to develop their ability to think carefully about difficult questions, evaluate arguments, identify assumptions, and give reasons for their own moral judgements. Students will be encouraged to question ideas that may initially seem obvious or commonsense, to challenge traditional views, to engage seriously with perspectives different from their own, and to appreciate the connections between individual ethical life and the social conditions in which that life is lived. By bringing together questions about how we ought to live, how we ought to treat one another, and what kind of society makes a good life possible, the module offers a broad and holistic introduction to ethics. It aims to show not only why ethics remains philosophically fascinating, but also why it remains necessary and valuable in understanding the contemporary world. This module is taught in both the autumn and the spring trimesters, and students are welcome in either. The teaching staff and the content will differ slightly, but the assessment will be the same.', 'https://www.ucd.ie/modules/PHIL10040', 'phil10040'),
    ('5bb84a2b-4a54-4267-8af7-9da064ea9153', v_uni_id, 'PHIL10100', 'Existentialism and Humanism: An Introduction to Continental Philosophy', 'Philosophy', 'What makes us ''human''? Is our humanity something we ''do'' or something we ''are''? Can we be more or less human? How do we give meaning to our human existence or is that existence ultimately meaningless? Are we now post-human? What is humanism and how has it affected our political and social structures? How do we treat others and how should we treat them? Are we ever really free? In this module we examine approaches to these and related questions from the European philosophical tradition. Thinkers we will read include: Schopenhauer, Nietzsche, Kierkegaard, Marx, Beauvoir, Sartre, Fanon, Foucault and Braidotti. Our main themes will be: rationality, freedom, responsibility. Further details will be posted on Brightspace.', 'https://www.ucd.ie/modules/PHIL10100', 'phil10100'),
    ('8596d515-30f6-4829-937d-eb7e6abbbc19', v_uni_id, 'PHIL10160', 'Critical Thinking', 'Philosophy', 'NOTE: AI was not used in any way in the composition of this module outline. In his 2005 book *On Bullshit*, the philosopher Harry Frankfurt (1929-2023) wrote that: "One of the most salient features of our culture is that there is so much bullshit. Everyone knows this. Each of us contributes their share. But we tend to take the situation for granted.” Frankfurt defines ''bullshit'' as content that is presented to us without any regard for the truth, but for some other reason: for example, to persuade us of something or just to get our attention. Given that definition, Frankfurt''s comment applies even more to our world today much more than it did in 2005. In fact, with the advent of generative AI and LLMs, we live in an era in which the total quantity of bullshit in our cognitive environment is constantly increasing. So, it''s more important than ever to be able to distinguish the true from the false, the rational from the irrational, and the logical from the illogical. And that requires the ability to reason well. Even as generative AI systems like ChatGPT and Claude grow increasingly capable of reasoning, the ability to think independently remains essential to human dignity, freedom, and moral responsibility. Intellectual autonomy—the ability to think for oneself—is what allows us to question authority, challenge assumptions and norms, and make sense of our lives beyond what is suggested or computed for us. Without the ability to reason for ourselves, we risk becoming passive recipients of content rather than active participants in shaping our world. Generative AI can support our thinking but it can''t replace our uniquely human capacity to reflect, doubt, and choose in ways that are bound up with conscience, creativity, and our own lived experiences. But reasoning, and especially reasoning well, is not easy. The aim of this course is to help you to learn to reason better, and therefore to make better decisions, by learning three main things: 1. Why our natural psychological biases make it hard for us to reason well, and what we can do to mitigate those biases; 2. What reasoning well actually consists of; in other words, what it means to be sensitive to the evidential and logical relations between different claims; and 3. How to extract and analyse arguments from what people or AIs write or say, in order to assess whether we should accept their conclusions and recommendations. To be a little more specific, in the module we''ll learn about cognitive biases and how to mitigate them; what an argument is; what makes an argument (logically) good or bad; what makes a claim evidence for another claim; how we might fail in our search for evidence; how to extract an argument from a piece of text, in order to assess whether we should accept it; what the difference is between having an opinion and knowing something, being scepticism and being sensitive to evidence, and between lying and bullshitting; what the typical forms of bad argument are; and finally, about logical paradoxes (such as that generated by the statement ‘This sentence is not true’), which seem to threaten our most basic assumptions about good reasoning. The module is taught by me, Dr. Daniel Esmonde Deasy (Associate Professor, UCD School of Philosophy), and is delivered in the form of two 50-minute face-to-face lectures per week of term along with seven 50-minute face-to-face tutorials with a graduate tutor from the School of Philosophy. Lectures consist primarily in the presentation of material by the lecturer, and tutorials involve active discussion of the material and non-graded exercises. The module is not difficult, but it should reward those who engage with it with valuable skills they can apply throughout their lives. I welcome students of all kinds to join this module: not just Philosophy students, but also students from any other discipline in the university; students at any stage of their UG degree; exchange, Erasmus, and study abroad students; students for whom English is not a first language; mature students; Open Learning students; and students who have come to UCD through other non-traditional routes. Critical thinking is for *everyone*, and the more diverse the class, the better. If you''d like to see last year''s syllabus, just email me at daniel.deasy@ucd.ie.', 'https://www.ucd.ie/modules/PHIL10160', 'phil10160'),
    ('af8f9b5e-6802-4b11-8614-8e41a7c38dd9', v_uni_id, 'PHIL20240', 'Applied Ethics', 'Philosophy', 'This module will be a survey of some of the most pressing ethical issues confronting us today. The discussion will begin with describing what applied ethics is and the range of topics that are normally covered under this field of ethics. Students will engage with ethical issues from thematic clusters: Environment and Climate Change, Medical and Public Health, Conflict and Violence, Migration, and Artificial Intelligence. In engaging with these thematic clusters, the lectures and tutorials will ask: How is the subject being discussed an ethical issue or concern? What ethical principles do they violate? What understanding of an ethical life or ethical society is it fostering or preventing? How does the phenomenon under investigation harm or benefit living entities? How can things change for the better? This module will require a fair amount of autonomous reading. Students are required to read the text before the class and participate in the discussion.', 'https://www.ucd.ie/modules/PHIL20240', 'phil20240'),
    ('00c97a2c-eb62-479a-8782-e0ec4fd7e4e5', v_uni_id, 'PHIL20640', 'Philosophy of Mind and AI', 'Philosophy', 'What is the nature of the mind? How are thought and consciousness related to the physical body and brain? How do we know that experience is real rather than a convincing illusion or simulation? These and other foundational questions in the philosophy of mind have returned to the fore in the context of modern ‘machine learning’ or ‘AI’ systems. Such systems raise the possibility of artificially intelligent agents that aim to replicate or even replace various aspects of human thought and behaviour, despite being physically very unlike us. This module will provide an introduction to these contemporary debates by examining foundational issues in the philosophy of mind concerning the nature of thought, consciousness and intelligence, and how these apply to current AI technologies such as machine learning (ML) and Large Language Models (LLMs). The focus will be on philosophical theories, such as physicalism, intentionality, externalism, and the extended mind, that enable us to explore AI as a test case to sharpen and advance our understanding of the mind, brain and body. Note: If you are taking this module as an elective you may be interested in pursuing a Structured Elective programme in Philosophy (this will entail taking two more Philosophy electives). Your University Transcript could show that you have a Structured Elective in either Existential Philosophy & Critical Theory or Philosophy of Mind & Science depending on which other electives you choose. See https://www.ucd.ie/students/registration/structuredelectives/ for details.', 'https://www.ucd.ie/modules/PHIL20640', 'phil20640'),
    ('ecf561f1-2982-45a5-ab3f-c15e32aedc8d', v_uni_id, 'PHIL20710', 'Body, Mind, World', 'Philosophy', 'In this module we explore the interrelation between mind and body particularly in terms of well-being, health and illness. Many people think of the mind being in the body like a driver in a vehicle. But it is more accurate to speak of embodied minds – our mental states are also embodied ones – and this also helps to us to understand our relationships with other people and with the world. This approach helps make better sense of well-being and illness -- especially mental illness -- as a disruption of the relationship with other people and with the world. We examine these issues in terms of the way they affect human action and shape our bodily habits, lived experience, and social identity. In this module we may consider a range of conditions such as mental illness (anxiety, social phobias, depression, dementia), trauma and pain, as well as the lived experience of body change (eating disorders, amputation, cosmetic surgery), reproduction (pregnancy, birth, IVF and surrogacy), as well as embodied aspects of identity such as gender, race, disability and sexuality. We may also address the roles played by social structures, constructions of personhood and sub-personhood, markers of normalcy and abnormality, and consider the ways the body is viewed in a clinical or medical setting in contrast to the lived experience of illness. (Please note topics might change and will be updated at the start of the semester). The module will be of interest to those in philosophy, humanities and social sciences, but also medicine, nursing and related disciplines including medical humanities. The module draws on phenomenological approaches and is a good companion course to PHIL20500 Phenomenology and Existentialism. It is not a prerequisite to have taken PHIL20500 to register for Body, Mind, World though. If you are taking this module as an elective - you may be interested in pursuing a Structured Elective programme in Philosophy (this will entail taking two more Philosophy electives). Your University Transcript will show that you have a Structured Elective in Existential Philosophy & Critical Theory, as appropriate. For further details: See: https://www.ucd.ie/students/electives/structuredelectives.html', 'https://www.ucd.ie/modules/PHIL20710', 'phil20710'),
    ('597a9155-afa2-4152-9d2a-e8c0cdef59b6', v_uni_id, 'PHPS40610', 'Risk Analysis in Food Safety', 'Public Hlth, Phys & Sports Sci', 'Risk analysis is integral to Food Safety. It is composed of three elements; Risk Assessment; Risk Management & Risk Communication. This module will largely focus on risk assessment associated with biological hazards and will include some focus on chemical hazards also. It will present a structured and detailed description of both defined and emerging risks to public health associated with the modern food chain. Some examples of important food-associated biological, chemical and other hazards will be provided. Modern scientific approaches to detect and trace food-borne bacterial zoonotic agents will be highlighted, including the use of whole genome sequencing (WGS)-mediated methods.', 'https://www.ucd.ie/modules/PHPS40610', 'phps40610'),
    ('7b92009a-1f96-43b0-8d6e-8e45a18051c3', v_uni_id, 'PHPS40740', 'Public Health Nutrition', 'Public Hlth, Phys & Sports Sci', 'This module will give you a basic understanding of the concepts of nutritional epidemiology, the methods employed to analyse the relationship between diet and nutrition status, focusing on specific nutrient deficiencies, dietary patterns, and growing chronic disease. The role of nutrition at each stage of the lifecycle will be examined while considering approaches to promote health and prevent adverse health outcomes. The effect of policy on dietary intake is also considered and its impact on over and undernutrition in both developing and developed countries. Psycho-social and cultural factors influencing dietary intake are explored throughout the module particularly in the context of developing strategies for improving nutrition at the population level.', 'https://www.ucd.ie/modules/PHPS40740', 'phps40740'),
    ('d3b172e8-ba40-45be-967a-4eb073554871', v_uni_id, 'PHTY20280', 'Born to Run: The Science of Human Endurance', 'Public Hlth, Phys & Sports Sci', 'Our bodies have an evolutionary story: as the descendants of flat-footed apes, we are not the quickest of creatures, but we have developed a series of adaptations that make us excellent long-distance runners. Bipedalism, ambulation on two legs, is a defining characteristic of what it is to be human. The premise of this module is that evolutionary, biological, and biomechanical perspectives can help us to better understand how we are “born to run”. First, we will examine the anatomical changes that enabled us to become specialists at long-distance running. We will also consider the biomechanics of human locomotion and the physiological determinants of long-distance running performance. These fundamental concepts will help to frame a discussion on how a training stimulus might be designed to optimise performance in long-distance events, with a focus on the marathon, and the influence of technology (e.g., shoes and wearable sensors) on human locomotion.', 'https://www.ucd.ie/modules/PHTY20280', 'phty20280'),
    ('7fba6ab8-ad42-4148-8c31-2df44fbb45c2', v_uni_id, 'PHTY30120', 'Research Methods', 'Public Hlth, Phys & Sports Sci', 'This module aims to enable the student, through a series of lectures, directed tutorials and CAL workshops, a high degree of autonomous learning, group work and guided by feedback from group oral presentations to their supervisor, to produce, unique to their group: their own, advanced, research proposal, compatible with the research strategy of UCD School of Public Health, Physiotherapy & Sports Science. In the context of their own research ideas, their group research proposal should credibly plan to deal with various common research problems, issues, and procedures that their research would encounter, in the event that their plan is initiated. A variety of methods of quantitative and qualitative data collection and relevant methods of data analyses will be examined, including: formulating a research question, writing a research proposal, the research process and study designs, sampling and measurement, questionnaire design and surveys, literature and database searching, the PICO framework, citation management, scientific writing, critical appraisal of literature and research quality rating tools, data management and both quantitative and qualitative statistical methods and analysis. Research integrity and ethical issues relating to research with human subjects are addressed; the concepts of informed consent are considered in relation to ethics and human rights in line with international, national and institutional policies, and students consider the definitions of vulnerable groups and ethical issues associated with informed consent for these populations. Students engage in tutorial groups to present their developing research ideas, to develop library information skills, to gain qualitative data analysis and SPSS CAL data management and data analysis experience. The developed group research proposal requires it and all supporting documentation to be submitted in electronic form, for checking by anti-plagiarism software. The module also aims to support the student to develop skills required to deal with working within a research team: workload and time management, problem solving, planning, organisation, leadership, communication, team-work, self and peer review and feedback. Mapped to CORU SoP: 1.13, 1.15, 1.16, 1.18, 2.13, 2.15, 5.1, 5.2, 5.5, 5.29', 'https://www.ucd.ie/modules/PHTY30120', 'phty30120'),
    ('c054741e-1aea-4d1a-bc25-e31a28a9593d', v_uni_id, 'PHTY30450', 'Digital Transformation in Health, Rehabilitation and Sport', 'Public Hlth, Phys & Sports Sci', 'Digital technologies have the potential to make an enormous impact in the intersecting fields of health, wellness and sport. We are witnessing a global healthcare crisis, with an ageing and more sedentary population, rising healthcare costs and an undersupply of healthcare practitioners. At the same time, we also see the promise that digital transformation could bring to the healthcare sector, with the possibility of more proactive and preventive care in the home and community setting, and advanced personalised therapies in the acute setting. However, the process of digital transformation in healthcare is complex and slow, and we are yet to see a revolutionary transformation as we have seen in the entertainment and travel sectors. On the other hand, in the wellness and sports sectors we are seeing a rapid adoption of digital technologies - however in this case the value proposition is not always clear. In this module we will introduce the key concepts associated with use of digital technologies in these fields and will explore the benefits and challenges of digital transformation through examination of case studies in different contexts, with a specific focus on applications in Physiotherapy and Sport Science. The module will be delivered in a series of lectures and students will be tasked with reading targeted papers/reports and implementing tools in practice where appropriate. Mapped to CORU SoP: 1.13, 2.7, 5.5, 5.6, 5.12', 'https://www.ucd.ie/modules/PHTY30450', 'phty30450'),
    ('bdf598b9-2d37-43a2-9556-f101f4dd6506', v_uni_id, 'PHYC10190', 'Aspects of Physics for Ag. Sci', 'Physics', 'The course centres on the use of online lectures. Aspects of Physics including Atoms, lasers, nuclear and light will be covered. Applications of apsects of these elements to Arg science will be covered. Assessment will contain Lab based experimental work. Tutorals will be given to support learning.', 'https://www.ucd.ie/modules/PHYC10190', 'phyc10190'),
    ('785bb24a-bf88-4de1-a0ee-5e239f34c8cf', v_uni_id, 'PHYC20090', 'Electronics and Devices', 'Physics', 'The module will cover the physics of electronics and devices. Students will study circuits, complex impedance, Ohm''s law, Kirchoff’s laws, elementary crystallography, X-ray diffraction and Bragg’s law, Drude’s classical theory of conduction, the Hall effect, passive components (resistors (and resistor networks), capacitors), semiconductors, the p-n junction, diodes, transistors, and operational amplifiers. Furthermore, the module will provide an introduction into Digital-Analog (DA) and (AD) converters, measuring data, and µ-controller (e.g. Arduino). Devices studied will rely primarily on the physics covered in the module and includes photodiodes, LEDs, photomultiplier tubes (PMTs), amplifiers, solar cells and CCDs.', 'https://www.ucd.ie/modules/PHYC20090', 'phyc20090'),
    ('18d548e8-7296-4d8f-bcca-043e4597d546', v_uni_id, 'PHYC40020', 'Applied Quantum Mechanics', 'Physics', 'The module will build upon PHYC30030. The following list of topics will be covered: Topics covered in this course include the time-dependent Schrodinger equation; the variational principle; position and momentum operators and representations (Fourier transforms); a complete treatment of the Stern-Gerlach experiment; spin; quantum dynamics; Heisenberg operators and equation of motion; two state quantum systems; spin precession in a magnetic field; ammonia molecule in an electric field, and the MASER (Nobel Prize work); nuclear magnetic resonance (Nobel Prize work); multiparticle states and tensor product; entangled states and quantum teleportation; EPR paradox and Bell Inequality.', 'https://www.ucd.ie/modules/PHYC40020', 'phyc40020'),
    ('cc944183-bdd0-4c4d-b056-72692cc927a7', v_uni_id, 'PHYC40080', 'High Energy Particle Physics', 'Physics', 'This module provides an introduction to modern particle physics:fundamental particles and interactions, experiments at particlecolliders, quantum numbers and conservation laws, the Standard Modelof Particle Physics, quarks and leptons, gauge and Higgs bosons,resonant states and quark model of hadrons, Feynman diagrams,electroweak unification, P and CP violation, physics of charm, beautyand top quarks, mixing and oscillation, strong interaction physics,neutrino physics, physics beyond the Standard Model.', 'https://www.ucd.ie/modules/PHYC40080', 'phyc40080'),
    ('14473de0-f9fd-494f-8e26-9af950ff7521', v_uni_id, 'PHYC40740', 'Space Sector Professional Skills', 'Physics', 'This module gives students the opportunity to develop professional skills relevant to the space sector. These include space project management, developing requirements, proposal writing in response to Invitations to Tender, CV preparation and other relevant transferable skills such as team-working. One-to-one access to space sector professionals, via seminars and workshops, provides students with a unique opportunity to network and gain insights that will support them in planning their own preferred career trajectory. The module provides a structured environment within which students develop their CV and cover letter, in consultation with the internship manager and other support services. Students are supported to seek out opportunities for their 3 month space sector internships in a timely and professional manner. Weekly seminars provide students with a breadth of knowledge of the current state of the art across the space sector from experts in the field.', 'https://www.ucd.ie/modules/PHYC40740', 'phyc40740'),
    ('d737e25b-970b-4663-8023-ccaa1c8900a4', v_uni_id, 'POL10120', 'Foundations in Global Development', 'Politics & Int Relations', 'This module is designed to introduce students to key themes in the foundations of global affairs and international development. The first section of the module explores theories (and histories) of development. , including market-based approaches (free markets, free trade, free movement of capital.); approaches that emphasize the role of the state. The second section of the module explores more empirical aspects of industrial development, human development, sustainable development and beyound 2030 development.', 'https://www.ucd.ie/modules/POL10120', 'pol10120'),
    ('8f6fc18a-074a-4fe0-8b6b-c1b8c1f579f2', v_uni_id, 'POL10160', 'Foundations of Contemporary Politics', 'Politics & Int Relations', 'This course introduces students to the study of political science. We will explore the foundations of political power and collective decision-making and analyze how politics is shaped by ideas, interests and institutions.', 'https://www.ucd.ie/modules/POL10160', 'pol10160'),
    ('49a80d88-54ca-4f0d-8576-31ea83df5a69', v_uni_id, 'POL10170', 'Foundations in Political Research', 'Politics & Int Relations', 'Most courses you will take in your undergraduate studies will relate to politics itself - about politics in different regions, or about particular aspects of political systems. This course, however, is about political science, about conducting research on politics and in the social sciences more broadly. Theoretically and practically, we will consider questions such as: How do we design our research? How do we collect data? How do we draw valid conclusions from this data? The module will provide you with very relevant practical and analytical skills that will benefit you throughout your career, both academically and professionally. We will cover several topics, including general types and core elements of research design; a brief overview of the main methods used in political science today; as well as practical and ethical considerations of political research. We will also explore empirical research methods and the visual inspection of results as the core components of the course. Special attention will be paid to writing and reading political science research.', 'https://www.ucd.ie/modules/POL10170', 'pol10170'),
    ('c699893d-1a01-4dd6-bd30-b969dc27b827', v_uni_id, 'POL10180', 'Foundations of Pol Theory', 'Politics & Int Relations', 'This module provides an introduction to political theory, focusing on changing conceptions and models of democracy, mainly through the thought of four challenging and influential political thinkers, Aristotle, Wollstonecraft, Mill and Marx. We focus in particular on four key themes: the meaning and relative importance of the political principles of liberty, equality and community; how much political participation there should be; the social pre-conditions for democracy; and to what extent the kind of democracy possible depends on how we think of human nature. This module is required for any student wishing to take Politics as a major at Stage Two. In addition to the lectures, an essential part of this module are tutorials in which students learn through writing essays and exercises and through participating in discussions.', 'https://www.ucd.ie/modules/POL10180', 'pol10180'),
    ('854dc808-5724-41cc-9b80-35cb89cb6467', v_uni_id, 'POL20010', 'Individuals and the State: The Idea of Freedom in the History of Political Thought', 'Politics & Int Relations', 'The slogan of the French Revolution is still popular: Liberty, Equality, and Fraternity. Liberty is usually the most glorious and most popular ideal, but what does it mean to be free? Free from what? Free to do what? How is my freedom from interference compatible with your freedom to act? How is the authority of the state compatible with my individual liberty? Equality also is still a very popular ideal but the question of what kind of equality matters when is very controversial. Are equal rights enough? Should there be equal opportunities? What about equality of well-being? Fraternity, finally, has a lovely ring to it, but is quite complicated to. And not just because of the sexist undertones. When is the idea of community and belonging important enough to allow compromising some liberties and/or some aspects of equality? The key question of this model is how freedom is compatible with the authority of the state. Over the course of this module we will look at some classical responses to this question as well as to the related questions of how to organise statehood in a way that balances concerns for liberty, equality, and community. In exploring the theoretical foundations of today’s debates on these issues, we will initially focus on a selection of historical thinkers from the pre-Enlightenment period onwards, later bringing the debate more up to date with scholarship by more modern thinkers.', 'https://www.ucd.ie/modules/POL20010', 'pol20010'),
    ('0c49d5e5-1315-49e6-8688-3cf10723cea5', v_uni_id, 'POL20020', 'Comparative Politics', 'Politics & Int Relations', 'Introduces students to the concepts and methods of comparative politics, with a focus on domestic political institutions and processes. Uses systematic comparison across political systems that are similar in many respects but differ in important ways, to analyse the effects of those differences rigorously. Assumes no prior knowledge of politics.', 'https://www.ucd.ie/modules/POL20020', 'pol20020'),
    ('03f36ce0-3a2d-4877-b971-2e4669bc5f03', v_uni_id, 'POL20050', 'Research Methods in Political Science', 'Politics & Int Relations', 'This module introduces students to the philosophy and practice of social science and to commonly used statistical techniques in political science research. Students will learn how to pose interesting, answerable, and focused research questions, develop answers by generating theory-driven hypotheses, operationalize concepts, construct valid and reliable measures, and finally work with data. The module will cover quantitative methods, including basic statistical analysis, from describing and visualizing patterns in numerical data to regression analysis. Students will also be introduced to statistical programming for research in political science.', 'https://www.ucd.ie/modules/POL20050', 'pol20050'),
    ('34736729-539e-4acb-bc90-5fa795ffb833', v_uni_id, 'POL20250', 'Irish Politics', 'Politics & Int Relations', 'The objective of this course is to introduce students to the workings of the Irish political system. We start by locating Irish politics in comparative terms, showing how unusual a political system it is in comparison to other European states. The course then examines the historical, constitutional, social and political context of Irish politics. It deals with the ground rules within which Irish elections take place, the evolution of the Irish party system, and voting behaviour in elections and referendums. The course exmaines the operation of the main political institutions: the Dail, the Seanad, the government, the judiciary and major offices such as those of President and Taoiseach. Other important forums for political activity are also considered. This course will be taught entirely by lectures; there will be no tutorials.', 'https://www.ucd.ie/modules/POL20250', 'pol20250'),
    ('36f4c44a-ce40-447f-860c-eff8d2605d60', v_uni_id, 'POL20260', 'Introduction to Chinese Politics', 'Politics & Int Relations', 'This module aims to introduce students to the political system of the People''s Republic of China. The module first provides a historical foundation for understanding the current political regime, covering the Civil War and Communist victory, the Great Leap Forward, the Cultural Revolution, and the transition to economic modernisation under Deng Xiaoping and Jiang Zemin. Building on this foundation, the module examines China''s social context, including geography, urbanisation, demographics, and the hukou system. It then analyses political institutions—the Party, government, legislature, local politics, and the military—before turning to political contestation through factions, corruption, and protest. The module addresses mechanisms of authoritarian control, including repression, censorship, ideology, propaganda, and the politics of nationalism and ethnicity in Xinjiang and Tibet. It concludes by examining China''s foreign relations, including Taiwan and Hong Kong, and global governance initiatives such as the Belt and Road initiative. By the end of the module students will have a well-grounded understanding of Chinese politics and be prepared to think carefully about current and future developments.', 'https://www.ucd.ie/modules/POL20260', 'pol20260'),
    ('4a273a69-873c-4693-b3de-21f1b0400a67', v_uni_id, 'POL20270', 'Post-Soviet Politics', 'Politics & Int Relations', 'The module will introduce students to politics in countries of the ex-Soviet Union, covering the main political developments, events, institutions, and processes in the region. We will start with a historical overview of the pre-Soviet (imperial Russia) and Soviet periods and then focus on topics related to politics in Ukraine, Belarus, Russia, Georgia and other countries after the fall of the Soviet Union. We will assess how and why, despite shared historical legacies, some post-Soviet countries succeeded in democratic transition while others established authoritarian regimes. The course will put the regional developments in the global context, introducing students to the main theories and comparative literature on democratic transitions and reversals. (This module will be taught by Dr Nikita Khokhlov.)', 'https://www.ucd.ie/modules/POL20270', 'pol20270'),
    ('79908983-021b-4d1b-8139-609c35603076', v_uni_id, 'POL20280', 'Politics of the Welfare State', 'Politics & Int Relations', 'This module provides and overview of the political origins and development of welfare states in democratic countries. Topics covered include the varieties and tasks of modern welfare states; classic theories about the relationship between markets, classes, and social protection; competing explanations for why modern welfare states emerge and why they differ from one another; how welfare states are shaped by social forces such as organized labor and the self- employed, political institutions, and societal views of appropriate gender relationships; challenges to the welfare state that emerge from changing labour market, demographic, and social conditions in industrialised countries; and the political dynamics of reforms to the welfare state.', 'https://www.ucd.ie/modules/POL20280', 'pol20280'),
    ('bf8d0bd6-3115-460a-b2d4-2485d1baa4e7', v_uni_id, 'POL30640', 'Democratic innovations and the future of democracy', 'Politics & Int Relations', 'This is a substantively revised module that used to be titled ‘Deliberative mini-publics’. The primary focus remains on DMPs, but the setting has changed to reflect growing concerns about the future of democracy. Political science is replete with studies about the crisis of democracy: much of the emphasis is on democratic ‘erosion’ and ‘backsliding’, on ‘autocratization’ and the emergence of ‘illiberal’ regimes. What is often forgotten or underestimated is the degree to which democracies can and do innovate, to varying degrees showing their resilience. This module starts from that perspective, introducing students to another significant emerging field of studies, on the phenomenon of democratic innovations. We start by reviewing the main forms of democratic innovation before proceeding to focus on the most prominent of these innovations – deliberative mini-publics (DMPs), which are fast becoming an ever more notable feature of contemporary democracies. Having first emerged in the latter part of the 20th century, they started to achieve prominence in the first decade of this century (starting with the British Columbia Citizens’ Assembly in 2005). Their use has mushroomed in the past few years, not least as shown by the extensive use of DMPs between 2012-23. An influential OECD report records hundreds of examples of DMPs over the past few decades. The primary purpose of this module is to examine what they are, how they vary, their strengths and weaknesses, and what the might contribute to the resilience of democratic systems. The content of the module will include the following key themes: threats to democracy; democratic innovations with a particular focus on citizen-centred reforms; defining DMPs and how they vary; where DMPs fit within deliberative democracy more generally; the place of DMPs within the existing system representative democracy; the potential of deliberative processes to help save democracy.', 'https://www.ucd.ie/modules/POL30640', 'pol30640'),
    ('3e3eba36-2d16-4449-b70a-047e7a4441ef', v_uni_id, 'POL30660', 'Data Analytics for Social Sciences', 'Politics & Int Relations', 'In this module, you will acquire a broad understanding and technical skills in well-established and cutting-edge data analysis methods for the social sciences. The course is divided into three broad areas of data analysis: description, prediction, and causation. These reflect some of the main strands of social scientific work in academic research and other professions. We will start by revisiting the rationale, principles, and aims of statistical analysis. The descriptive analysis part of our course covers methods to manipulate, summarize, and visualize data. In the predictive part of the module, we will move to a range of approaches to address various kinds of empirical questions, including regression analysis and logistic regressions. In the final part of the seminar, we will learn about the rationale for and application of cutting-edge methods to examine the causal drivers of various social phenomena. Written and verbal participation as well as lab and group exercises form the basis of continuous assessment throughout the module. Capping off the first part of the course, you will work on and present a group exercise with some of your classmates. After the second part of the module, you are asked to hand in a take-home assignment. Lastly, your understanding and application of all methods will be assessed in a final exam at the end of term.', 'https://www.ucd.ie/modules/POL30660', 'pol30660'),
    ('788be5f6-399c-4056-9ea8-2a6a210208d8', v_uni_id, 'POL30730', 'Political Activism in the Middle East', 'Politics & Int Relations', 'Welcome to Political Activism in the Middle East! In this module, we will study resistance in the Arab World. Many contemporary events, such as the debate around disarming Hezbollah or the fall of the Assad regime in Syria, underscore the centrality of non-state actors in the Middle East. This module covers a diverse set of actors, including religious figures, political dissidents, workers, women, and ordinary people, in settings across the region (e.g. Syria, Egypt, Tunisia, Palestine, and Israel). While introducing students to the broader study of political resistance, beyond the Arab World, the module equips them with the analytical tools to examine collective and non-collective forms of violent and nonviolent activism in the Arab World.', 'https://www.ucd.ie/modules/POL30730', 'pol30730'),
    ('32dbf84d-dded-4921-a302-2b5a35df4f39', v_uni_id, 'POL30780', 'Justice in Education', 'Politics & Int Relations', 'We analyse moral questions in the context of education and schooling. In particular, we will look at the relevant criteria for evaluating the moral rights and duties of children, parents, and the state with regard to education. Students will be introduced to some of the most important concepts in political theory such as justice, equality, liberty, autonomy, and community. We will discuss the different aims of eduction as well as which agents have which responsibilities with regard to enabling children to acquire the capacities for full membership in society. We will consider which understandings of freedom and equality should inform our thinking about multicultural education and/or demands for equal opportunities for the socially disadvantaged and discuss whether and in how far state schools ought to be neutral with regard to religious and/or cultural norms relating to conceptions of the good life.', 'https://www.ucd.ie/modules/POL30780', 'pol30780'),
    ('e07e8c74-88af-4346-8666-7cb8d8171565', v_uni_id, 'POL30820', 'Political Risk and Foreign Direct Investment', 'Politics & Int Relations', 'This module provides both an introduction to and an in-depth review of the field of political risk, with a particular focus on the socio-political events, dynamics, and processes that can shape—and at times hinder—the success of multinational corporations (MNCs). At the heart of the course is the complex and often contentious relationship between foreign investors and host country governments. Drawing on insights from multiple disciplines including international political economy, comparative politics, international relations, global politics, international business, corporate and social responsibility, and international economics—the course offers an interdisciplinary perspective on political risk. Key themes explored include: • Understanding the concept of political risk. • Causal chain analysis of political risk. • Expropriation, and nationalization as critical challenges for MNCs. • Economic nationalism and protectionism and their implications for foreign investment. • The obsolete bargaining model and evolving investor–state dynamics. • The relationship between regime types and FDI. • Institutions, governance, and regulatory frameworks and how they influence investor confidence. • Political risks in natural resource sectors, particularly in extractive industries. • Issues of extraterritoriality and geopolitics. • Impact of human rights on foreign direct investments. • Emerging practices in political risk assessment and analysis. In addition to examining these core issues, the module also highlights the practical instruments, strategies, and risk management techniques that MNCs employ to mitigate exposure to political risks. By integrating theory with real-world applications, this module aims to provide students with a nuanced and comprehensive understanding of how political risks emerge, evolve, and affect the objectives of global firms.', 'https://www.ucd.ie/modules/POL30820', 'pol30820'),
    ('a9ad5588-185b-4906-83da-85c45ee6a154', v_uni_id, 'PSY10040', 'Introduction to the Psychology of Perception and Cognition', 'Psychology', 'This course presents an introduction to the fields of Perception and Cognitive Psychology. The study of "perception" is concerned with how we acquire knowledge about the external world through our senses. It examines such questions as: How do we come to experience colours and sounds, tastes and smells, and objects and faces? "Cognitive psychology" explores how our minds work in seeking, storing and using our knowledge of the world, ourselves and other people. It addresses such questions as: How does our memory system work and what goes on in our heads when we imagine something? The objective of the module is to introduce you to the main principles, methods and findings of contemporary psychology as applied to the fields of perception and cognition. To enhance student learning, lecture content is supplemented by video/computer illustrations and class exercises. Copies of all lecture notes are available to registered students on the Blackboard system.', 'https://www.ucd.ie/modules/PSY10040', 'psy10040'),
    ('04ddf77b-ba21-47d8-a556-440bdb6ca29b', v_uni_id, 'PSY10050', 'Introduction to Psychology', 'Psychology', 'This module is designed to introduce students to the breadth of topics covered by the discipline of psychology. The module covers a range of theoretical approaches used in psychology to try to explain human thought and behaviour. A variety of topics will be introduced drawn from the full breadth of the discipline of psychology and may include aspects of child development, human social interaction, thinking and reasoning and biological psychology.', 'https://www.ucd.ie/modules/PSY10050', 'psy10050'),
    ('2cb91181-a3a1-478d-abd6-25bf4637d5b5', v_uni_id, 'PSY10060', 'Brain and Behaviour', 'Psychology', 'One of the big challenges in psychology is to understand how elements of the nervous system, such as neurons, can cooperate to produce high-level operations like perceiving, thinking, acting and consciousness. The aim of this module is to introduce you to biological psychology by way of studying the link between the brain and behaviour. Psychology students will gain an understanding of how the brain is involved in everything we do; whether it be recognising faces, getting a good night''s sleep or remembering where you left the car keys. The course consists of: - Historical Perspectives and The Big Questions - Measuring Brain and Behaviour - Neuroanatomy and the Developing Brain - Sensation and Perception - Executive Functions - Learning and Memory - Sleep & Dreaming - Disorders of Brain and Behaviour Throughout the course, case studies will be presented to help show the link between brain and behaviour and to explain clinical disorders and real-life problems that psychologists study.', 'https://www.ucd.ie/modules/PSY10060', 'psy10060'),
    ('2c67e876-4dcf-4cc7-a91a-11c2cff42bac', v_uni_id, 'PSY10080', 'Introduction to Social Psychology', 'Psychology', 'This module introduces students to key topics, theories and methods in the field of social psychology. Social psychology is the scientific study of how individuals’ thoughts, feelings and behaviours are influenced by the actual or imagined presence of other people. This module covers such topics as attitudes, social influence, groups, prejudice, attraction, gender and prosocial behaviour. The module will critically evaluate seminal and contemporary studies in social psychology and consider the insights they offer into the psychological processes that underlie human relationships, culture and society.', 'https://www.ucd.ie/modules/PSY10080', 'psy10080'),
    ('37d95769-65f0-4540-8cb3-d9337ebccbce', v_uni_id, 'PSY10090', 'Introduction to Applied Psychology', 'Psychology', 'The aim of this module is to provide students with an introduction to applied psychology by examining how psychology has used research to examine socially significant issues. A range of topics will be considered, for example video games and aggression, cheating in sport, bullying, self-esteem, mental health, wellbeing, and dementia. The module will also use these topics to examine quantitative and qualitative research methods, and a key focus of the module is on supporting students to be confident consumers of research in journals and the popular media. Students should note that this module will include formal lectures, in-class small group workshops and a high level of participation is expected.', 'https://www.ucd.ie/modules/PSY10090', 'psy10090'),
    ('b700ea33-ef94-4108-bca0-c38f26578b65', v_uni_id, 'PSY10100', 'Research Methods & Stats I', 'Psychology', 'Research methods are central to the undergraduate curriculum in many subjects and disciplines. This module introduces students to the basic principles underpinning research enquiry in psychology. Students will learn about commonly used quantitative and qualitative methodologies and designs. In addition, the module introduces students to basic descriptive statistics, for example levels of measurement, properties of the normal curve, measures of central tendency and variation, and correlation. You will also learn about the importance of open research and how open research principles can be applied across the research process. Students should note that a key feature of this module is attendance and weekly participation in active and collaborative learning activities, including but not limited to classroom discussion, buzz groups, and skills-based group problem-solving related to the learning outcomes.', 'https://www.ucd.ie/modules/PSY10100', 'psy10100'),
    ('48270c5c-9292-45de-9b86-310712633d38', v_uni_id, 'PSY10130', 'Key Skills and Concepts in Psy', 'Psychology', 'Pass/Fail (GPA Neutral) This module is a core module on the BSc in Psychology. The aim is to provide students with an introduction to some of the key concepts and skills that are central to engaging with the subject. A secondary aim is to introduce students to the staff and postgraduate students in the UCD School of Psychology. This ten-credit module will ensure that students have the space in the first trimester of first year to immerse themselves in their studies and develop a strong understanding of the subject. The topics in the module have been drawn from across the specialist topics that form part of the BSc. Students will also be introduced to careers in psychology and encouraged to identify the work and impact of psychology in their communities.', 'https://www.ucd.ie/modules/PSY10130', 'psy10130'),
    ('34e3712b-9ce4-40cc-b6e8-8f595dc827fb', v_uni_id, 'PSY20020', 'Child & Adolescent Development', 'Psychology', 'During childhood and adolescence human development is taking place at a phenomenal pace, with children learning many of the skills that are crucial to their current and future emotional well being, relationships and cognitive functioning. This module explores the complex biological, psychological and cultural factors that influence this developmental process. The module introduces and critiques the major theories of developmental psychology that underpin understanding of development during childhood and adolescence. Lectures span all aspects of child development from birth through adolescence pointing to important methodological issues and gaps in our current understanding.', 'https://www.ucd.ie/modules/PSY20020', 'psy20020'),
    ('fa139c06-5776-4e33-a8c1-590d7bc4b066', v_uni_id, 'PSY20100', 'Introduction to Disability Studies', 'Psychology', 'This module provides students with an introduction to the interdisciplinary field of disability studies. The module comprises four core strands: the nature of disability; the history of disability; key models of disability; and policy and practice in disability. The module takes a bio-psychosocial (non-medical) approach to disability. The focus of the module is on introducing students to theory, research, policy and practice relating to the disability sector in Ireland and internationally.', 'https://www.ucd.ie/modules/PSY20100', 'psy20100'),
    ('e3078c59-6927-4f10-9a85-c4d4e5baaea7', v_uni_id, 'PSY20110', 'Introduction to Health Psychology', 'Psychology', 'This module will introduce students to some of the psychological processes that underlie health and illness. It includes an examination of both theoretical and applied issues and covers a variety of topics including an exploration of the meaning of ''health'' and ''illness''. Key topics include health beliefs, health behaviours and behaviour change, stress and coping, inequalities in health, and living with illness.', 'https://www.ucd.ie/modules/PSY20110', 'psy20110'),
    ('ec2c9a81-a3f8-41a1-a6ae-f713775ae190', v_uni_id, 'PSY20150', 'Foundations of Psychology', 'Psychology', 'This module will provide an introduction to the history of Psychology, its foundations in scientific and philosophical traditions and its impact on modern society and culture. Emphasis will be placed on considering psychological research in the light of the social and scientific context in which it was produced. Through this module you will acquire a broad knowledge of the history of psychology. Topics will include early experimental work in psychology, the Behaviourist school, Gestalt psychology and the psychodynamic approach. You will also come to understand the relationship between psychology and the society in which it is produced. We will investigate how psychology has contributed to the construction of concepts such as ‘race’, ‘gender’ and ‘madness’, and will critically evaluate the social role that psychology has played and continues to play.', 'https://www.ucd.ie/modules/PSY20150', 'psy20150'),
    ('7ee4acbb-560d-460e-9416-aa13bfc56e71', v_uni_id, 'PSY20170', 'Clinical Psychology', 'Psychology', 'This module provides an overview of common psychological problems such as depression, anxiety, schizophrenia, childhood disorders and personality disorders. This overview includes material on clinical examples, clinical features, classifciation, epidemology, aetiology and treatment. This is also a focus on protective factors and positive psychology.', 'https://www.ucd.ie/modules/PSY20170', 'psy20170'),
    ('2a157c82-4ae3-4eea-bf0b-a7dca3f06c6c', v_uni_id, 'PSY20180', 'The Science + Art of Therapy: From Freud to Zinn', 'Psychology', 'This module will give you a broad overview of the key concepts and therapeutic processes of the major approaches in counselling psychology. Theoretical constructs of how psychological disturbance are acquired and maintained, the goals of therapy, key therapeutic techniques and the therapeutic relationship will be explored across these approaches. Lectures will be highly participative and case studies and video clips showing master practitioners will be used to illustrate the therapeutic process. Assessment will consist of a) an MCQ quiz b) an end of trimester essay.', 'https://www.ucd.ie/modules/PSY20180', 'psy20180'),
    ('26fa5224-1db2-4270-8868-55477c20cf03', v_uni_id, 'PSY20220', 'Psychology of Ageing', 'Psychology', 'We are all ageing. With every day, we age a little more. While you may not consider yourself to be ageing, you may be observing those close to you ageing, and be involved in providing support as needed. This module aims to provide students with a basic understanding of the psychology of ageing. The module will explore the nature of ageing; cognitive functioning; psychological issues; assessment and interventions.', 'https://www.ucd.ie/modules/PSY20220', 'psy20220'),
    ('403e702e-feee-4118-adc6-990148d1b709', v_uni_id, 'PSY20240', 'Language, Perception & Social Cognition', 'Psychology', 'Social interactions are fundamental to human life and are supported by various cognitive processes, including language, social perception and social cognition. Some of these processes are shared with other social species while other abilities, such as language, are thought to be uniquely human. This module provides an introduction to the nature and development of language, to aspects of social perception (the recognition of faces, bodies and gestures ) and to aspects of social cognition (including mentalizing and perspective taking) considered from an embodied perspective. The course introduces the various ways in which psychologists study language and cognition; via experimental psychology and cognitive neuroscience, and by studying the changes in cognitive function that result from brain injury and the differences in social cognition that characterize specific neurodevelopmental conditions.', 'https://www.ucd.ie/modules/PSY20240', 'psy20240'),
    ('7620d9e9-7f1e-427b-bf57-5d116f7dccf7', v_uni_id, 'PSY20250', 'Careers in and with psychology', 'Psychology', 'This module is designed for psychology students to facilitate their academic, personal and career development and to enable them to develop employability skills. Students will learn about options for careers in and with psychology available to psychology graduates and approaches to independently researching career possibilities. Students will develop their self-awareness and gain an enhanced understanding of what motivates them in the workplace. Students will also build their appreciation of how to prepare for and navigate the graduate recruitment process, gaining practical experience of how to market themselves in written applications and interviews for different types of roles.', 'https://www.ucd.ie/modules/PSY20250', 'psy20250'),
    ('9dfb483f-f94f-4a2a-82f3-9d634ae8023b', v_uni_id, 'PSY20260', 'Psychological Disorder, Difference & Diversity in Social Context', 'Psychology', 'This module explores how social contexts shape concepts and experiences of psychological disorder, difference and diversity. The module covers such topics as the social determinants of mental health and illness, culture and global mental health, relationships between psychiatric diagnoses and social labels, and how psychiatric categories interact with dynamics of stigma, identity and community. The module will critically evaluate biomedical and social constructivist approaches to psychiatric disorder and consider their implications for experiences of distress and difference in society.', 'https://www.ucd.ie/modules/PSY20260', 'psy20260'),
    ('bdb65b47-1e3b-44e8-97d0-541f6599b2f6', v_uni_id, 'RDEV10020', 'Information Skills', 'Agriculture & Food Science', 'Pass/Fail (GPA Neutral) The purpose of this module is to introduce students to some of the key skills required in your chosen Degree Programme. The focus of the module will be on transitioning into University life and the expectations that your lecturers and tutors have for you. We will be looking at how critical thinking and working independently is such a strong feature of your new academic life.', 'https://www.ucd.ie/modules/RDEV10020', 'rdev10020'),
    ('c942cbe6-f6ed-4df9-8f1d-a6b2ced2326d', v_uni_id, 'RDEV20140', 'Health, Welfare & Safety in Agriculture', 'Agriculture & Food Science', 'This is an undergraduate module designed for students of Agricultural Science, Food Science and Human Nutrition who are required to undertake professional work experience (PWE). It focuses on developing greater awareness and knowledge of health and safety issues related to agriculture, the food industry and associated areas. The agri-food sector faces the challenge of economic, environmental and social sustainability as the industry expands to meet global food demand. This module explores social sustainability through the lens of occupational safety and health. Content includes the work environment; the legal environment and health and safety legislation in Ireland; insurance; health and safety management and work systems; manual handling; chemical safety and other psycho-social hazards; health and welfare. The module will also contain a training component related to Agricultural Science Programme Majors.', 'https://www.ucd.ie/modules/RDEV20140', 'rdev20140'),
    ('f5e78f87-7fb7-4d26-a0ae-a0d3bbe1a458', v_uni_id, 'RDEV30160', 'Food Poverty and Policy', 'Agriculture & Food Science', 'Globalization goes well beyond the boundaries of economics and markets and impacts on the very basic needs that sustain people''s lives, including their access to food. It is estimated that in 2009 more than one billion people were food poor and for reasons of access, affordability or availability do not have enough food to meet their basic nutritional needs for healthy lives. At the same time almost one billion people are categorised as obese. The linkage between people''s access to food at household level and the general state of the market place have never been as strong e.g. transport and energy costs in Europe impact on the costs of basic food stuffs for poor households not just in Europe but also in poor regions such as sub-Saharan Africa. Historically many countries have been shaped by periods of food poverty, including Ireland, and for hundreds of millions of households today chronic hunger is a reality. This module explores the causes of food poverty in poor countries of the South as well as some of the economically wealthier countries of the North. It aims to provide students with the opportunity to develop a deeper appreciation of both the extent and nature of food poverty as well as an understanding of the range of policies that aim to address this problem. This module has been developed as part of the Egalitarian World Initiative in UCD and with the financial support of Irish Aid.', 'https://www.ucd.ie/modules/RDEV30160', 'rdev30160'),
    ('11f4c4ca-8e30-43db-af41-2f6849a485bc', v_uni_id, 'SCI10010', 'Principles of Scientific Enquiry', 'Science Admin Office', 'This module introduces students to the principles of scientific enquiry through lectures and group work. Working in small groups, students in conjunction with their academic mentor will identify a scientific problem, research the literature and produce a review. The work will develop students'' independent study skills. This module involves staff from all disciplines within the Science Programme and students are encouraged to undertake their project work in a discipline that is of particular interest to them. Using a project based approach; students will learn communication and presentation skills, methods of sourcing scientific information, scientific writing and analysis. Formal direction on teamwork, communication, presenting, sourcing and appraising information, scientific reading and writing, and critical thinking will be central to this module.', 'https://www.ucd.ie/modules/SCI10010', 'sci10010'),
    ('9960cbd1-560f-49df-b406-d212d94d6cd5', v_uni_id, 'SCI30080', 'Professional Placement-Science', 'Science Admin Office', 'Pass/Fail (GPA Neutral) The opportunity of a professional science experience is offered to students over a 6-10 week Summer period. The aim of this module is to give students the opportunity to develop an understanding of how Science operates in a professional industrial environment and how theory presented in modules translates to practice. Placements may vary considerably but in general terms students will work in industrial or non-academic research environments where they will obtain a breadth of practical experience to complement their degree programme. Work placements are available subject to suitability and availability, queries can be directed to scienceinternships@ucd.ie These should be discussed with the School coordinator in advance. Students apply for these placements and may be offered interviews by the placement providers. Students may alternatively source their own placements on the advice of the module coordinator. A member of the academic staff will be appointed to liaise with the student during the period of their work placement. The member of academic staff will maintain contact with the student and the student''s supervisor within the placement organization to ensure that the student is meeting the learning outcomes associated with the module. Assessment will take place on completion of the placement and submission of reports from both the student and employer. The module will be assessed as Pass/Fail. Successful completion of the module will result in a module grade P which will be grade point neutral. An unsuccessful attempt at the module will be awarded an F or an NG giving a grade point of 1.0 or 0 respectively. Failure to meet the learning outcomes associated with this module represents grounds for failure.', 'https://www.ucd.ie/modules/SCI30080', 'sci30080'),
    ('e9b9e115-5f4f-409f-9827-a692b8a5367f', v_uni_id, 'SMGT10060', 'Sociology of Sport', 'Public Hlth, Phys & Sports Sci', 'Sport is an integral part of culture and society. To be effective as a sport management professional, it is essential that you have an understanding of the culture of the society in which you exist. Knowledge of the social significance of sport will enhance your understanding and effectiveness in your future life and work. This module explores the relationship between sport and society, examining the influences these entities have on each other. The links between sport and social structures, such as politics, social class, the commercial and business sectors, education, and the media, will be analyzed. There will be a particular focus on how issues such as identity (local and national), socialization, doping, violence, race, and commercialism are addressed and how they impact the sports context.', 'https://www.ucd.ie/modules/SMGT10060', 'smgt10060'),
    ('3e9e35e4-5481-40ea-bdd6-169f194f2cf1', v_uni_id, 'SMGT10070', 'Sports Management', 'Public Hlth, Phys & Sports Sci', 'This module will provide students with an introduction to multiple aspects of sports management. The aim of this module is to enable students to develop skills in and knowledge about management and organisational behaviour through the lens of sport. Each unit of the module will examine key management principles (e.g., leadership, culture, inclusion, stakeholder and issue management, event and facility operations) followed by case study analysis. All course materials including summary lecture notes will be available on Brightspace.', 'https://www.ucd.ie/modules/SMGT10070', 'smgt10070'),
    ('446e9d60-0e47-48fa-8479-0a97da15c13e', v_uni_id, 'SMGT10100', 'Coaching and Leadership', 'Public Hlth, Phys & Sports Sci', 'This module is an introduction to the science and research in coaching and coaching practice. Fundamental topics will be covered such as the coaching process, coach development, leadership and how to structure a coaching session. The aim of the module is to provide students with an awareness of the current coaching literature and how this can inform coaching practice. Practical classes are a core component of the module and are designed to develop the practical skills and competencies required to achieve the module learning outcomes. Due to the practical nature of the module, we have a mandatory 80% attendance policy in place. Regular attendance at these classes provides core training and for health and safety measures. Students who are unable to attend due to illness or other exceptional circumstances should notify the module coordinator as soon as possible.', 'https://www.ucd.ie/modules/SMGT10100', 'smgt10100'),
    ('de1bfd6c-4215-4f55-8f2e-f1b79d0cca04', v_uni_id, 'SMGT10220', 'Sports Legislation', 'Public Hlth, Phys & Sports Sci', 'This module identifies and illustrates aspects of sports law and its particular relevance to sport and the sports industry. It provides an understanding of the current state of interaction between sport and the law. It explores such issues as doping in sport, liability for sport injuries, player image rights and the regulation of sports governing bodies.', 'https://www.ucd.ie/modules/SMGT10220', 'smgt10220'),
    ('36e39bcf-ff83-4675-a8e1-3a78af18a70d', v_uni_id, 'SMGT10240', 'Sport Development', 'Public Hlth, Phys & Sports Sci', 'Sports development is a process whereby opportunities, pathways and structures are put in place to enable people to be generally physically active and / or to participate in competitive sport – whether through casual or organised participation, aimed at improving physical fitness or subjective wellbeing, and /or based on forming social relationships of achieving excellence in competition at regional, national and international levels. This module introduces students to the underlying principles of sports development, the practices of sport development officers, and to the range of outcomes which are aligned to its public health, educational and elite performance goals. Students will be exposed to theories of sports development – to policies and partnerships which characterise local, national and international sports development organisations – and this will be facilitated by means of a range of individual-, group- and inquiry-based modes of learning.', 'https://www.ucd.ie/modules/SMGT10240', 'smgt10240'),
    ('43c45eac-a2d1-4db8-9d3b-fbf16845f9d4', v_uni_id, 'SMGT10260', 'Core Academic Skills for Sport & Exercise', 'Public Hlth, Phys & Sports Sci', 'This module introduces students to a wide range of academic skills that are required to successfully study at university, including extracting meaning from lectures, taking notes, tackling readings, engaging with artificial intelligence, working with and managing quantitative data, conducting research, referencing, critical thinking, and academic writing.', 'https://www.ucd.ie/modules/SMGT10260', 'smgt10260'),
    ('59774885-6552-47ba-b1e8-e4fc58e74b4e', v_uni_id, 'SMGT10290', 'Sport Mega Events', 'Public Hlth, Phys & Sports Sci', 'This module explores the role of sport mega-events like the Olympics and the FIFA world cups in the international sporting, social and political landscape. By considering the origins of modern sport mega-events, the stakeholders behind their organisation and the values and objectives that underpin them, this module examines the nature, management and influence of mega-events in the twenty-first century. Students taking this module will be encouraged to access and analyse a wide range of sources in order to critically assess sport mega-events and their role on sports and society today, to examine the legacy of sport mega-events and to evaluate their sustainability.', 'https://www.ucd.ie/modules/SMGT10290', 'smgt10290'),
    ('51166985-53ae-42d7-9023-6573e8d8454b', v_uni_id, 'SMGT10300', 'Sport Marketing, Branding and Sponsorship', 'Public Hlth, Phys & Sports Sci', 'This module examines the correlation between and application of marketing and branding within sporting contexts. It focuses on the major decisions that marketing executives and management personnel may face in their efforts to harmonise the objectives and resources of organisations with the needs and opportunities in the marketplace. Students should gain a thorough understanding of the theories of marketing and sponsorship as aids in decision-making as well as comprehending the corporate context of marketing as it applies to the sports industry. It examines connections between sports consumers, sponsorship and brand recognition and how social media platforms might be utilised in the application of marketing strategies.', 'https://www.ucd.ie/modules/SMGT10300', 'smgt10300'),
    ('2c06bf31-950e-4da6-be2c-764ca988e4ad', v_uni_id, 'SMGT20010', 'Event Management', 'Public Hlth, Phys & Sports Sci', 'The purpose of this module is to acquire an in depth knowledge about the specialised field of "event management" and to become familiar with management techniques and strategies required for successful planning, promotion, implementation and evaluation of events within a sport context. All course materials including summary lecture notes will be available on Brightspace.', 'https://www.ucd.ie/modules/SMGT20010', 'smgt20010'),
    ('6423ce2d-9f57-4f15-8359-05c0d828bc77', v_uni_id, 'SMGT20030', 'Economics of Sport', 'Public Hlth, Phys & Sports Sci', 'This module develops economic principles within the sports industry together with an understanding of the manner in which economic concepts permeates all aspects of the industry. The module provides an understanding of the national and international economic framework that influences markets and determines the economic environment within which sporting industries operate. The module introduces students to concepts on which the behaviour of all economic agents including; individuals, firms, organisations and governments are based.', 'https://www.ucd.ie/modules/SMGT20030', 'smgt20030'),
    ('0d702dbf-94f4-4674-8d79-c4790c580da9', v_uni_id, 'SMGT20070', 'Sports Tourism', 'Public Hlth, Phys & Sports Sci', 'This module considers the development, scope and social and economic importance of the travel and tourism industry and examines its relationship to the sports industry in Ireland. This module explores issues such as tourist motivations and how tourists'' decisions may be influenced. Finally, this module addresses how new technologies have transformed the nature of both the modern tourist and modern tourist industry.', 'https://www.ucd.ie/modules/SMGT20070', 'smgt20070'),
    ('24a29c88-f80f-48a7-ab9a-14cb1560ce5d', v_uni_id, 'SMGT20080', 'Sports Work Placement', 'Public Hlth, Phys & Sports Sci', 'This module is designed to provide students a bridge between academia and practice, and gain experience in the sport management industry. The work placement is to occur over a minimum period of 6 weeks, during which students are expected to conform to the normal working hours of the host company, and complete a minimum of 200 hours of work.', 'https://www.ucd.ie/modules/SMGT20080', 'smgt20080'),
    ('3bd9564f-bb46-450b-b65e-c5a59e76587c', v_uni_id, 'SMGT20150', 'Strategic Planning in Sport', 'Public Hlth, Phys & Sports Sci', 'This module introduces students to the underlying theories and practices of sports strategy planning and provision of sports facilities and resources. The syllabus includes an examination of the sports industry regulatory framework, the sports strategic planning process and environmental scanning. Students will be able to prepare an environmental scan and develop a strategic plan for a sports facility.', 'https://www.ucd.ie/modules/SMGT20150', 'smgt20150'),
    ('460ec7e0-31f4-47bc-9ea1-15c45dff8f09', v_uni_id, 'SMGT20200', 'Sports HRM', 'Public Hlth, Phys & Sports Sci', 'Organisations can only function if they are able to assemble together people with the necessary knowledge, skills, attitudes and experience to meet objectives. They must also retain effective performers and deal with exit from the organisation, both voluntary and otherwise whilst remaining within the legal framework. This involves actively seeking to manage the performance and contribution of organisational members. As the skills that employers seek become more specialised, employment markets have tightened, leading to increased complexity. This is reflected in an increased number of considerations such as diversity management, employer branding, work–life balance initiatives and innovative approaches to job design. This module considers a variety of activities, aimed at managing the human resource in sporting organisations. It covers the practical aspects of resourcing, talent management, retention, performance management, workplace learning, the legal context of employment, employee relations, diversity management and corporate social responsibility.', 'https://www.ucd.ie/modules/SMGT20200', 'smgt20200'),
    ('62422e44-7204-4c11-a4d2-60fbe1deeda4', v_uni_id, 'SMGT20210', 'Event Management Practicum', 'Public Hlth, Phys & Sports Sci', 'This module provides a practical opportunity to apply skills learned in Event Management and other modules in the core SMGT programme.', 'https://www.ucd.ie/modules/SMGT20210', 'smgt20210'),
    ('058102dc-588c-4543-a1aa-cb83e2f7455a', v_uni_id, 'SMGT20250', 'Psychology of Sport & Exercise', 'Public Hlth, Phys & Sports Sci', 'This module provides students with an introduction to the role of psychology in the promotion of health and improved performance in sport and exercise. It deals with topics such as confidence, motivation, psychological factors influencing exercise participation, and issues surrounding injury rehabilitation. After undertaking this module, students will have developed their understanding and acquired initial skills to assess and critically analyse certain situations within sport, exercise and health settings from a psychological perspective. All course materials including summary lecture notes will be available on Blackboard.', 'https://www.ucd.ie/modules/SMGT20250', 'smgt20250'),
    ('7406653a-3cee-43dc-9a39-046129cf2837', v_uni_id, 'SOC10010', 'Theorising Society: Foundations of Sociological Thought', 'Sociology', 'This is a 1st year module for sociology students. It provides an introduction to some of the main theories that laid the foundation for modern sociology. Sociology developed as an intellectual discipline in the 19th century as writers grappled with their understanding of modern capitalism. Some of the key writers include Karl Marx, Max Weber and Emile Durkheim. The course outlines their central ideas, their relevance for today and encourages students to critically assess them.Students wishing to take Sociology at Stage 2 should take this module.', 'https://www.ucd.ie/modules/SOC10010', 'soc10010'),
    ('b21bc509-5376-43ef-bb2d-a0e9b329647e', v_uni_id, 'SOC10020', 'Introduction to Sociology', 'Sociology', 'This module provides an introduction to sociology as both a field of study and an academic discipline. Organised around key sociological concepts, it explores fundamental aspects of human societies, including inequality, gender, power, culture, and social change. Through these themes, students will critically examine how societies function, evolve, and shape individual and collective experiences. Indicative Content of the Module: 1. What is sociology? 2. Groups and Relationships: Individual, community, and society 3. The Historical Development of Sociology 4. Difference VS inequality 5. Social construction of sexuality and gender 6. Sociological Imagination 7. Authority, power, and discipline 8. Modernity and Post-Modernity 9. Social institutions and social control 10. Culture and Values 11. Social Change 12. Nature VS society By engaging with sociological theories and methodologies, students will develop analytical tools to understand and investigate social structures, relationships, and transformations. Each week is dedicated to a central concept, such as society, inequality, or crisis, allowing for in-depth discussion and application of sociological perspectives. Whether you are new to sociology or looking to deepen your understanding, this module offers a foundational exploration of the key ideas that shape our world.', 'https://www.ucd.ie/modules/SOC10020', 'soc10020'),
    ('6e2d3d20-fe43-43b0-ab6b-53e6de58b082', v_uni_id, 'SOC10060', 'Ireland in Comparative Perspective', 'Sociology', 'Ireland is in a state of ongoing transformation, experiencing rapid and dramatic economic, social and cultural changes in a short period of time. Yet there are structural continuities traced back to modern Irish society before and after independence that underlie and help to explain these changes. This module explores the continuities amidst the significant changes in contemporary Irish society drawing on a comparative perspective. This provides a framework to identify what is similar to the continuities and changes in Ireland compared to other related societies, and what is different in the Irish experience contrasted with other societies. The topics examined in the module include some of the following: periods of boom and bust in Ireland''s development, particularly the Celtic Tiger and current austerity; population, emigration and immigration; inequality, poverty and class; housing; education; labour markets; social networks; religion and secularisation; pluralism and liberalisation; consumerism and individualism; the media; social movements; and nationalism and national identity.', 'https://www.ucd.ie/modules/SOC10060', 'soc10060'),
    ('01db6183-16c2-46af-ad5a-668cd193bdf9', v_uni_id, 'SOC30360', 'Sociology of Migration, Race and Ethnicity', 'Sociology', 'Migration is at the forefront of contemporary debates globally, and has been a centre piece of electoral and political discourses in the Global North since the 1990s. From the so-called “migration crisis” of 2015 in Europe to the Brexit debates on keeping migrants out and to the current anti-immigrant mobilisations in Ireland, the UK, the USA, and elsewhere, migration remains a contentious issue. Often entangled with racism, discourses on migration show us how societies categorise themselves and others, and how they deal with otherness through policies and dynamics of inclusion and exclusion. In this module, we will learn to disentangle the terms used in public, media, and political discourses on migration and race by using concepts and theories from the sociology of migration and race.', 'https://www.ucd.ie/modules/SOC30360', 'soc30360'),
    ('91afee84-2b48-4791-9ca7-d23510535358', v_uni_id, 'SPOL10030', 'Understanding Social Problems and Policies', 'Soc Pol, Soc Wrk & Soc Justice', 'This module seeks to equip you with basic research and analytical skills that are needed to understand and respond to social policy problems. Its main focus is on statistical data available in online databases that are widely used to describe such problems and design policy solutions to them. You will learn about major relevant databases for Ireland and the EU and will receive guidance and hands-on experience on how to access those databases, search through them for data on specific social policy topics, select and extract particular relevant indicators into Excel spreadsheets, present the data in graphs and tables, and write brief descriptive commentaries on what the data reveal. For illustrative purposes, the module will focus on unemployment as a representative social problem and will concentrate on analysing that problem and policy responses to it in Ireland and in the EU. A special focus will be on the impact of Covid-19 on the labour market and its effects on employment and unemployment among younger cohorts in particular.', 'https://www.ucd.ie/modules/SPOL10030', 'spol10030'),
    ('a98949b8-99ca-4057-aa36-56c678a013e8', v_uni_id, 'SSCI20030', 'Building Resilience', 'C.O. - Social Sciences & Law', 'The module introduces students to the various facets of the resilience concept through a trans-disciplinary approach. It also provides skills to deal with challenging situations and potential future crisis. Specifically, we will interrogate and unravel the complexity and depth of resilience using the lens of scientific disciplines such as psychology, archaeology, sociology and social justice. Resilience can refer to a single organism (e.g. forest, human being) or to a system (e.g. community, health system), following exposure to a stressor (e.g. fire, pandemic, work stress). Thus, resilience may encompass processes of recovery, adaptation, transformation and sustainability. The module will cover the following 1) Pre-crisis stage: we will explore the history of social and environmental crisis and how these have differed across cultures and time periods. 2) Crisis stage: we will look at how crisis and shocks unfold and how we are impacted as individuals and groups, such as 9/11, Global warming, COVID-19. 3) Post-crisis: we will look at how groups and societies have recovered from crisis events, drawing out the methods we can use to adjust and find a new equilibrium. Experts from different social science disciplines teach on the module and contribute to understanding and building resilience. Student participation and learning is supported by a variety of tools such as seminars, reflexive exercises, online resources and discussion forums. By the end of the module, students will be able to critically analyse systemic contexts of adversity and the value of resilience in addressing societal challenges of the 21st century.', 'https://www.ucd.ie/modules/SSCI20030', 'ssci20030'),
    ('50487885-b748-46dd-ac3c-5120e81d668e', v_uni_id, 'SSJ10020', 'Global Justice: Towards an Egalitarian Global Order', 'Soc Pol, Soc Wrk & Soc Justice', 'The objective of this module is to equip students with a clear understanding of and critical perspective on global injustices. We will cover a range of related topics, which will normally include global poverty and inequality; colonialism and post-colonialism; debt and development; neoliberal capitalism; trade, transnational corporations and international tax justice; global gender relations; the global fashion industry; migration; ‘race’ and racism; and environmental justice and climate change. The module will encourage and enable students to analyse inequalities across the economic, political, social and cultural spheres of global society, and to think critically about relations of power at a global level. The module will also explore the role of different groups and institutions in creating or challenging systems of global inequality, including the International Financial Institutions, the United Nations, the G8, transnational corporations, the media, development agencies, NGOs, and social movements. In addition, we will explore the ways in which development and global justice issues are represented within a European context. Students will be encouraged to reflect upon their own role within global social systems, as global citizens and future professionals. Ways of potentially creating a more sustainable and egalitarian world will be explored throughout. We encourage you to search for other School of Social Justice (SSJ) modules which include options relating to Equality Studies and Women''s Studies. Graduates who have completed at least 15 credits of undergraduate electives offered by the School of Social Justice will have this noted on their UCD transcripts as the completion of Structured Electives in Social Justice.', 'https://www.ucd.ie/modules/SSJ10020', 'ssj10020'),
    ('dc2d1450-afb2-4f02-a4ce-1df8b12a8d94', v_uni_id, 'STAT10050', 'Practical Statistics', 'Mathematics & Statistics', 'This module focusses on practical statistics and computation in real-world scenarios. Students will cover: - How statistics are used - How to turn data into information - How to create statistical graphics - How to obtain data from surveys and designed experiments - Probability theory and random variables', 'https://www.ucd.ie/modules/STAT10050', 'stat10050'),
    ('1108e75a-7ce9-4427-99b2-3e99411ba7c8', v_uni_id, 'SUST10010', 'Introduction to Sustainability', 'Geography', 'This module introduces the principles of sustainability and its measurement, and provides a broad overview of the major sustainability challenges in water, climate, energy, food and pollution. As part of the module students define sustainability and how it is measured using the Sustainable Development Goals (SDGs). Students also investigate how sustainable development can be promoted at local, regional and national level across different economic sectors (e.g. agriculture, energy generation, urban growth, industry).', 'https://www.ucd.ie/modules/SUST10010', 'sust10010'),
    ('dd10d2b5-0dac-405c-9a1e-b8208ce379ae', v_uni_id, 'SUST10020', 'Sustainability Challenges', 'Science Admin Office', 'Building on GEOG 10150 Introduction to sustainability, this module focuses on three selected sustainability challenges and explores them in more detail. The focal challenges are Energy and Climate, Future Cities and Water. Each will be analysed from the perspectives of each of the three dimensions of sustainability: environment, economy and society. They will be considered from the perspectives of individuals, communities, regions, nations and at a global scale. The emphasis will be on interdisciplinary approaches to developing strategies and solutions and the module will involve group work in interdisciplinary teams, drawing on input and guidance from a range of relevant experts.', 'https://www.ucd.ie/modules/SUST10020', 'sust10020'),
    ('6532a46a-68fb-4fad-808a-8b2ab16fb679', v_uni_id, 'SUST20010', 'Sustainability: Research Tools', 'Geography', 'This module builds on the foundational knowledge built through Introductions to Sustainability (SUST10010) and introduces the pragmatic research theory and practice required to effectively study global sustainability challenges. This includes natural- and social-science techniques across quantitative, qualitative and mixed methodologies. This will be supplemented by a common strand of innovation and creative problem solving throughout.', 'https://www.ucd.ie/modules/SUST20010', 'sust20010'),
    ('fa34acab-e895-4e04-8f7f-6e8224f6ff9c', v_uni_id, 'VET10050', 'Comparative Topographical Anatomy of the Abdomen and Pelvis', 'Veterinary Medicine', 'This module covers the basic anatomy of the structures and contents of the abdominal and pelvic cavities of the domestic veterinary species; including the key structures of the gastrointestinal and urogenital system. This includes their basic function, topographical relationships, attachments, blood supply, innervation and lymphatic drainage. Key principals are emphasised through reference to (a) the developmental progression involved in organogenesis of the structures comprising relevant body systems and (b) practical examples from surgery, pathology and clinical practice with the aid of X-ray plates and USG (ultrasonography). The physics of diagnostic imaging techniques will be introduced.', 'https://www.ucd.ie/modules/VET10050', 'vet10050'),
    ('e896b5c9-5f6d-4f2d-8b03-40ec89c7324a', v_uni_id, 'VET10060', 'Professional Growth 1', 'Veterinary Medicine', 'Pass/Fail (GPA Neutral) This veterinary core module is only available to students registered to the veterinary professional degree programme. This module will introduce students to the professional attributes required to contribute as a productive member of the veterinary profession. Topics covered will include professional standards, fitness to practise, career options, professional regulatory frameworks, communication skills, mindfulness, evidence based veterinary medicine, goal setting, personal financial planning, team-working, problem solving, non-verbal and verbal communication skills and leadership. Many of the issues that impact on professional life will be introduced in peer-to-peer lectures and facilitated discussions which will require active student interaction. Group work will be emphasized with the purpose of building skills in forming a strong working relationship with other members of the veterinary team. Students will be encouraged to reflect on their progress to date, and to set goals for themselves to provide the motivation and direction necessary for personal growth and success. Critical self and peer-assessment also forms part of this module.', 'https://www.ucd.ie/modules/VET10060', 'vet10060'),
    ('0f7ae607-2ae9-4765-8aa2-51aab3078678', v_uni_id, 'VET10080', 'Cell and Whole Body Metabolism', 'Veterinary Medicine', 'This module focuses on the pathways of intermediary metabolism, with particular reference to domestic animals. It describes the main pathways of intermediary metabolism, their relationship to each other, and how they are regulated by hormones. Students learn about macromolecules such as proteins, enzyme activity and regulation, and the main pathways of carbohydrate, amino acid, and lipid metabolism. These pathways are illustrated using examples from various domestic species. This module describes how precursors generated in these pathways are used to generate compounds such as nucleic acids, hormones, and neurotransmitters. The hormonal regulation of metabolic pathways in different species is discussed, with reference to clinical veterinary scenarios. The metabolic function of vitamins and minerals and their relevance to health and disease is discussed in the context of ruminant and monogastric species.', 'https://www.ucd.ie/modules/VET10080', 'vet10080'),
    ('f6371b7b-1813-4b67-b00a-5a0d158c2718', v_uni_id, 'VET10100', 'Intro to the Practical Apps of Veterinary Anatomy & Comparative Topographical Anatomy of the Thorax', 'Veterinary Medicine', 'This module provides an introduction to the practical and applied aspects of veterinary anatomy through small group dissection projects aimed at relating anatomical structures to a clinical, surgical, or biological problem. It will also cover the anatomy of the structures encompassing the walls and contents of the thoracic cavity of farm animal species as well as the dog and cat. Key areas covered include: the structure and function of the thoracic skeleton, thoracic musculature, thoracic cavity and pleura, respiratory system, cardiovascular system, gastro- intestinal tract within the thoracic cavity, innervation of the thoracic cavity and the lymphatic system. It also includes an introduction to: the clinical examination of the thoracic cavity; thoracic radiography and thoracic surgery. ***Please check and be aware if this module is a prerequisite (Academic Regulation 3.27(a)) for any future modules.', 'https://www.ucd.ie/modules/VET10100', 'vet10100'),
    ('cc44514c-c352-4c33-ac35-c7a5fbcf1f05', v_uni_id, 'VET10110', 'Veterinary Cardiovascular and Respiratory Function', 'Veterinary Medicine', 'This module is part of the core course in veterinary medicine. Over the course of this module the veterinary student will gain an in-depth knowledge of the function of the cardiovascular and respiratory systems. Where appropriate, specific reference will be made to clinical conditions of veterinary importance. This module underpins the clinical veterinary course in respiratory and cardiovascular medicine.', 'https://www.ucd.ie/modules/VET10110', 'vet10110'),
    ('21bb4cb2-0a7e-4bd9-a90d-a1b00f4c2234', v_uni_id, 'VET10140', 'The Physiology and Biochemistry of Digestion of Domestic Animals', 'Veterinary Medicine', 'Most of the organic material in the feed consumed by animals consists of macromolecules which must be broken down into smaller molecules before they can be utilised to maintain energy-requiring processes or serve as building blocks for cells and tissues. This module will describe the structure/function relationships and metabolic and regulatory mechanisms controlling the function of GI tract, including liver and pancreas, in animals of veterinary importance including farm animal species as well as the Dog and Cat. ***Please check and be aware if this module is a prerequisite (Academic Regulation 3.27(a)) for any future modules.', 'https://www.ucd.ie/modules/VET10140', 'vet10140'),
    ('1d3ec6c8-6614-4c43-8342-f225dd1357f7', v_uni_id, 'VET10150', 'Basic structure & function', 'Veterinary Medicine', 'In this module first year veterinary students are introduced to the basic tissues of domestic animals. Aspects of cell biology, functional genomics, epigenetics, developmental anatomy (embryology) of the animal as well as the microscopic anatomy (histology) of the main body tissues are examined. Students are required to integrate the principles of integrated structure and function. Developmental biology (including embryology) will be studied up to the formation of the basic mammalian body plan.', 'https://www.ucd.ie/modules/VET10150', 'vet10150'),
    ('7617721c-f65d-4062-a9a7-5c2d513990b9', v_uni_id, 'VET10160', 'Cell Biology & Homeostasis', 'Veterinary Medicine', 'This module focuses on essential principles of cell biology and the physiology of communication and integrated functions of excitable cells with reference to appropriate veterinary examples. The module covers: i) cellular and subcellular structure and function, role of membranes ii) nucleic acids, cell cycle, transcription and translation, post translational modifications iii) practical applications of DNA, RNA & protein (extraction, analysis), including a brief overview of the immune system iv) homeostatic principles v) membrane potential, ion channels, action potential vi) excitable cells vii) synaptic transmission, synaptic potentials, and cellular integration viii) muscle tissue, sliding filament theory, metabolism', 'https://www.ucd.ie/modules/VET10160', 'vet10160'),
    ('a3100a80-39fb-4918-ab8f-e16768227f46', v_uni_id, 'VET10170', 'Introduction to veterinary epidemiology', 'Veterinary Medicine', 'This module introduces epidemiology to veterinary students by presenting topics and principles fundamental to understanding the discipline. The goal is, above all, to communicate to students that epidemiology is an approach to the investigation and understanding of how outcomes are caused in the natural world. Consistent with this, the module’s focus is not to teach about diseases in themselves, but to communicate and demonstrate the approach(es) and type(s) of thinking needed to detect them, quantify their frequency and determine which factors cause or are at least associated with their occurrence. The module explains that epidemiology relates to the study of the distribution and determinants of outcomes in populations. In veterinary medicine, epidemiology is most often used to study the distribution of the determinants of animal diseases or other animal-related outcomes. These “other animal-related outcomes” can include diseases and other conditions relevant to humans, which result from human-animal interactions (e.g. allergies, injuries or even grief after the loss of a pet). Thus, a core part of the module’s content pertains to the definition, calculation and interpretation of measures of disease frequency and measures of effect (Lectures 3-6). Given the important role of biostatistics in making the population-level inferences central to epidemiology, the module also briefly introduces some bio-statistical content that the graduating veterinarian should be exposed to. Particular emphasis is placed on variable types, measures of central tendency and measures of dispersion (Lectures 5, 7-8). Given that epidemiology is a “measurement science”, estimation of the magnitude of measures of effect is emphasized, while the use of p values and Null Hypothesis Significance Testing is explicitly discouraged, in favor of confidence intervals for making epidemiologic inferences (Lectures 8-12). During the module, an attempt is made to communicate that Statistics serves only as an epidemiologic tool, enabling population-level inferences, and is neither synonymous with, nor a foundation of the discipline. The module also contains material aimed at helping veterinary students to draw evidence-based decisions both from clinical practice as well as from the scientific literature. Thus, lectures are dedicated to the application and interpretation of diagnostic tests (Lectures 13-14), as well as sampling, epidemiologic study design and bias (Lectures 16-19, 22). Finally at the end of the module, epidemiology subspecialities (Lectures: 20-21, 23) are introduced, with most attention paid to Infectious Disease Epidemiology, and its particularities, in recognition of its importance to Veterinary Medicine.', 'https://www.ucd.ie/modules/VET10170', 'vet10170'),
    ('cbc1465b-8a8f-491a-a4e6-827a03464d1c', v_uni_id, 'VET10180', 'Animal Husbandry and Practical Skills', 'Veterinary Medicine', 'This module will focus on appropriate procedures to approach, handle, and conduct routine chores on food producing, equine and companion animals. It will consist of a series of introductory lectures and a series of practical classes.', 'https://www.ucd.ie/modules/VET10180', 'vet10180'),
    ('c012f452-7350-44c5-85c2-2fc679dd67f8', v_uni_id, 'VET20030', 'Head & Nervous System of Domestic Animals', 'Veterinary Medicine', 'In this core module the anatomy and physiology of structures of the head will be studied with an emphasis on comparative anatomy (dog/horse/ruminant). The embryological development and histological arrangement of structures of the head, face and neck will also be examined. Clinical and radiological aspects of the region will be underlined. Particular emphasis will be placed on understanding the functioning of the central nervous system and the organs of special sense in order to aid the student in the diagnosis and treatment of diseases of the nervous system.', 'https://www.ucd.ie/modules/VET20030', 'vet20030'),
    ('0a75276a-3484-4acd-be1e-0450715267e9', v_uni_id, 'VET20040', 'Introduction to fluids: blood plasma, urine and milk with an emphasis on basic pharmacokinetics', 'Veterinary Medicine', 'This is a 2nd year core module for the MVB degree. This is the first time students will be exposed to pharmacological concepts in detail, specifically pharmacokinetics. The module integrates and develops understanding of the distribution of water, solutes, and drugs in animals of veterinary significance. Students learn that plasma is composed of water, ions, organic molecules and dissolved gases. Fluid and electrolyte homeostasis requires integration among multiple systems. How kidney function contributes to water balance and regulation of urine concentration is examined. Regulation of (whole body) acid/base balance is described. How body fluids including blood, urine and milk (histology of mammary gland) are used diagnostic purposes is introduced in practical classes. Factors influencing the uptake, distribution and elimination of drugs between compartments (pharmacokinetics) are introduced as part of a discussion of dosing concepts in species. An introduction to diuretics and their mechanism of action is presented based on student knowledge of kidney structure (histology) and function.', 'https://www.ucd.ie/modules/VET20040', 'vet20040'),
    ('04ea2e74-362b-4ae6-9538-83572d0a0888', v_uni_id, 'VET20050', 'Genetics & Animal Breeding', 'Veterinary Medicine', 'This module focuses on the genetics and animal breeding of farm and companion animals. It includes the animal genes; tracking pedigree Mendelian and complex; population genetics; quantitative genetics; heritability/selection; heterosis/inbreeding; molecular genetics of disease and the ways species are selected. It will also include the genetics of dairy, beef, sheep, thoroughbred horses, sport horses and companion animals.', 'https://www.ucd.ie/modules/VET20050', 'vet20050'),
    ('0ba98d14-548a-45bf-8026-622b03a91861', v_uni_id, 'VET20070', 'Veterinary Farm Animal Husbandry and Animal Handling', 'Veterinary Medicine', 'This module consists of a series of lectures and tutorials on the applied practical aspects of husbandry and management of the main farm animal species, including beef, dairy, sheep, pigs and poultry, as well as an introduction to aquaculture, camelid husbandry and honey bee husbandry. There will also be an introduction to herd health, including important production diseases of cattle (mastitis, lameness) as well as infectious disease; there is a similar introduction to flock health and disease. Practical classes in animal handling are offered for farm animal and companion animal species that build on previous programme content. The emphasis is on health and safety for the handler and maintaining low stress scenarios for the animals involved. Students are also facilitated in using routine handling equipment, carrying out important husbandry tasks and procedures such as disbudding of calves. The main purposes of this module are to A) familiarise students with common farming systems and critically important husbandry aspects which have a direct and indirect impact on animal health, animal welfare, productivity and economic performance on farms; B) to emphasize an animal handling approach that recognises and avoids risk to the handler and ensures animal well-being by the use of low stress animal handling where possible, and C) to introduce and familiarise students with basic animal handling techniques, equipment and procedures.', 'https://www.ucd.ie/modules/VET20070', 'vet20070'),
    ('7ea0113d-9da3-4a18-8f10-e667ccdb5c56', v_uni_id, 'VET20080', 'Integrated Physiological Communication', 'Veterinary Medicine', 'This module integrates and develops understanding of how cell-cell and tissue communication is important to animals of veterinary significance. The endocrine system is used as an exemplar of coordinated signalling which incorporates feedback patterns, hormones and hormone receptors, cellular responses and disturbed function (pathologies are used to illustrate selected points).This module also develops the principles of signalling by endogenous substances to the actions of exogenous molecules (drugs, toxins, xenobiotics). This way of thinking is developed into an introduction of pharmacology and specifically, how normal signalling systems lend themselves to regulation by drugs (pharmcodynamics).', 'https://www.ucd.ie/modules/VET20080', 'vet20080');
