-- Seeds the UCD professor/course catalog gathered by a research agent from official
-- ucd.ie module descriptor pages (ratemymodule.ie used only as a lead-generation aid
-- for discovering module codes to then confirm officially — never cited as a source).
-- Generated from .claude/scratch/ucd_courses_seed.json by a one-off script (not checked
-- into the repo — see HANDOFF.md §13 for how to regenerate/extend this).
-- Runs as the privileged migration role, so it bypasses the RLS that otherwise closes
-- professors/courses to direct writes (see 20260902270000_reviews_core.sql).
do $$
declare
  v_uni_id uuid;
begin
  select id into v_uni_id from public.universities where slug = 'ucd';



end $$;
